        Buff_Content_100 = {
          ContentDE = "Hochgefährliche Gegner werden unverwundbar, sobald ihre LP unter #1 fallen, und bleiben es #2 Sek. lang; zugleich erscheinen Verstärkungen. Beim Besiegen eines Gegners wird der verursachte Schaden aller Verbündeten um #3 erhöht, bis zu #4-mal stapelbar. Wird eine bestimmte Anzahl an Gegnern besiegt, endet die Unverwundbarkeit vorzeitig.",
          TextMapId = "Buff_Content_100"
        },
        Buff_Content_11111 = {
          ContentDE = "Der erlittene SCH aller Gegner wird um #1 verringert. Jedes Mal, wenn sie Schaden von einem anderen Verbündeten als zuvor erleiden, wird dieser Effekt um #2 verringert.",
          TextMapId = "Buff_Content_11111"
        },
        Buff_Content_11113 = {
          ContentDE = "Wenn Verbündete von anderen Verbündeten geheilt werden, wird ihre Angriffs-GES um #1 und Fähigkeits-GES für #3 Sek. um #2 erhöht, bis zu #4-mal stapelbar. Gewährt bei maximalen Stapelungen Immunität gegen Trefferstarre.",
          TextMapId = "Buff_Content_11113"
        },
        Buff_Content_11121 = {
          ContentDE = "Für jeden Verlust von #1 % der maximalen LP wird der KRIT-Rate der Verbündeten um #2 für #3 Sek. erhöht, bis zu #4-mal stapelbar.",
          TextMapId = "Buff_Content_11121"
        },
        Buff_Content_11122 = {
          ContentDE = "Der verursachte Waffen-SCH aller Verbündeten wird um #1 verringert. Der KRIT-SCH wird um #2 erhöht.",
          TextMapId = "Buff_Content_11122"
        },
        Buff_Content_11211 = {
          ContentDE = "Liegt die LP eines Verbündeten über #1, wird sein Fähigkeits-SCH um #2 erhöht und er wird immun gegen Trefferstarre.",
          TextMapId = "Buff_Content_11211"
        },
        Buff_Content_11212 = {
          ContentDE = "Der verursachte KRIT-SCH aller Verbündeten wird um #1 verringert. Der DoT wird um #2 erhöht.",
          TextMapId = "Buff_Content_11212"
        },
        Buff_Content_11221 = {
          ContentDE = "Nach dem Einsatz eines Nahkampfangriffs wird der Waffen-SCH aller Verbündeten für #2 Sek. erhöht, bis zu #3-mal stapelbar. Gewährt bei maximalen Stapelungen Immunität gegen Trefferstarre.",
          TextMapId = "Buff_Content_11221"
        },
        Buff_Content_11222 = {
          ContentDE = "Der verursachte SCH aller Verbündeten wird um #1 verringert. Der KRIT-Rate wird um #2 erhöht.",
          TextMapId = "Buff_Content_11222"
        },
        Buff_Content_201 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie Fähigkeits-SCH oder Waffen-SCH erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_201"
        },
        Buff_Content_202 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie KRIT-SCH erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_202"
        },
        Buff_Content_203 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie Fernkampfwaffen-SCH erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_203"
        },
        Buff_Content_204 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie Waffen-SCH erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_204"
        },
        Buff_Content_205 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie Nahkampfwaffen-SCH erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_205"
        },
        Buff_Content_206 = {
          ContentDE = "Der erlittene SCH der gegnerischen Einheiten wird um #1 reduziert. Jedes Mal, wenn sie DoT erleiden, verringert sich dieser Effekt um #2.",
          TextMapId = "Buff_Content_206"
        },
        Buff_Content_211 = {
          ContentDE = "Gegner stellen alle 3 Sek. #1 ihres maximalen Schilds wieder her. Die Wiederherstellung pausiert, solange ein elementarer Bonuseffekt aktiv ist.",
          TextMapId = "Buff_Content_211"
        },
        Buff_Content_30 = {
          ContentDE = "Für je #1 verursachte Schadensinstanzen einer beliebigen Verbündeten wird der ANG um #2 erhöht, hält #3 Sek. an, bis zu #4-mal stapelbar.",
