        Content_Batt02_01_01 = {
          ContentDE = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt, bemerkst du einen Fremden vor dir. Sprich mit ihm und erfahre, was geschehen ist.",
          TextMapId = "Content_Batt02_01_01"
        },
        Content_Batt02_01_02 = {
          ContentDE = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Von Herrn Qiu getrennt triffst du einen Mann namens Kezhou. Eure Schicksale sind nun miteinander verwoben – setzt euren Weg gemeinsam fort, um einen Ausweg zu finden.",
          TextMapId = "Content_Batt02_01_02"
        },
