        Content_Batt03_03_01 = {
          ContentDE = "Vom Beutetier geweckt, erhebt sich die prächtige Vielfach-Fangjagd-Formation aus der Erde und fängt dich in seinem uralten Mechanismus ein.\n Der Ausgang liegt vor dir – entkomme!",
          TextMapId = "Content_Batt03_03_01"
        },
        Content_Nai01_01_01 = {
          ContentDE = "Von einem Hilferuf angezogen bist du in den Vergessensspalt gefallen — ein lichtloses Reich, in dem alles ins Vergessen gleitet.\n Finde einen Ausweg, bevor du diejenigen vergisst, die dir am Herzen liegen.",
          TextMapId = "Content_Nai01_01_01"
        },
        Content_Nai02_01_01 = {
          ContentDE = "{nickname} ist fürs Erste in Sicherheit, doch Fushu, die zu ihrer Rettung eilte, ist nun selbst in Gefahr geraten.\n Die Verbindung zwischen dem Vergessensspalt und der Außenwelt wird immer schwächer. Beeil dich – finde einen Ausweg, solange du noch kannst.",
          TextMapId = "Content_Nai02_01_01"
        },
        Content_Nai03_01_01 = {
          ContentDE = "Fushus Geist war noch von Zweifel getrübt, und sie konnte dem Äolischen Klangspiel keine Antwort entlocken — sodass sie dem Vergessensspalt nicht entkommen konnte. Zum Glück fand sie mit der Hilfe des Wishen endlich ihren Weg zurück, und eine längst vergessene Erinnerung erwachte erneut.\n Jetzt, da Fushu wieder bei dir ist, bleibt keine Zeit zum Ausruhen. Mach weiter und finde den Ausgang aus diesem Ort.",
          TextMapId = "Content_Nai03_01_01"
        },
