        FeinaEvent_DungeonDes_1 = {
          ContentDE = "Fina betritt eine Märchenwelt und besucht das Haus des Großen Magiers, nur um festzustellen, dass er nicht da ist. Folge den Spuren, die er hinterlassen hat, und finde den Ausgang aus der Höhle.",
          TextMapId = "FeinaEvent_DungeonDes_1"
