        FeinaEvent_DungeonDes_2 = {
          ContentDE = "Hinter sich lässt Fina die düstere Höhle und betritt ein verworrenes Labyrinth. Fürchte dich nicht vor tückischen Fallen oder verschlungenen Wegen – mit der Hilfe {性别:des klugen Herrn|der klugen Frau} Einhorn wird sie jedes Rätsel lösen können.",
          TextMapId = "FeinaEvent_DungeonDes_2"
