        MOD_ATTR_ExtraComboLevel = {
          ContentDE = "Beim Ausführen eines geladenen Angriffs wird die Kombostufe um #1 erhöht.",
          TextMapId = "MOD_ATTR_ExtraComboLevel"
        },
        MOD_ATTR_ExtraComboProb = {
          ContentDE = "Beim Erhalten eines Kombopunkts durch Angriffe besteht eine Chance von #1, einen zusätzlichen Kombopunkt zu erhalten.",
          TextMapId = "MOD_ATTR_ExtraComboProb"
        },
        MOD_DESC_101001 = {
          ContentDE = "Verändert die Standardangriffe des Schwerts. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_101001"
        },
        MOD_DESC_101002 = {
          ContentDE = "Verändert das geladene Angriff des Schwerts. Im Vergleich zum originalen Angriffsmodus wird der Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_101002"
        },
        MOD_DESC_101003 = {
          ContentDE = "Verändert den geladenen Angriff des Schwerts. Der geladene Angriff wirft eine Blitzklinge, die nach kurzer Verzögerung in einem großen Bereich explodiert. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_101003"
        },
        MOD_DESC_102001 = {
          ContentDE = "Verändert den geladenen Angriff der Stangenwaffe. Der geladene Angriff wirft 5 Stangenwaffen nach vorne und trifft alle Gegner auf dem Weg. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_102001"
        },
        MOD_DESC_102002 = {
          ContentDE = "Verändert die Standardangriffe der Stangenwaffe. Beschwört Phantomspeere, die das Ziel treffen. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_102002"
        },
        MOD_DESC_102003 = {
          ContentDE = "Verändert die Standardangriffe der Stangenwaffe. Beschwört Phantomspeere, die das Ziel treffen. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_102003"
        },
        MOD_DESC_102004 = {
          ContentDE = "Verändert den geladenen Angriff der Stangenwaffe. Der geladene Angriff stürmt vorwärts und trifft alle Gegner auf dem Weg. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_102004"
        },
        MOD_DESC_103001 = {
          ContentDE = "Verändert die Standardangriffe des Großschwerts. Der letzte Angriff des Standardangriffs erzeugt 3 Schwertwellen, die alle Gegner auf dem Weg treffen. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_103001"
        },
        MOD_DESC_103002 = {
          ContentDE = "Verändert den geladenen Angriff des Großschwerts. Während des Aufladens kann sich die Figur bewegen und unterwegs kontrollierbare Gegner erfassen (bis zu 4). Durch Verbrauch von Kombopunkten kann die Bewegungsdauer verlängert werden. Beim Loslassen der Angriffstaste oder nach Ablauf der Dauer wird ein großflächiger Angriff ausgelöst. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_103002"
        },
        MOD_DESC_103003 = {
          ContentDE = "Verändert die Standardangriffe der Stangenwaffe. Beschwört Phantomspeere, die das Ziel treffen. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.Erhöhen",
          TextMapId = "MOD_DESC_103003"
        },
        MOD_DESC_104001 = {
          ContentDE = "Verändert den Gleitangriff der Doppelklingen. Die Figur stürmt nach vorn und trifft alle Gegner auf dem Weg. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_104001"
        },
        MOD_DESC_104002 = {
          ContentDE = "Verändert die Standardangriffe der Doppelklingen. Die Klingen werden kombiniert und für einen rotierenden Angriff eingesetzt. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_104002"
        },
        MOD_DESC_104003 = {
          ContentDE = "Verändert den geladenen Angriff der Doppelklingen. Die Klingen werden kombiniert und nach vorne geworfen, wodurch Gegner entlang der Flugbahn getroffen werden. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_104003"
        },
        MOD_DESC_106001 = {
          ContentDE = "Verändert den geladenen Angriff des Katanas. Nach einem Treffer springt die Figur in die Luft und führt einen herabstürzenden Schlag aus, der mehreren Gegnern in der Umgebung mehrfachen Schaden zufügt. Im Vergleich zum originalen Angriffsmodus wird die Gesamtstärke um 100 % erhöht.",
          TextMapId = "MOD_DESC_106001"
        },
        MOD_DESC_1311 = {
          ContentDE = "Der erlittene SCH wird um #1 reduziert. Beim Besiegen eines Gegners wird der ANG um #2 für #3 s erhöht, bis zu #4-mal stapelbar. Die Dauer des Effekts wird bei jeder neuen Stapelung aktualisiert.",
          TextMapId = "MOD_DESC_1311"
        },
        MOD_DESC_1312 = {
          ContentDE = "Erhöht die Fähigkeits-SCH zu Kampfbeginn in Missionen oder Nocturne-Echos für #2 s um #1.",
          TextMapId = "MOD_DESC_1312"
        },
        MOD_DESC_1313 = {
          ContentDE = "Erhöht den verursachten SCH um #1, wenn sich weniger als 2 Gegner im Umkreis von 20 m befinden.",
          TextMapId = "MOD_DESC_1313"
        },
        MOD_DESC_1314 = {
          ContentDE = "Erhöht den verursachten SCH pro Gegner im Umkreis von 20 m um #1, bis zu #2.",
          TextMapId = "MOD_DESC_1314"
        },
        MOD_DESC_1315 = {
          ContentDE = "Erhöht den verursachten SCH um #1 beim Angriff auf Gegner mit vollständig geschwächter Kampfhaltung.",
          TextMapId = "MOD_DESC_1315"
        },
        MOD_DESC_1316 = {
          ContentDE = "Erhöht den ANG bei jeder Wiederbelebung in Missionen oder Nocturne-Echos um #1, bis zu #2.",
          TextMapId = "MOD_DESC_1316"
        },
        MOD_DESC_1400 = {
          ContentDE = "Moral: Je höher der LP-Prozentsatz, desto höher der verursachte SCH, bis zu #1.",
          TextMapId = "MOD_DESC_1400"
        },
        MOD_DESC_1410 = {
          ContentDE = "Entschlossenheit: Je niedriger der LP-Prozentsatz, desto höher der verursachte SCH, bis zu #1.",
          TextMapId = "MOD_DESC_1410"
        },
        MOD_DESC_1420 = {
          ContentDE = "Der Fähigkeits-SCH wird um #1 reduziert. Waffenangriffe verursachen zusätzlich #2 Schaden desselben Elementtyps.",
          TextMapId = "MOD_DESC_1420"
        },
        MOD_DESC_1430 = {
