        },
        Message_Guide_ModLevelUp_1 = {
          ContentDE = "Eine Erhöhung der <H>Stufe der Dämonenkeile</> kann Daimonen und Waffen weiter verstärken.",
          TextMapId = "Message_Guide_ModLevelUp_1"
        },
        Message_Guide_ModLevelUp_4 = {
          ContentDE = "Wähle einen Dämonenkeil",
          TextMapId = "Message_Guide_ModLevelUp_4"
        },
        Message_Guide_ModLevelUp_4_Pad = {
          ContentDE = "Drücke, um einen Dämonenkeil auszuwählen",
          TextMapId = "Message_Guide_ModLevelUp_4_Pad"
        },
        Message_Guide_ModLevelUp_5 = {
          ContentDE = "Wähle „Dämonenkeil hochstufen“",
          TextMapId = "Message_Guide_ModLevelUp_5"
        },
        Message_Guide_ModLevelUp_5_Pad = {
          ContentDE = "Drücke, um „Dämonenkeil hochstufen“ auszuwählen",
          TextMapId = "Message_Guide_ModLevelUp_5_Pad"
        },
        Message_Guide_ModLevelUp_6 = {
          ContentDE = "Das Hochstufen von Dämonenkeilen <H>erhöht deine Kampfkraft beträchtlich</>.",
          TextMapId = "Message_Guide_ModLevelUp_6"
        },
        Message_Guide_ModLevelUp_7 = {
          ContentDE = "Das Hochstufen eines Dämonenkeils <H>erhöht die für ihn erforderliche Toleranz</>. Achte darauf, dass die gesamte erforderliche Toleranz nach dem Hochstufen des Dämonenkeils <H>nicht</> die <H>Toleranz-Obergrenze</> überschreitet.",
          TextMapId = "Message_Guide_ModLevelUp_7"
        },
        Message_Guide_ModTendency_1 = {
          ContentDE = "Die der Figur innewohnende Spur kann mithilfe von <H>Spurwechselmodulen</> angepasst werden.",
          TextMapId = "Message_Guide_ModTendency_1"
        },
        Message_Guide_ModTendency_10 = {
          ContentDE = "Wenn du einen mächtigen Dämonenkeil besitzt, aber Probleme mit einer <H>inkompatiblen Spur</> hast, solltest du <H>die Spur des Platzes anpassen</>.",
          TextMapId = "Message_Guide_ModTendency_10"
        },
        Message_Guide_ModTendency_11 = {
          ContentDE = "Wenn die Spur des Platzes einer Figur mit der Spur eines Dämonenkeils <H>übereinstimmt</>, <H>verringert</> sich die <H>Toleranz</>, die für das Ausrüsten dieses Dämonenkeils erforderlich ist.",
          TextMapId = "Message_Guide_ModTendency_11"
        },
        Message_Guide_ModTendency_4 = {
          ContentDE = "Wähle den Dämonenkeil-Platz",
          TextMapId = "Message_Guide_ModTendency_4"
        },
        Message_Guide_ModTendency_4_Pad = {
          ContentDE = "Drücke, um einen Dämonenkeil-Platz auszuwählen",
          TextMapId = "Message_Guide_ModTendency_4_Pad"
        },
        Message_Guide_ModTendency_5 = {
          ContentDE = "Wähle „Platz-Spur anpassen“",
          TextMapId = "Message_Guide_ModTendency_5"
        },
        Message_Guide_ModTendency_5_Pad = {
          ContentDE = "Drücke, um „Platz-Spur anpassen“ auszuwählen",
          TextMapId = "Message_Guide_ModTendency_5_Pad"
        },
        Message_Guide_ModTendency_6 = {
          ContentDE = "Du kannst <H>Spurwechselmodule</> verwenden, um die innewohnende <H>Spur</> des Dämonenkeil-Platzes einer Figur hinzuzufügen, anzupassen oder zu eliminieren.",
          TextMapId = "Message_Guide_ModTendency_6"
        },
        Message_Guide_ModTendency_7 = {
          ContentDE = "Ärgert dich die limitierte Toleranzobergrenze, die mehr Dämonenkeil-Konfigurationen verhindert? Achte auf die <H>Spur</>!",
          TextMapId = "Message_Guide_ModTendency_7"
        },
        Message_Guide_ModTendency_8 = {
          ContentDE = "Alle Figuren oder Waffen haben bestimmte Eigenschaften, die zu verschiedenen <H>Spuren</> für ihre <H>Dämonenkeil-Plätze</> führen.",
          TextMapId = "Message_Guide_ModTendency_8"
        },
        Message_Guide_ModTendency_9 = {
          ContentDE = "Um <H>Dämonenkeile</> effektiver einsetzen zu können, wurden einige speziell mit einer <H>Spur</> hergestellt, die für bestimmte Figuren maßgeschneidert wurde.",
          TextMapId = "Message_Guide_ModTendency_9"
        },
        Message_Guide_Mod_1 = {
          ContentDE = "<H>Dämonenkeile</>, hergestellt von der Spathatoi aus Hyperborea, sind tragbare Komponenten, die die Kraft von Daimonen und Waffen erheblich verstärken, sobald sie ausgerüstet sind.",
          TextMapId = "Message_Guide_Mod_1"
        },
        Message_Guide_Mod_10 = {
          ContentDE = "Wähle einen Dämonenkeil aus, um dir seine Effekte anzusehen",
          TextMapId = "Message_Guide_Mod_10"
        },
        Message_Guide_Mod_11 = {
          ContentDE = "Verbrauche <H>Münzen</> und <H>Karminkügelchen</>, um Dämonenkeile <H>hochzustufen</> und ihre Kräfte deutlich zu verstärken. Allerdings erhöht das Hochstufen von Dämonenkeilen auch die Belastung für den Träger – dabei kann die Toleranzobergrenze für das Ausrüsten überschritten werden.",
          TextMapId = "Message_Guide_Mod_11"
        },
        Message_Guide_Mod_12 = {
          ContentDE = "Hier kannst du schnell zwischen Figuren und Waffen wechseln, um ihre Dämonenkeile bei Bedarf anzupassen.",
          TextMapId = "Message_Guide_Mod_12"
        },
        Message_Guide_Mod_13 = {
          ContentDE = "Ein Figuren-Dämonenkeil kann von mehreren Figuren genutzt werden. Ebenso kann der gleiche Waffen-Dämonenkeil bei mehreren Waffen eingesetzt werden.",
          TextMapId = "Message_Guide_Mod_13"
        },
        Message_Guide_Mod_14 = {
          ContentDE = "Du solltest deine Figure und Waffen <H>hochstufen</>, um ihre Toleranzobergrenzen zu erhöhen.",
          TextMapId = "Message_Guide_Mod_14"
        },
        Message_Guide_Mod_15 = {
          ContentDE = "Klick hier, um Dämonenkeile automatisch auszurüsten",
          TextMapId = "Message_Guide_Mod_15"
        },
        Message_Guide_Mod_16 = {
          ContentDE = "Halte <H>&ShowCursor&</> gedrückt, um den Mauszeiger einzublenden, und wähle dann <H>Kampf</> um das Menü „Kampftraining“ zu öffnen.",
          TextMapId = "Message_Guide_Mod_16"
        },
        Message_Guide_Mod_16_Pad = {
          ContentDE = "Tippe auf das <H>Kampftraining</>-Symbol, um das Menü „Kampftraining“ zu öffnen.",
          TextMapId = "Message_Guide_Mod_16_Pad"
        },
        Message_Guide_Mod_2 = {
          ContentDE = "Wähle „Dämonenkeile“ zum Ausrüsten",
          TextMapId = "Message_Guide_Mod_2"
        },
        Message_Guide_Mod_2_Pad = {
          ContentDE = "Drücke, um einen Dämonenkeil zum Ausrüsten auszuwählen",
          TextMapId = "Message_Guide_Mod_2_Pad"
        },
        Message_Guide_Mod_3 = {
          ContentDE = "Es gibt zwei Arten von Dämonenkeilen: <H>Figuren-Dämonenkeile</> und <H>Waffen-Dämonenkeile</>, und sie sind nicht untereinander austauschbar.",
          TextMapId = "Message_Guide_Mod_3"
        },
        Message_Guide_Mod_4 = {
          ContentDE = "Dämonenkeile bieten verschiedene Verstärkungseffekte – sie müssen <H>in Plätzen ausgerüstet werden</>, damit sie funktionieren.",
          TextMapId = "Message_Guide_Mod_4"
        },
        Message_Guide_Mod_5 = {
          ContentDE = "Lass <H>Charaktere aufsteigen</>, um mehr Plätze freizuschalten",
          TextMapId = "Message_Guide_Mod_5"
        },
        Message_Guide_Mod_6 = {
          ContentDE = "Dämonenkeile besitzen gewaltige Kräfte und belasten ihren Träger daher sehr.",
          TextMapId = "Message_Guide_Mod_6"
        },
        Message_Guide_Mod_7 = {
          ContentDE = "In der <H>oberen linken Ecke</> wird die <H>erforderliche Toleranz</> dieses Dämonenkeils angezeigt.",
          TextMapId = "Message_Guide_Mod_7"
        },
        Message_Guide_Mod_8 = {
          ContentDE = "Wenn Toleranz noch nicht die Obergrenze erreicht hat, kannst du einen Dämonenkeil in einen leeren Platz ziehen, um ihn auszurüsten.",
          TextMapId = "Message_Guide_Mod_8"
        },
        Message_Guide_Mod_9 = {
          ContentDE = "Die <H>Toleranz</> ist die Belastbarkeit von Figuren und Waffen gegenüber Dämonenkeilen. Die Zahl unten zeigt die Toleranzgrenze einer Figur oder Waffe.",
          TextMapId = "Message_Guide_Mod_9"
        },
        Message_Guide_OnlineAreaPre_1 = {
          ContentDE = "Schließe „Schwarzes Eisen & Weiße Blume“ des Kapitels Nachtfahrer ab, um den Koop-Funktionen freizuschalten. In speziellen Koop-Bereichen kannst du andere Spieler aus verschiedenen Zeiten treffen.",
          TextMapId = "Message_Guide_OnlineAreaPre_1"
        },
        Message_Guide_OnlineAreaPre_2 = {
          ContentDE = "Nachdem du die Koop-Funktionen freigeschaltet hast, werden manche Bereiche zu Koop-Bereichen. Wenn du diese Bereiche betrittst, wird automatisch der Mehrspieler-Modus aktiviert. Wenn du sie verlässt, wird er deaktiviert.",
          TextMapId = "Message_Guide_OnlineAreaPre_2"
        },
        Message_Guide_OnlineAreaPre_3 = {
