        },
        Message_Guide_OnlineArea_1 = {
          ContentDE = "Einige Bereiche sind Koop-Bereiche, in denen du auf Spieler aus verschiedenen Zeitlinien treffen kannst.",
          TextMapId = "Message_Guide_OnlineArea_1"
        },
        Message_Guide_OnlineArea_2 = {
