        },
        Message_Guide_PetTrain_3 = {
          ContentDE = "Wähle <H>Eigenschaft</>",
          TextMapId = "Message_Guide_PetTrain_3"
        },
        Message_Guide_PetTrain_3_Pad = {
          ContentDE = "Drücke, um dir ihre <H>Eigenschaften</> anzusehen",
          TextMapId = "Message_Guide_PetTrain_3_Pad"
        },
        Message_Guide_PetTrain_4 = {
          ContentDE = "Geniemon sind in <H>aktive Geniemon</> und <H>inaktive Geniemon</> unterteilt. Aktive Geniemon haben Eigenschaft-Plätze, die beim Aufsteigen allmählich freigeschaltet werden.",
          TextMapId = "Message_Guide_PetTrain_4"
        },
        Message_Guide_PetTrain_5 = {
          ContentDE = "Die Eigenschaft-Stufe der Geniemon kann über <H>Aufsteigen</> erhöht werden. Über <H>Geniemon-Training</> kannst du sogar Eigenschaften zwischen Geniemon übertragen.",
          TextMapId = "Message_Guide_PetTrain_5"
        },
        Message_Guide_PetTrain_6 = {
          ContentDE = "Inaktive Geniemon können nicht am Kampf teilnehmen, aber ihre Eigenschaften können von anderen Geniemon durch Geniemon-Training erlernt werden.",
          TextMapId = "Message_Guide_PetTrain_6"
        },
        Message_Guide_PetTrain_7 = {
          ContentDE = "Im Eigenschaftskompendium kannst du alle Geniemon-Eigenschaften einsehen und die automatische Sperre für neu erworbene Geniemons mit ausgewählten Eigenschaften ein- oder ausschalten.",
          TextMapId = "Message_Guide_PetTrain_7"
        },
        Message_Guide_PetTraits_1 = {
          ContentDE = "Du hast einen <H>inaktiven Geniemon</> erhalten. Schau ihn dir im Geniemon-Menü an.",
          TextMapId = "Message_Guide_PetTraits_1"
        },
        Message_Guide_PetTraits_2 = {
          ContentDE = "Klicke, um zu den <H>inaktiven Geniemon</> umzuschalten.",
          TextMapId = "Message_Guide_PetTraits_2"
        },
        Message_Guide_PetTraits_2_Pad = {
          ContentDE = "Drücke, um zu den <H>inaktiven Geniemon</> umzuschalten.",
          TextMapId = "Message_Guide_PetTraits_2_Pad"
        },
        Message_Guide_PetTraits_4 = {
          ContentDE = "Klicke, um zu den <H>aktiven Geniemon</> umzuschalten.",
          TextMapId = "Message_Guide_PetTraits_4"
        },
        Message_Guide_PetTraits_4_Pad = {
          ContentDE = "Drücke, um zu den <H>aktiven Geniemon</> umzuschalten.",
          TextMapId = "Message_Guide_PetTraits_4_Pad"
        },
        Message_Guide_PetTraits_5 = {
          ContentDE = "Geniemon sind in <H>aktive Geniemon</> und <H>inaktive Geniemon</> unterteilt. Aktive Geniemon haben Eigenschaft-Plätze, die beim Aufsteigen allmählich freigeschaltet werden.",
          TextMapId = "Message_Guide_PetTraits_5"
        },
        Message_Guide_PetTraits_6 = {
          ContentDE = "Erhalte Geniemon-Eigenschaft durch <H>Geniemon-Training</>.",
          TextMapId = "Message_Guide_PetTraits_6"
        },
        Message_Guide_PetTraits_6_Pad = {
          ContentDE = "Erhalte Geniemon-Eigenschaft durch <H>Geniemon-Training</>.",
          TextMapId = "Message_Guide_PetTraits_6_Pad"
        },
        Message_Guide_PetTraits_7 = {
          ContentDE = "Klicke, um einen <H>inaktiven Geniemon</> als Trainingspartner hinzuzufügen, damit andere seine Eigenschaft erben können.",
          TextMapId = "Message_Guide_PetTraits_7"
        },
        Message_Guide_PetTraits_7_Pad = {
