          TextMapId = "Message_Guide_PetTraits_7_Pad"
        },
        Message_Guide_Pet_01 = {
          ContentDE = "Wähle „Geniemon füttern”.",
          TextMapId = "Message_Guide_Pet_01"
        },
        Message_Guide_Pet_02 = {
          ContentDE = "Du kannst Geniemon mit Leckereien unterschiedlicher Qualität anlocken. Je höher die Qualität, desto höher sind deine Chancen, dich mit einem Geniemon anzufreunden.",
          TextMapId = "Message_Guide_Pet_02"
        },
        Message_Guide_Pet_03 = {
          ContentDE = "Das Füttern zum richtigen Zeitpunkt erhöht deine Chancen, besonders wenn du auf den <H>zentralen Punkt</> zielst.",
          TextMapId = "Message_Guide_Pet_03"
        },
        Message_Guide_Pet_04 = {
          ContentDE = "Wähle hier, um zu füttern",
          TextMapId = "Message_Guide_Pet_04"
        },
        Message_Guide_Pet_05 = {
          ContentDE = "Wenn der richtige Zeitpunkt gekommen ist, drück auf <H>Drücken</>, um das Leckerei zu werfen.",
          TextMapId = "Message_Guide_Pet_05"
        },
        Message_Guide_Pet_06 = {
          ContentDE = "Du hast dich erfolgreich mit diesem Geniemon angefreundet! Gehe zu <H>Bewaffnung</>, um dir deinen neuen Kumpel anzusehen.",
          TextMapId = "Message_Guide_Pet_06"
        },
        Message_Guide_Pet_07 = {
          ContentDE = "Wähle hier, um das <H>Geniemon</>-Menü zu öffnen",
