        },
        Message_Guide_Pet_09 = {
          ContentDE = "Hier kannst du deine Geniemon ansehen und füttern",
          TextMapId = "Message_Guide_Pet_09"
        },
        Message_Guide_Pet_10 = {
          ContentDE = "Wähle hier, um das ausgewählte Geniemon in den Kampf mitzunehmen.",
