        Message_Guide_Quest_1 = {
          ContentDE = "Wenn du nicht weißt, was du als Nächstes tun sollst, helfen dir vielleicht die <H>Auftragsnotizen</> weiter!",
          TextMapId = "Message_Guide_Quest_1"
        },
        Message_Guide_Quest_2_PC = {
          ContentDE = "Halte <H>&ShowCursor&</> gedrückt, um den Mauszeiger einzublenden, und wähle dann <H>Auftrag</>, um dir die Auftragsnotizen anzusehen.",
          TextMapId = "Message_Guide_Quest_2_PC"
        },
        Message_Guide_Quest_2_Pad = {
          ContentDE = "Drücke, um die Auftragsnotizen zu öffnen",
          TextMapId = "Message_Guide_Quest_2_Pad"
        },
        Message_Guide_Quest_2_Phone = {
          ContentDE = "Wähle <H>Auftrag</>, um dir die Auftragsnotizen anzusehen.",
          TextMapId = "Message_Guide_Quest_2_Phone"
        },
        Message_Guide_Quest_3 = {
          ContentDE = "Die Auftragsnotizen zeigen dir Details zu allen laufenden Aufträgen. Die <H>Auftragsnavigation</> kann dir helfen, Auftragsziele zu finden. Vergiss nicht, dass du für manche Aufträge bestimmte Freischaltbedingungen erfüllen musst, um weitermachen zu können.",
          TextMapId = "Message_Guide_Quest_3"
        },
        Message_Guide_Quest_4 = {
