        },
        NumPadTwo = {ContentDE = "Num 2", TextMapId = "NumPadTwo"},
        NumPadZero = {ContentDE = "Num 0", TextMapId = "NumPadZero"},
        One = {ContentDE = "1.0", TextMapId = "One"},
        PET_401_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Umbro-ANG +#1, Max. LP +#2]],
          TextMapId = "PET_401_PASSIVE"
        },
        PET_401_SKILL = {
          ContentDE = "Verursacht Umbro-SCH in Höhe von #1 des ANG der Hauptfigur an Gegnern innerhalb der Reichweite, mit einem zusätzlichen zufälligen attributbasierten Effekt für #2 Sek.",
