        },
        PhantomTalk_1503_Chest = {
          ContentDE = "Einige Schätze hier wären zu schade, um sie in der Erde zu lassen, nimm sie mit.",
          TextMapId = "PhantomTalk_1503_Chest"
        },
        PhantomTalk_160101_Chest = {
          ContentDE = "Nun, was für eine angenehme Überraschung.",
          TextMapId = "PhantomTalk_160101_Chest"
        },
        PhantomTalk_1601_Chest = {
          ContentDE = "Nun, was für eine angenehme Überraschung.",
          TextMapId = "PhantomTalk_1601_Chest"
        },
        PhantomTalk_1801_Chest = {
          ContentDE = "Finas Freunde sagen, sie riechen den Schatz des Königs.",
          TextMapId = "PhantomTalk_1801_Chest"
        },
        PhantomTalk_2101_Chest = {
          ContentDE = "Romantik braucht gelegentliche Überraschungen. Schau, hier ist eine.",
          TextMapId = "PhantomTalk_2101_Chest"
        },
        PhantomTalk_2301_Chest = {
          ContentDE = "Etwas Schönes gefunden. Hehe, willst du raten, was drin ist?",
          TextMapId = "PhantomTalk_2301_Chest"
        },
        PhantomTalk_2401_Chest = {
          ContentDE = "Unerwartetes Glück auf dem Land. Genug, um ein paar Heiltränke zu kaufen.",
          TextMapId = "PhantomTalk_2401_Chest"
        },
        PhantomTalk_3101_Chest = {
          ContentDE = "Unerwartete Beute? Sieht aus, als hätten wir Glück.",
          TextMapId = "PhantomTalk_3101_Chest"
        },
        PhantomTalk_3102_Chest = {
          ContentDE = "Wie ich schon sagte – beim Aufräumen gibt es gelegentlich Überraschungen.",
          TextMapId = "PhantomTalk_3102_Chest"
        },
        PhantomTalk_3103_Chest = {
          ContentDE = "Äh ... Oliver meint, hier liegt etwas Glänzendes in der Nähe.",
          TextMapId = "PhantomTalk_3103_Chest"
        },
        PhantomTalk_3201_Chest = {
          ContentDE = "Ungerechtes Eigentum? Nimm es, das widerspricht der Gerechtigkeit nicht.",
          TextMapId = "PhantomTalk_3201_Chest"
        },
        PhantomTalk_3202_Chest = {
          ContentDE = "Glück ist auch eine Möglichkeit, Reichtum anzuhäufen. Nimm diese Dinge an.",
          TextMapId = "PhantomTalk_3202_Chest"
        },
        PhantomTalk_3301_Chest = {
          ContentDE = "Ich rieche Schätze! Heute ist wohl ein guter Fang!",
          TextMapId = "PhantomTalk_3301_Chest"
        },
        PhantomTalk_4101_Chest = {
          ContentDE = "Umgebung abgesucht, einige zurückgelassene Vorräte gefunden.",
          TextMapId = "PhantomTalk_4101_Chest"
        },
        PhantomTalk_4102_Chest = {
          ContentDE = "Erde unten, Feuer oben – Gold durch Arbeit geboren. Die Zeichen haben nicht getäuscht.",
          TextMapId = "PhantomTalk_4102_Chest"
        },
        PhantomTalk_4201_Chest = {
          ContentDE = "Solche weltlichen Dinge sind für mich nutzlos, nimm sie dir.",
          TextMapId = "PhantomTalk_4201_Chest"
        },
        PhantomTalk_4202_Chest = {
          ContentDE = "Schatz? Schön, wenn man ihn gegen einen freien Tag eintauschen könnte.",
          TextMapId = "PhantomTalk_4202_Chest"
        },
        PhantomTalk_4301_Chest = {
          ContentDE = "Herumliegende Schätze? Hmph. An Beute, die sich nicht wehrt, habe ich kein Interesse.",
          TextMapId = "PhantomTalk_4301_Chest"
        },
        PhantomTalk_5101_Chest = {
          ContentDE = "Filbert hat etwas gefunden? Moment, das ist kein Essen! Spuck es aus!",
          TextMapId = "PhantomTalk_5101_Chest"
        },
        PhantomTalk_5102_Chest = {
          ContentDE = "Schau, was ich gefunden habe! Wie immer – jeder die Hälfte?",
          TextMapId = "PhantomTalk_5102_Chest"
        },
        PhantomTalk_5301_Chest = {
          ContentDE = "Diese kleine Schachtel – verbirgt sie die Erinnerungen von jemandem?",
          TextMapId = "PhantomTalk_5301_Chest"
        },
        PhantomTalk_5401_Chest = {
          ContentDE = "Einige Vorräte gefunden, erst einmal auffüllen, bevor wir weitermachen?",
          TextMapId = "PhantomTalk_5401_Chest"
        },
