        },
        QuestDesc_10020101 = {
          ContentDE = "An jenem schicksalhaften Tag auf der Purgatorio-Insel stand dir das Glück zur Seite, und du hast noch einen weiteren Tag erlebt. Als du wieder erwachst, ist Berenica weg und du findest dich in einer unbekannten verschneiten Landschaft wieder.\n Eine in Rot gekleidete Dame, die sich als Camilla vorstellte, lud dich zusammen mit einem Mädchen namens Snow ein, mit nach Icelake zu kommen.\n Nach reiflicher Überlegung hast du dich entschieden, dich ihnen anzuschließen ...",
          TextMapId = "QuestDesc_10020101"
        },
        QuestDesc_10020102 = {
          ContentDE = "An jenem schicksalhaften Tag auf der Purgatorio-Insel stand dir das Glück zur Seite, und du hast noch einen weiteren Tag erlebt. Als du wieder erwachst, ist Berenica weg und du findest dich in einer unbekannten verschneiten Landschaft wieder.\n Eine in Rot gekleidete Dame, die sich als Camilla vorstellte, lud dich zusammen mit einem Mädchen namens Snow ein, mit nach Icelake zu kommen.\n Nach reiflicher Überlegung hast du dich entschieden, dich ihnen anzuschließen ...",
          TextMapId = "QuestDesc_10020102"
        },
        QuestDesc_10020103 = {
          ContentDE = "Das umgestürzte Gefährt und die auf der Brücke verstreute Ladung haben Filthoiden angelockt. Schlage diese ungebetenen Besucher in die Flucht.",
          TextMapId = "QuestDesc_10020103"
        },
        QuestDesc_10020104 = {
          ContentDE = "Nachdem du die Filthoiden vertrieben hast, setzt du mit Snow deine Reise nach Icelake fort.",
          TextMapId = "QuestDesc_10020104"
        },
        QuestDesc_10020105 = {
          ContentDE = "Trotz eines kleinen Problems mit dem Wachmann, der den Reisepass überprüfte, konnte Frau Camilla durch geschickte Verhandlungen dafür sorgen, dass die Einreise nach Icelake gesichert war.",
          TextMapId = "QuestDesc_10020105"
        },
        QuestDesc_10020106 = {
          ContentDE = "Frau Camilla schlägt vor, dass du im Hypnos’ Haus übernachtest.\n Trotz der unheimlichen Geschichten beschließt du, dich näher damit zu beschäftigen ...",
          TextMapId = "QuestDesc_10020106"
        },
        QuestDesc_10020107 = {
          ContentDE = "Frau Camilla schlägt vor, dass du im Hypnos’ Haus übernachtest.\n Trotz der unheimlichen Geschichten beschließt du, dich näher damit zu beschäftigen ...",
          TextMapId = "QuestDesc_10020107"
        },
        QuestDesc_10020108 = {
          ContentDE = "Henrik, der Besitzer von Hypnos’ Haus, ist ein nachdenklicher und zurückhaltender Mann.\n Nachdem ihn ein beherztes junges Mädchen überredet hat, bietet er dir widerwillig eine Bleibe für die Nacht an.\n Es wird Zeit, das Haus aufzusuchen, von dem das Mädchen erzählt hat.",
          TextMapId = "QuestDesc_10020108"
        },
        QuestDesc_10020109 = {
          ContentDE = "Henrik, der Besitzer von Hypnos’ Haus, ist ein nachdenklicher und zurückhaltender Mann.\n Nachdem ihn ein beherztes junges Mädchen überredet hat, bietet er dir widerwillig eine Bleibe für die Nacht an.\n Es wird Zeit, das Haus aufzusuchen, von dem das Mädchen erzählt hat.",
          TextMapId = "QuestDesc_10020109"
        },
        QuestDesc_10020110 = {
          ContentDE = "Ein seltener Moment der Ruhe. Es ist Zeit, deine drängenden Fragen zu klären und einen Überblick über die aktuelle Situation zu bekommen.",
          TextMapId = "QuestDesc_10020110"
        },
        QuestDesc_10020111 = {
          ContentDE = "Du hast ein paar Fragen an Psyche.",
          TextMapId = "QuestDesc_10020111"
        },
        QuestDesc_10020112 = {
          ContentDE = "Bevor du den Auftrag, Berenica zu finden, antrittst, musst du etwas Geld besorgen und einen Reisepass erwerben.\n Psyche verrät dir, dass du in der von Camilla betriebenen Taverne „Die Asphodel“ Bargeld durch Aufträge verdienen kannst – ganz ohne Reisepass.",
          TextMapId = "QuestDesc_10020112"
        }
      }
    end
  },
  {
    MinKey = "QuestDesc_10020201",
    MaxKey = "QuestDesc_1003plus35",
    Loader = function()
      return {
        QuestDesc_10020201 = {
          ContentDE = "Bevor du den Auftrag, Berenica zu finden, antrittst, musst du etwas Geld besorgen und einen Reisepass erwerben.\n Psyche verrät dir, dass du in der von Camilla betriebenen Taverne „Die Asphodel“ Bargeld durch Aufträge verdienen kannst – ganz ohne Reisepass.",
          TextMapId = "QuestDesc_10020201"
        },
        QuestDesc_10020202 = {
          ContentDE = "Bevor du den Auftrag, Berenica zu finden, antrittst, musst du etwas Geld besorgen und einen Reisepass erwerben.\n Psyche verrät dir, dass du in der von Camilla betriebenen Taverne „Die Asphodel“ Bargeld durch Aufträge verdienen kannst – ganz ohne Reisepass.",
          TextMapId = "QuestDesc_10020202"
        },
        QuestDesc_10020203 = {
          ContentDE = "Auf dem Platz wurdest du Zeuge einer Gräueltat – das ist bei den Charons mit ihren einzigartigen Hörnern und Stacheln ganz normal.\n Da du Camilla, die für dich gebürgt hat, nicht in Schwierigkeiten bringen wolltest, hast du den Mund gehalten.\n Weiter zur Asphodel.",
          TextMapId = "QuestDesc_10020203"
        },
        QuestDesc_10020204 = {
          ContentDE = "Das Müllmädchen Margie stößt auf einige Schwierigkeiten.\n Frag sie, was los ist.",
          TextMapId = "QuestDesc_10020204"
        },
        QuestDesc_10020205 = {
          ContentDE = "Das Müllmädchen Margie stößt auf einige Schwierigkeiten.\n Frag sie, was los ist.",
          TextMapId = "QuestDesc_10020205"
        },
        QuestDesc_10020206 = {
          ContentDE = "Das Müllmädchen Margie wurde von einem Dieb ausgeraubt.\n Hilf ihr, ihre Geldtasche wiederzufinden. Nicht nur, um ihr zu helfen, sondern auch, um Camillas Test zu bestehen.",
          TextMapId = "QuestDesc_10020206"
        },
        QuestDesc_10020207 = {
          ContentDE = "Das Müllmädchen Margie wurde von einem Dieb ausgeraubt.\n Nachdem du die Asphodel verlassen hast, frag auf dem Platz herum, ob jemand den Dieb gesehen hat.",
          TextMapId = "QuestDesc_10020207"
        },
        QuestDesc_10020208 = {
          ContentDE = "Ein alter Mann namens Badi in der Nähe des Platzes behauptet, den Dieb gesehen zu haben.\n Er schlägt vor, in der Nähe von Mülleimer 3 zu suchen.",
          TextMapId = "QuestDesc_10020208"
        },
        QuestDesc_10020209 = {
          ContentDE = "Tatsächlich findest du in der Nähe des Mülleimers Spuren des Diebes, die zum Dach führen.\n Gehe dort hinauf, um weiter nachzuforschen.",
          TextMapId = "QuestDesc_10020209"
        },
        QuestDesc_10020210 = {
          ContentDE = "Du hast das Dach erreicht. Durchsuche den Bereich nach Spuren des Diebes.",
          TextMapId = "QuestDesc_10020210"
        },
        QuestDesc_10020211 = {
          ContentDE = "Du hast den Dieb auf dem Dach gestellt, aber er ist plötzlich geflohen.\n Es gibt keine Zeit zu verlieren – jage ihm hinterher! Warte, irgendetwas scheint in der Nähe des Gullys nicht zu stimmen ...",
          TextMapId = "QuestDesc_10020211"
        },
        QuestDesc_10020212 = {
          ContentDE = [[
Du folgst der Spur in die Kanalisation, wo der Dieb Fallen aufgestellt hat, um dich zu aufzuhalten.
 Finde einen Weg, diese Mechanismen zu deaktivieren, und setze die Verfolgung fort.]],
          TextMapId = "QuestDesc_10020212"
        },
        QuestDesc_10020213 = {
          ContentDE = [[
Du hast es geschafft, die Schalter umzulegen und den Wasserstand erfolgreich zu senken.
 Zeit, die Verfolgung fortzusetzen.]],
          TextMapId = "QuestDesc_10020213"
        },
        QuestDesc_10020213_1 = {
          ContentDE = "Der Dieb hat eine Reihe vorbereiteter Fallen gestellt. Margie und Snow wurden überrascht und erlitten ein paar Treffer.\n Durchsuche weiter die Gegend – er kann nicht weit sein.",
          TextMapId = "QuestDesc_10020213_1"
        },
        QuestDesc_10020214 = {
          ContentDE = "Der Dieb hat mit einem kleinen Gerät einen dichten Nebel erzeugt und ist darin verschwunden. Du brauchst einen Ersatzschlüssel, um die Verfolgung fortzusetzen.",
          TextMapId = "QuestDesc_10020214"
        },
        QuestDesc_10020215 = {
          ContentDE = [[
Endlich hast du den Dieb wiedergefunden. Dieses Mal wird er dir nicht entkommen.
 Besiege den Dieb und nimm ihn fest.]],
          TextMapId = "QuestDesc_10020215"
        },
        QuestDesc_10020221 = {
          ContentDE = "Du hast Margies Auftrag erfüllt. Gehe zurück zur Asphodel, um deine Belohnung zu erhalten.",
          TextMapId = "QuestDesc_10020221"
        },
        QuestDesc_10020222 = {
          ContentDE = "Alle Aufträge für Phoxjäger findest du auf dem Auftragsbrett in die Asphodel. Schau es dir mal an.",
          TextMapId = "QuestDesc_10020222"
        },
        QuestDesc_10020223 = {
          ContentDE = "Wells hat dich missverstanden und sich blamiert. Er hat beschlossen, dir einen Drink zu spendieren, um sich zu entschuldigen ...",
          TextMapId = "QuestDesc_10020223"
        },
        QuestDesc_10020224 = {
          ContentDE = "Das Geniemon-System ist jetzt freigeschaltet. Fange einen Geniemon, der dich auf deiner weiteren Reise unterstützen wird.",
          TextMapId = "QuestDesc_10020224"
        },
        QuestDesc_10020301 = {
          ContentDE = "Henrik, der Besitzer von Hypnos’ Haus, hat eine hohe Belohnung auf die Rückholung des Kristallo von Stella aus der Glevum-Grube ausgesetzt.\n Die Belohnung deckt deine Reisekosten in den Süden perfekt ab, also beschließt du, das Risiko einzugehen ...",
          TextMapId = "QuestDesc_10020301"
        },
        QuestDesc_10020302 = {
          ContentDE = "Psyche beschließt, sich unserer Reise anzuschließen, um uns den Weg zur Glevum-Grube zu zeigen.\n Mach dich mit Psyche auf den Weg zur Glevum-Grube.",
          TextMapId = "QuestDesc_10020302"
        },
        QuestDesc_10020303 = {
          ContentDE = "Psyche scheint sich entschieden zu haben – sie begleitet dich auf diesem kleinen „Abenteuer“.\n Mach dich mit Psyche auf den Weg zur Glevum-Grube.",
          TextMapId = "QuestDesc_10020303"
        },
        QuestDesc_10020304 = {
          ContentDE = [[
Die Tore der Glevum-Grube sind seit langem verschlossen.
 Sucht nach einem alternativen Weg.]],
          TextMapId = "QuestDesc_10020304"
        },
        QuestDesc_10020305 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern.\n Erforsche die Tiefen dieser verlassenen Mine, um den von Henrik gesuchten Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020305"
        },
        QuestDesc_10020306 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern.\n Erforsche die Tiefen dieser verlassenen Mine, um den von Henrik gesuchten Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020306"
        },
        QuestDesc_10020307 = {
          ContentDE = "Ihr habt es bis in die Glevum-Grube geschafft, aber ein verschlossenes Tor versperrt euch den Weg.\n Durchsuche die Umgebung – vielleicht gibt es eine Möglichkeit, es zu öffnen.\n \n ...\n Ein Phoxjäger erwähnte einst in seinem Tagebuch Tunnellampen und Wegweiser.\n Wenn du etwas Zeit übrig hast, könntest du sie wiederherstellen – vielleicht erleuchten sie den Weg für jene, die nach dir kommen.",
          TextMapId = "QuestDesc_10020307"
        },
        QuestDesc_10020308 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern.\n Filthoiden versperren euch den Weg. Besiege sie und gehe weiter.",
          TextMapId = "QuestDesc_10020308"
        },
        QuestDesc_10020309 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern.\n Betätige den Mechanismus, um die Tür zu öffnen, und erkunde die Tiefen dieser verlassenen Mine, um das von Henrik gesuchte Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020309"
        },
        QuestDesc_10020310 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern.\n Erforsche die Tiefen dieser verlassenen Mine, um den von Henrik gesuchten Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020310"
        },
        QuestDesc_10020311 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern. Doch die losen Steine und scharfen, gezackten Kristallspitzen, die überall verstreut liegen, deuten auf Gefahren hin.\n Erforsche die Tiefen dieser verlassenen Mine, um den von Henrik gesuchten Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020311"
        },
        QuestDesc_10020312 = {
          ContentDE = "Ihr durchquert die verlassenen Tunnel und gelangt in die Tiefen der Glevum-Grube.\n Wo einst ein majestätischer Himmelbaum stand, sind nach Jahren der Ausbeutung nur winzige Überreste seiner Wurzeln übrig geblieben, die an eine längst vergangene Zeit des Überflusses erinnern. Doch die losen Steine und scharfen, gezackten Kristallspitzen, die überall verstreut liegen, deuten auf Gefahren hin.\n Erforsche die Tiefen dieser verlassenen Mine, um den von Henrik gesuchten Kristallo von Stella zu finden.",
          TextMapId = "QuestDesc_10020312"
        },
        QuestDesc_10020313 = {
          ContentDE = [[
Deine Ankunft hat den riesigen Filthoid geweckt, der in den Tiefen der Glevum-Grube lebt.
 Nun, da es so weit gekommen ist, besteht die erste Aufgabe darin, ihn zu besiegen.]],
          TextMapId = "QuestDesc_10020313"
        },
        QuestDesc_10020314 = {
          ContentDE = [[
Unter dem furchterregenden Leichnam des riesigen Filthoid liegt ein Edelstein, der im Sternenlicht leuchtet.
 Hebe ihn auf und nimm ihn mit.]],
          TextMapId = "QuestDesc_10020314"
        },
        QuestDesc_10020315 = {
          ContentDE = "Dein erstes Abenteuer in der Glevum-Grube ist erfolgreich zu Ende gegangen – trotz der unangenehmen Komplikationen mit Outsider.\n Outsider hat den Kristallo von Stella mitgenommen. Er scheint unbedingt mit dir reden zu wollen. Du hast zugestimmt, ihn in seiner Residenz zu treffen.",
          TextMapId = "QuestDesc_10020315"
        },
        QuestDesc_10020316 = {
          ContentDE = "Dein erstes Abenteuer in der Glevum-Grube ist erfolgreich zu Ende gegangen – trotz der unangenehmen Komplikationen mit Outsider.\n Outsider hat den Kristallo von Stella mitgenommen. Er scheint unbedingt mit dir reden zu wollen. Du hast zugestimmt, ihn in seiner Residenz zu treffen.\n Währenddessen wartet jemand am Tor von Icelake – und er sieht nicht besonders erfreut aus ...",
          TextMapId = "QuestDesc_10020316"
        },
        QuestDesc_10020401 = {
          ContentDE = "Outsider bat um ein exklusives Treffen, also ging Snow zuerst.\n Laut Outsider ist sein Zuhause in den Slums, gekennzeichnet durch einen Vogel an der Tür.",
          TextMapId = "QuestDesc_10020401"
        },
        QuestDesc_10020402 = {
          ContentDE = "Du wurdest zu einer bescheidenen, aber netten „Teeparty” mit Outsider und seiner Schwester Fina eingeladen.\n Nach dem Essen wollte Outsider ein paar ernste Sachen mit dir unter vier Augen besprechen.",
          TextMapId = "QuestDesc_10020402"
        },
        QuestDesc_10020403 = {
          ContentDE = "Du wurdest zu einer bescheidenen, aber netten „Teeparty” mit Outsider und seiner Schwester Fina eingeladen.\n Nach dem Essen wollte Outsider ein paar ernste Sachen mit dir unter vier Augen besprechen.",
          TextMapId = "QuestDesc_10020403"
        },
        QuestDesc_10020404 = {
          ContentDE = "Als Gegenleistung für einen Reisepass bat dich Outsider, Hypnos’ Haus unter dem Vorwand zu untersuchen, den Kristallo von Stella zu liefern.\n Aber zuerst eine wohlverdiente Pause.",
          TextMapId = "QuestDesc_10020404"
        },
        QuestDesc_10020405 = {
          ContentDE = "Laut Outsider könnte das von Henrik geführte Hypnos’ Haus schreckliche Geheimnisse bergen – \n ein Phoxjäger namens Hunt soll innerhalb seiner Mauern verschwunden sein.\n Du hast beschlossen, dieses Gasthaus zu untersuchen.",
          TextMapId = "QuestDesc_10020405"
        },
        QuestDesc_10020406 = {
          ContentDE = "Henrik öffnete widerwillig die Tür wegen des Kristallo von Stella.\n Zeit, sich auf die Suche zu begeben.",
          TextMapId = "QuestDesc_10020406"
        },
        QuestDesc_10020407 = {
          ContentDE = "Henrik ging zurück in sein Büro, um die Echtheit des Kristallos zu überprüfen. Jetzt hast du die Chance, das Gasthaus zu erkunden.\n Psyche hat dich gerade begrüßt. Schau zuerst bei ihr vorbei.",
          TextMapId = "QuestDesc_10020407"
        },
        QuestDesc_10020408 = {
          ContentDE = "Du hast ein Geschenk von Psyche bekommen. Sie meinte, dass Blumen Glück bringen würden.\n Du hast auch erfahren, dass alle Gäste in Hypnos’ Haus an irgendeiner Krankheit leiden und Henrik anscheinend heimlich etwas erforscht.\n Untersuche besser einige andere Bereiche des Gasthauses.",
          TextMapId = "QuestDesc_10020408"
        },
        QuestDesc_10020409 = {
          ContentDE = "Die Gäste von Hypnos’ Haus scheinen eine ungewöhnliche Gruppe zu sein. Frage herum und finde heraus, was sie über Henrik wissen.",
          TextMapId = "QuestDesc_10020409"
        },
        QuestDesc_10020410 = {
          ContentDE = "Du hast erfahren, dass Henriks verschlossenes Büro in diesem Gebäude tabu ist.\n Du hast erfahren, dass Henrik jeden Monat am 20. um 17 Uhr das Haus verlässt.\n Du hast bestätigt, dass Hunt, der vermisste Phoxjäger, tatsächlich einmal hier gewohnt hat.\n Henrik sollte jeden Moment zurück sein.",
          TextMapId = "QuestDesc_10020410"
        },
        QuestDesc_10020411 = {
          ContentDE = "Obwohl du nicht in das Büro gelangen konntest, hast du einige nützliche Informationen gesammelt.\n Gehe zurück und teile deine Erkenntnisse mit Outsider.",
          TextMapId = "QuestDesc_10020411"
        },
        QuestDesc_10020412 = {
          ContentDE = "Obwohl du nicht in das Büro gelangen konntest, hast du einige nützliche Informationen gesammelt.\n Gehe zurück und teile deine Erkenntnisse mit Outsider.",
          TextMapId = "QuestDesc_10020412"
        },
        QuestDesc_10020501 = {
          ContentDE = "Bis zum 20. ist noch viel Zeit.\n Schau dir das Auftragsbrett in die Asphodel an und schließe Mission: Vermittlung ab, um etwas Erfahrung zu erlangen.",
          TextMapId = "QuestDesc_10020501"
        },
        QuestDesc_10020502 = {
          ContentDE = "Während du dich allmählich in der Stadt einlebst und lernst, wie man {性别:ein Phoxjäger|eine Phoxjägerin} wird ...\n In Dismania, der kaiserlichen Hauptstadt, schmiedet die Legion Pläne.",
          TextMapId = "QuestDesc_10020502"
        },
        QuestDesc_10020503 = {
          ContentDE = "Außerhalb von Icelake beschäftigt sich Outsider damit, Fallen auf einer Lichtung in den Außenbezirken aufzubauen, während er auf dich wartet.\n Vielleicht solltest du nachsehen, was er vorhat.",
          TextMapId = "QuestDesc_10020503"
        },
        QuestDesc_10020504 = {
          ContentDE = "Besiege gemäß Outsiders Anweisungen die herannahenden Filthoiden, um dein Training abzuschließen.",
          TextMapId = "QuestDesc_10020504"
        },
        QuestDesc_10020504_1 = {
          ContentDE = "Du hast alle Filthoiden besiegt. Sprich mit Outsider.",
          TextMapId = "QuestDesc_10020504_1"
        },
        QuestDesc_10020505 = {
          ContentDE = "Outsider hat irgendwie eine Gruppe Filthoiden angelockt.\n Nun, es bringt nichts, sich zu beschweren – hilf ihm einfach, sich um sie zu kümmern.",
          TextMapId = "QuestDesc_10020505"
        },
        QuestDesc_10020505_1 = {
          ContentDE = "Du hast dich mit Outsider zum Phoxjäger-Training in den Außenbezirken verabredet, aber Outsider hat irgendwie eine Menge Filthoiden angelockt.\n Nachdem du dich um die Filthoiden gekümmert hast, schau mal nach, was er vorhat.",
          TextMapId = "QuestDesc_10020505_1"
        },
        QuestDesc_10020506 = {
          ContentDE = "Laut Outsider geht es in der nächsten Runde des Trainings darum, dieses laut dröhnende Gerät zu beschützen.\n Sorge einfach dafür, dass die Filthoiden es nicht beschädigen.",
          TextMapId = "QuestDesc_10020506"
        },
        QuestDesc_10020507 = {
          ContentDE = "Henrik sollte bald das Haus verlassen.\n Triff dich mit Snow in der Nähe von Hypnos’ Haus, der die Aufgabe hat, Henrik heimlich zu beobachten.",
          TextMapId = "QuestDesc_10020507"
        },
        QuestDesc_10020601 = {
          ContentDE = "Henrik sollte bald das Haus verlassen.\n Triff dich mit Snow in der Nähe von Hypnos’ Haus, der die Aufgabe hat, Henrik heimlich zu beobachten.",
          TextMapId = "QuestDesc_10020601"
        },
        QuestDesc_10020602 = {
          ContentDE = "Henrik scheint sich auf den Weg außerhalb der Stadt zu machen.\n Folge ihm, um zu sehen, was er vorhat.",
          TextMapId = "QuestDesc_10020602"
        },
        QuestDesc_10020603 = {
          ContentDE = "Henrik hält bei einem Blumenladen, kauft ein Blumensträußchen und setzt seinen Weg fort.\n Folge ihm.",
          TextMapId = "QuestDesc_10020603"
        },
        QuestDesc_10020604 = {
          ContentDE = "Outsider ist über den Schornstein in den verschlossenen Raum eingedrungen.\n Erforsche die Geheimnisse dieses Raums.",
          TextMapId = "QuestDesc_10020604"
        },
        QuestDesc_10020605 = {
          ContentDE = "Du und Snow habt Henriks Kiste entdeckt, die unter Wasser versteckt war.\n Der Inhalt scheint sich aufgelöst zu haben.\n Gehe zurück und schau nach, was Outsider herausgefunden hat.",
          TextMapId = "QuestDesc_10020605"
        },
        QuestDesc_10020606 = {
          ContentDE = "Outsider hat sich in Henriks Büro geschlichen und ein Dokument mit dem Titel „Das Projekt ‚Schlummer‘“ gefunden.\n Das Dokument enthält eine Liste mit Namen von Personen, die verschwunden sind, und auch Psyche steht auf dieser Liste.\n Es sieht so aus, als könnte Henrik Psyche etwas antun. Aus Sorge um ihre Sicherheit beschließt du, einzugreifen und begibst dich nach Hypnos’ Haus, um weitere Nachforschungen anzustellen.",
          TextMapId = "QuestDesc_10020606"
        },
        QuestDesc_10020607 = {
          ContentDE = "Du hörst leises Schluchzen aus Psyches Zimmer. Sieh nach ihr.",
          TextMapId = "QuestDesc_10020607"
        },
        QuestDesc_10020608 = {
          ContentDE = "Aus irgendeinem Grund scheint Psyche aufgebracht zu sein, obwohl Henrik einfordert, sie fühle sich nur etwas unwohl.\n Da du das Bedürfnis nach einem privaten Gespräch verspürst, lädst du sie zu einem Spaziergang am Klagenden See ein. Der liegt direkt außerhalb von Icelake. Gehe jetzt mit Psyche spazieren.",
          TextMapId = "QuestDesc_10020608"
        },
        QuestDesc_10020609 = {
          ContentDE = "Du merkst, dass Psyche stark sehbehindert ist, aber sie will nicht darüber reden.\n Psyche möchte, dass du sie zu den alten Baumwurzeln am Klagenden See begleitest, einem Ort, der voller Kindheitserinnerungen für sie ist.",
          TextMapId = "QuestDesc_10020609"
        },
        QuestDesc_10020610 = {
          ContentDE = "Laut Psyche verbirgt sich unter diesen Wurzeln ein Geheimnis. Es ist Zeit, es zu lüften.",
          TextMapId = "QuestDesc_10020610"
        },
        QuestDesc_10020611 = {
          ContentDE = "Psyche hat dir die Kamera gegeben, die sie als Kind vergraben hat. Sie selbst kann nichts mehr sehen, hofft aber, dass du die Welt durch das Objektiv festhältst.\n Es scheint, als hätte Psyche noch mehr auf dem Herzen. Gehe mit ihr am Klagenden See spazieren und hör ihr zu.",
          TextMapId = "QuestDesc_10020611"
        },
        QuestDesc_10020612 = {
          ContentDE = "Dein Gespräch mit Psyche wird plötzlich durch Henriks Ankunft unterbrochen. Du hast Psyche gesagt, dass du um 2 Uhr morgens am Ticketschalter auf sie warten wirst.\n Jetzt ist es Zeit, nach Icelake zurückzukehren und dich auf ihre Rettung vorzubereiten.",
          TextMapId = "QuestDesc_10020612"
        },
        QuestDesc_10020613 = {
          ContentDE = "Auf dem Weg zurück nach Icelake triffst du auf einen verdächtigen Soldaten. Erschrocken von deiner Anwesenheit greift er dich ohne Vorwarnung an ...",
          TextMapId = "QuestDesc_10020613"
        },
        QuestDesc_10020614 = {
          ContentDE = "Eine Runde „freundschaftlicher” Faustkampf beruhigte den Soldaten namens Kevin.\n Er scheint etwas zu sagen zu haben.",
          TextMapId = "QuestDesc_10020614"
        },
        QuestDesc_10020615 = {
          ContentDE = "Kevin gestand, dass er heimlich einen Verdorbenen begraben wollte, der früher sein Nachbar war. Er bat dich, dies geheim zu halten.\n Er erklärte dir auch, was „Verderbnis“ ist, und erzählte dir Henriks Hintergrundgeschichte.\n Mit diesen neuen Infos beschließt du, nach Icelake zurückzukehren, um mit Outsider und Snow darüber zu reden.",
          TextMapId = "QuestDesc_10020615"
        },
        QuestDesc_10020701 = {
          ContentDE = "Die Nacht ist hereingebrochen. Wie versprochen triffst du Psyche um 2 Uhr morgens am Ticketschalter südlich von Hypnos' Haus. Outsider scheint bereit zu sein.\n Es gibt keine Zeit zu verlieren. Begib dich jetzt zum Treffpunkt.",
          TextMapId = "QuestDesc_10020701"
        },
        QuestDesc_10020702 = {
          ContentDE = "Auf dem Weg zu Psyche ertönt plötzlich ein Schrei aus Richtung von Hypnos’ Haus – es klingt wie Snow.\n Es läuft dir kalt den Rücken herunter und du willst unbedingt herausfinden, woher der Schrei kommt.",
          TextMapId = "QuestDesc_10020702"
        },
        QuestDesc_10020703 = {
          ContentDE = "Laut Snow zeigt Psyche Anzeichen von Verderbnis. Unterdessen bittet dich ein Junge aus Hypnos’ Haus, Henrik zu helfen.\n Folge dem Jungen nach Hypnos’ Haus, um die Situation zu verstehen.",
          TextMapId = "QuestDesc_10020703"
        },
        QuestDesc_10020704 = {
          ContentDE = "Das normalerweise verschlossene Büro in der Erdetage von Hypnos’ Haus steht jetzt weit offen, was darauf hindeutet, dass Henriks Büro der Mittelpunkt des aktuellen Vorfalls ist.",
          TextMapId = "QuestDesc_10020704"
        },
        QuestDesc_10020705 = {
          ContentDE = "Schwer verletzt offenbart Henrik in seinen letzten Augenblicken die Wahrheit und bittet dich, Psyche zu retten, die ihren Verstand verloren hat. Das ist der gemeinsame Wunsch aller in Hypnos’ Haus.\n Snow weist dir den Weg, wohin Psyche geflohen ist. Begib dich nach Klagendem See, um sie zu finden.",
          TextMapId = "QuestDesc_10020705"
        },
        QuestDesc_10020706 = {
          ContentDE = "Schmetterlinge flattern entlang des Weges, den Psyche genommen hat, als wollten sie dich führen.\n Folge ihnen, um sie zu finden.",
          TextMapId = "QuestDesc_10020706"
        },
        QuestDesc_10020707 = {
          ContentDE = "Den Schmetterlingen folgend gelangst du nach Klagendem See, wo heftige Winde dir den Weg versperren wollen.\n Zum Glück folgen die Böen einem Muster. Bleibe wachsam und überquere vorsichtig den See.",
          TextMapId = "QuestDesc_10020707"
        },
        QuestDesc_10020708 = {
          ContentDE = "Psyches Zustand verschlechtert sich. Als du sie endlich einholst, hat sie sich in ein Filthoid namens „Die Schlüpfende“ verwandelt.\n Besiege „Die Schlüpfende“ und wecke Psyche aus ihrem Schlaf.",
          TextMapId = "QuestDesc_10020708"
        },
        QuestDesc_10020709 = {
          ContentDE = "Psyche liegt schlafend im Auge des Sturms. Inmitten der heulenden Winde spürst du die Grausamkeit des Schicksals, doch deine Hände setzen ihre Bemühungen fort.\n Am Ende kannst du dem schlafenden Mädchen nur einen Blumenstrauß anbieten.",
          TextMapId = "QuestDesc_10020709"
        },
        QuestDesc_10020801 = {
          ContentDE = "Der Schneesturm lässt plötzlich nach und Psyche findet sich an einem vertrauten Ort wieder ...",
          TextMapId = "QuestDesc_10020801"
        },
        QuestDesc_10020802 = {
          ContentDE = "Vor ihr erstreckt sich ein Korridor, der aus Erinnerungen gewebt ist. Am Ende liegt ein vertrauter und doch seltsamer Schatten aus der Vergangenheit.",
          TextMapId = "QuestDesc_10020802"
        },
        QuestDesc_10020803 = {
          ContentDE = "Der Schatten nagt unerbittlich an Psyches Verstand, aber deine Stimme ruft sie zurück.\n Als sich ihre brandneuen Flügel entfalten, kehrt eine stille Entschlossenheit in ihr Herz ein.",
          TextMapId = "QuestDesc_10020803"
        },
        QuestDesc_10020804 = {
          ContentDE = "Psyches Geschichte endet mit einer einzigen Kugel aus der Waffe der Eskorte.\n Rhythm, der Stabsfeldwebel, hat dich für Opfer gehalten, die von dem Filthoid angegriffen wurden, und schaut dich jetzt besorgt an.",
          TextMapId = "QuestDesc_10020804"
        },
        QuestDesc_10020805 = {
          ContentDE = "Der Tradition der Charon folgend, legst du Psyche im Wasser zur Ruhe und lässt ihre Seele zum Nebelmeer zurückkehren.",
          TextMapId = "QuestDesc_10020805"
        },
        QuestDesc_10020806 = {
          ContentDE = "Zusammen mit Outsider findest du einen abgelegenen Ort in der Nähe von Klagendem See, um Psyche ein letztes Lebewohl zu sagen.\n Du bist dir sicher, dass sie diesen Ort geliebt hätte – einen ruhigen, schönen Ruheplatz, fernab von traurigen Schreien oder dem Lärm von Maschinen.",
          TextMapId = "QuestDesc_10020806"
        },
        QuestDesc_10020807 = {
          ContentDE = "Nur die sanfte Brise zollt ihr stillen Tribut. Der Schlaf will dir nicht kommen, also machst du dich auf zu einem Spaziergang in die Tauenden Höhlen.\n Hier hast du einst fruchtbaren Boden für sie gesammelt, und es ist einer der wenigen Orte außerhalb der Stadtmauern, der vor Wind und Schnee geschützt ist.",
          TextMapId = "QuestDesc_10020807"
        },
        QuestDesc_10020808 = {
          ContentDE = "Eine einsame Gestalt steht in den Tauenden Höhlen – eine Frau, die du nicht kennst.\n Als sich eure Blicke treffen, scheint sie etwas sagen zu wollen.",
          TextMapId = "QuestDesc_10020808"
        },
        QuestDesc_10020809 = {
          ContentDE = "Hier, in dem schmalen Raum zwischen Realität und Traumwelt, öffnen Passanten ihre Augen, und Echos aus lärmenden Wüsten finden ihren Weg zurück.",
          TextMapId = "QuestDesc_10020809"
        },
        QuestDesc_10029701 = {
          ContentDE = "Erhöhe deine Prüfungsstufe, um den Hauptauftrag fortzusetzen.\n \n So kannst du EP verdienen:\n 1. Das Abschließen von <H>Missionen</> (ausgenommen Missionen im Handbuch des Nachtfahrers)\n 2. Die Interaktion mit Einheimischen und das Abschließen von <H>Nebenaufträgen</>",
          TextMapId = "QuestDesc_10029701"
        },
        QuestDesc_10029801 = {
          ContentDE = "Erhöhe deine Prüfungsstufe, um den Hauptauftrag fortzusetzen.\n \n So kannst du EP verdienen:\n 1. Das Abschließen von <H>Missionen</> (ausgenommen „Handbuch des Nachtfahrers“-Missionen)\n 2. Die Interaktion mit Einheimischen und das Abschließen von <H>Nebenaufträgen</>",
          TextMapId = "QuestDesc_10029801"
        },
        QuestDesc_10029901 = {
          ContentDE = "Erhöhe deine Prüfungsstufe, um den Hauptauftrag fortzusetzen.\n \n So kannst du EP verdienen:\n 1. Das Abschließen des <H>Dämonenkeil-Tutorials 101 bei der Luno-Schmiedin</>\n 2. Das Abschließen der <H>Missionen</> (ausgenommen „Handbuch des Nachtfahrers“-Missionen)\n 3. Die Interaktion mit Einheimischen und das Abschließen von <H>Nebenaufträgen</>",
          TextMapId = "QuestDesc_10029901"
        },
        QuestDesc_10030101 = {
          ContentDE = "Nach Tagen der Orientierungslosigkeit in vollkommener Dunkelheit beginnt dein Bewusstsein endlich wieder aufzutauchen.",
          TextMapId = "QuestDesc_10030101"
        },
        QuestDesc_10030102 = {
          ContentDE = "Du erwachst in der Raststätte, nachdem du fünf Tage lang bewusstlos warst. Das erste Gesicht, das du siehst, ist Camillas. Sprich mit ihr – vielleicht kann sie dir erzählen, was während deiner Bewusstlosigkeit geschehen ist.",
          TextMapId = "QuestDesc_10030102"
        },
        QuestDesc_10030103 = {
          ContentDE = "Camilla sagt dir, dass du als Einzige den Angriff vor fünf Tagen überlebt hast. Was die Details angeht, bleibt sie jedoch verschlossen. Stattdessen schlägt sie vor, zur Asphodel zu gehen, um die Wahrheit von deinen besorgten Freunden zu erfahren.",
          TextMapId = "QuestDesc_10030103"
        },
        QuestDesc_10030104 = {
          ContentDE = "Die Straßen von Icelake sind mit festlichen Dekorationen geschmückt, wirken jedoch seltsam still. Ein paar nervöse Passanten eilen vorbei – die unruhige Stille in der Luft ist unverkennbar. Wenn du die Wahrheit erfahren willst, solltest du zur Asphodel gehen und mit deinen Freunden sprechen.",
          TextMapId = "QuestDesc_10030104"
        },
        QuestDesc_10030105 = {
          ContentDE = "Auch Rhythm untersucht die Jagd auf Charon. Nach reiflicher Überlegung beschließt du, ihr zu folgen – vielleicht ist dies deine Chance, Frieden in Icelake zu sichern und etwas über Berenica aus der Legion zu erfahren.",
          TextMapId = "QuestDesc_10030105"
        },
        QuestDesc_10030106 = {
          ContentDE = "Du und Rhythm vereinbaren, bei der Jagd auf Charon zusammenzuarbeiten. Erster Schritt: den Tatort absuchen und Hinweise sammeln, die auf den Aufenthaltsort des Täters schließen lassen.",
          TextMapId = "QuestDesc_10030106"
        },
        QuestDesc_10030107 = {
          ContentDE = "Die Hinweise am Tatort deuten auf eine Verbindung zum Theater oder zur Fabrik hin. Als Leitung der Nachtfahrer führst du dein Team zum Galea-Theater, während Rhythm allein die Fabrik untersucht.",
          TextMapId = "QuestDesc_10030107"
        },
        QuestDesc_10030108 = {
          ContentDE = "Eine ältere Frau winkt dich aus der Ferne – vermutlich die Theaterleiterin. Sprich mit ihr und versuche, einige Hinweise zu dem Fall zu erhalten.",
          TextMapId = "QuestDesc_10030108"
        },
        QuestDesc_10030109 = {
          ContentDE = "Frau Putsch scheint mehr mit den Proben für das Silberkerzen-Karneval beschäftigt zu sein als mit dem laufenden Fall. Nach einem kurzen Gespräch kehrt sie zu ihrer Arbeit zurück – aber zumindest hindert sie dich nicht daran, dich umzusehen.\n Die Requisitenmeisterin, die für alle Materiallieferungen zuständig ist, könnte nützlichere Informationen haben.",
          TextMapId = "QuestDesc_10030109"
        },
        QuestDesc_10030110 = {
          ContentDE = "Laut dem Requisitenbuch hat die Truppe den ganzen Monat über ununterbrochen geprobt – kaum verdächtig. Also richtest du deine Aufmerksamkeit auf die elegante Frau auf der Bühne und den nervösen jungen Mann an ihrer Seite. Sein zittriges Verhalten weckt Ihren Verdacht – könnte er etwas mit dem Fall zu tun haben?",
          TextMapId = "QuestDesc_10030110"
        },
        QuestDesc_10030111 = {
          ContentDE = "Die Truppe scheint weder ein Motiv noch eine Gelegenheit für das Verbrechen gehabt zu haben. Da es hier keine hilfreichen Hinweise gibt, ist es der Zeit, sich mit Rhythm zu treffen und zu erfahren, ob sie in der Fabrik etwas herausfinden konnte.",
          TextMapId = "QuestDesc_10030111"
        },
        QuestDesc_10030112 = {
          ContentDE = "Rhythm erzählt dir von einem kürzlichen Diebstahl von Phoxichor in der Fabrik – der echte Vorrat wurde durch Fischöl ersetzt. Das würde die starken Phoxichor-Flecken auf dem Täter erklären. Du verdächtigst nun die Fischer der Icelake-Fischerei. Begib dich nach Mist Aken und spüre sie auf.",
          TextMapId = "QuestDesc_10030112"
        },
        QuestDesc_10030113 = {
          ContentDE = "Du nimmst das Fischöl von Rhythm – und die Katze wird sofort munter, schnurrt und wedelt mit dem Schweif, als wolle sie dich irgendwohin führen. Offenbar möchte sie, dass du ihr folgst. Warum also nicht sehen, wohin?",
          TextMapId = "QuestDesc_10030113"
        },
        QuestDesc_10030114 = {
          ContentDE = "Die Katze führt dich direkt zu einem sichtlich erschütterten Fischer. Noch bevor du ein Wort sagen kannst, fällt er auf die Knie, weinend und flehend um ein Geständnis. Irgendetwas stimmt hier nicht – es ist Zeit, genauer nachzuforschen.",
          TextMapId = "QuestDesc_10030114"
        },
        QuestDesc_10030201 = {
          ContentDE = "Du bist in der Kanalisation in der Nähe der Fabrik angekommen. Wohin jetzt? Am besten Rhythm fragen – sie hat vielleicht eine Idee.",
          TextMapId = "QuestDesc_10030201"
        },
        QuestDesc_10030202 = {
          ContentDE = "Ein paar Schritte in die Kanäle hinein hört Outsider plötzlich seltsame Geräusche vor sich. Geh am besten vorsichtig weiter.",
          TextMapId = "QuestDesc_10030202"
        },
        QuestDesc_10030203 = {
          ContentDE = "Hilferufe hallen durch den Tunnel. Bevor du reagieren kannst, stürmt Rhythm auf das Geräusch zu. Bleib nah bei ihr und folge ihr.",
          TextMapId = "QuestDesc_10030203"
        },
        QuestDesc_10030204 = {
          ContentDE = "Du hast den ersten eingeschlossenen Zivilisten gerettet und das versiegelte Tor geöffnet. Weiter vorwärts – es gibt noch jemanden, der Hilfe braucht.",
          TextMapId = "QuestDesc_10030204"
        },
        QuestDesc_10030205 = {
          ContentDE = "Der Zivilist sagt, sein Begleiter sei gleich voraus. Beeile dich.",
          TextMapId = "QuestDesc_10030205"
        },
        QuestDesc_10030206 = {
          ContentDE = "Du hörst den zweiten Zivilisten ganz in der Nähe rufen. Beeile dich und sieh nach ihm.",
          TextMapId = "QuestDesc_10030206"
        },
        QuestDesc_10030207 = {
          ContentDE = "Beide Zivilisten sind in Sicherheit. Sprich mit Rhythm – schau, wie es ihr nach der Rettung geht.",
          TextMapId = "QuestDesc_10030207"
        },
        QuestDesc_10030208 = {
          ContentDE = "Nachdem das Abwasser abgelaufen ist, kannst du das Knurren des Täters durch die Dunkelheit hallen hören. Bleib wachsam und geh weiter.",
          TextMapId = "QuestDesc_10030208"
        },
        QuestDesc_10030210 = {
          ContentDE = "Niemand hätte erwartet, dass bei der Jagd auf Charon nicht nur ein Angreifer, sondern gleich zwei auftauchen würden. Rhythm wurde schwer verletzt, als sie dich vor dem zweiten Angreifer schützte. Da Verstärkung eintrifft, wird die Legion von hier aus übernehmen. Nach kurzer Diskussion beschließen die Nachtfahrer, sie im medizinischen Zentrum zu besuchen – teilweise wegen der Belohnung, vor allem aber, um ihr dafür zu danken, dass sie dir das Leben gerettet hat.",
          TextMapId = "QuestDesc_10030210"
        },
        QuestDesc_10030211 = {
          ContentDE = "Niemand hätte erwartet, dass bei der Jagd auf Charon nicht nur ein Angreifer, sondern gleich zwei auftauchen würden. Rhythm wurde schwer verletzt, als sie dich vor dem zweiten Angreifer schützte. Da Verstärkung eintrifft, wird die Legion von hier aus übernehmen. Nach kurzer Diskussion beschließen die Nachtfahrer, sie im medizinischen Zentrum zu besuchen – teilweise wegen der Belohnung, vor allem aber, um ihr dafür zu danken, dass sie dir das Leben gerettet hat.",
          TextMapId = "QuestDesc_10030211"
        },
        QuestDesc_10030212 = {
          ContentDE = "Die Legion versprach eine Eskorte – doch hier ist niemand. Stattdessen sind die Wände voller Einschusslöcher: Spuren eines heftigen Gefechts. Es scheint, als seien die hier stationierten Soldaten dem Täter begegnet. Da du sowieso aufbrechen willst, folgst du am besten den Spuren und schaust, wohin sie führen.",
          TextMapId = "QuestDesc_10030212"
        },
        QuestDesc_10030213 = {
          ContentDE = "Du findest einen Tunnel, den der Täter wahrscheinlich bei seiner Flucht benutzt hat. Er führt bis zum äußeren Ausgang der Kanäle. Geh vorsichtig weiter.",
          TextMapId = "QuestDesc_10030213"
        },
        QuestDesc_10030214 = {
          ContentDE = "Am Ende der Kanäle herrscht eine bedrückende, unheimliche Stille. Hier ist eindeutig etwas passiert. Bleib aufmerksam.",
          TextMapId = "QuestDesc_10030214"
        },
        QuestDesc_10030215 = {
          ContentDE = "Der Ausgang ist ein Bild des Grauens. Giftspuren – keine Standardausrüstung der imperialen Streitkräfte – deuten auf etwas weitaus Dunkleres hinter der Jagd auf Charon hin. Nach kurzer Diskussion bleibt Outsider zurück, um der Legion Bericht zu erstatten. Du und Snow haltet euch an den Plan und besucht Rhythm im Krankenhaus.",
          TextMapId = "QuestDesc_10030215"
        },
        QuestDesc_10030216 = {
          ContentDE = "Einige Tage später erwacht Rhythm endlich aus ihrem Koma. Nachdem du sie über alles auf den neuesten Stand gebracht hast, dankt sie dir – und bittet dich als Zeichen ihrer Wertschätzung, ein silbernes Siegel aus ihrem geheimen Basispunkt zu holen. Noch ans Bett gefesselt, will sie persönliche Briefe schreiben, um Verbündete zu erreichen und mehr Informationen über Berenica zu sammeln.",
          TextMapId = "QuestDesc_10030216"
        },
        QuestDesc_10030217 = {
          ContentDE = "Einige Tage später erwacht Rhythm endlich aus ihrem Koma. Nachdem du sie über alles auf den neuesten Stand gebracht hast, dankt sie dir – und bittet dich als Zeichen ihrer Wertschätzung, ein silbernes Siegel aus ihrem geheimen Basispunkt zu holen. Noch ans Bett gefesselt, will sie persönliche Briefe schreiben, um Verbündete zu erreichen und mehr Informationen über Berenica zu sammeln.",
          TextMapId = "QuestDesc_10030217"
        },
        QuestDesc_10030218 = {
          ContentDE = "Du bist an Rhythms geheimem Basispunkt angekommen. Durchsuche den Ort – das silberne Siegel mit ihrem Namen sollte hier irgendwo sein.",
          TextMapId = "QuestDesc_10030218"
        },
        QuestDesc_10030219 = {
          ContentDE = "Du bist an Rhythms geheimem Basispunkt angekommen. Durchsuche den Ort – das silberne Siegel mit ihrem Namen sollte hier irgendwo sein.",
          TextMapId = "QuestDesc_10030219"
        },
        QuestDesc_100302sp101 = {
          ContentDE = "Zwei Zivilisten wurden von einem Monster in der Kanalisation gefangen genommen – wahrscheinlich handelt es sich um den Täter aus der Jagd auf Charon. Du bist definitiv auf der richtigen Spur. Die Kreatur ist vorerst verschwunden, also konzentriere dich darauf, das Tor zu öffnen und die Zivilisten in Sicherheit zu bringen.",
          TextMapId = "QuestDesc_100302sp101"
        },
        QuestDesc_100302sp102 = {
          ContentDE = "Um die Steuerkonsole wieder zu aktivieren, musst du die verstopften Rohre in diesem Bereich reinigen. Sobald das Abwassersystem aktiviert wird, schwärmen jedoch Filthoiden herein. Halte sie auf und beschütze den Zivilisten!",
          TextMapId = "QuestDesc_100302sp102"
        },
        QuestDesc_100302sp103 = {
          ContentDE = "Alle verstopften Rohre wurden gereinigt. Versuche erneut, das Tor zu öffnen.",
          TextMapId = "QuestDesc_100302sp103"
        },
        QuestDesc_100302sp104 = {
          ContentDE = "Um die Steuerkonsole wieder zu aktivieren, musst du die verstopften Rohre in diesem Bereich reinigen. Sobald das Abwassersystem aktiviert wird, schwärmen jedoch Filthoiden herein. Halte sie auf und beschütze den Zivilisten!",
          TextMapId = "QuestDesc_100302sp104"
        },
        QuestDesc_100302sp201 = {
          ContentDE = "Der zweite Zivilist ist hinter den Abwehrmechanismen der Kanalisation eingeschlossen. Bediene die Steuerkonsole, um die Sicherheitsvorrichtungen zu deaktivieren und ihn zu retten.",
          TextMapId = "QuestDesc_100302sp201"
        },
        QuestDesc_100302sp202 = {
          ContentDE = "Dasselbe Problem wie zuvor – die Steuerkonsole ist hinter verstopften Rohren versiegelt. Öffne die Ventile, beseitige die Blockade und bring das System wieder in Betrieb.",
          TextMapId = "QuestDesc_100302sp202"
        },
        QuestDesc_100302sp203 = {
          ContentDE = "Der zweite Zivilist ist hinter den Abwehrmechanismen der Kanalisation eingeschlossen. Bediene die Steuerkonsole, um die Sicherheitsvorrichtungen zu deaktivieren und ihn zu retten.",
          TextMapId = "QuestDesc_100302sp203"
        },
        QuestDesc_100302sp301 = {
          ContentDE = "Der Täter der Jagd auf Charon bricht mit einem wilden Gebrüll hervor. Stell dich ihm direkt – es ist Zeit, das zu beenden.",
          TextMapId = "QuestDesc_100302sp301"
        },
        QuestDesc_10030301 = {
          ContentDE = "Zurück in Rhythms geheimem Basispunkt findest du das silberne Siegel – zusammen mit ein paar Andenken aus ihrer Vergangenheit. Während du sie durchsuchst, wird dir etwas klar: Vielleicht war die Distanz zwischen euch nie so groß, wie sie schien. Bring ihr das Siegel und hör dir an, was sie zu sagen hat.",
          TextMapId = "QuestDesc_10030301"
        },
        QuestDesc_10030302 = {
          ContentDE = "Um unnötigen Ärger zu vermeiden, ist es am besten, vorerst mit der 13. Legion in Icelake zusammenarbeiten.",
          TextMapId = "QuestDesc_10030302"
        },
        QuestDesc_10030303 = {
          ContentDE = "Die Jagd auf Charon ist in eine neue Phase getreten. Auf Befehl von Clive begibst du dich in die Kanalisation unter dem Silberfrieden-Platz. Nimm dort erneut Kontakt auf und warte auf weitere Anweisungen.",
          TextMapId = "QuestDesc_10030303"
        },
        QuestDesc_10030304 = {
          ContentDE = "Nachdem du Rhythm über Berry informiert hast, platzt Kommandantin Lynn aus der 13. Legion ins Krankenzimmer. Sie erklärt ohne Umschweife, dass ihre Einheit die Jagd auf Charon übernimmt. Zum Glück scheint sie nichts von deiner Verbindung zu Sibylle zu wissen – und bietet dir sogar ihre Zusammenarbeit an. Jetzt ist nicht der Moment, Misstrauen zu wecken. Spiele vorerst mit und gib dich kooperativ.",
          TextMapId = "QuestDesc_10030304"
        },
        QuestDesc_100303sp101 = {
          ContentDE = "Du hast zugestimmt, bei den Ermittlungen zur Jagd auf Charon zu helfen. Ohne Zeit zu verlieren, weist Lynn dir deine erste Aufgabe zu: Triff Clive aus der 13. Legion außerhalb von Icelake und hilf dabei, die ankommenden Vorräte zu verarbeiten.",
          TextMapId = "QuestDesc_100303sp101"
        },
        QuestDesc_100303sp102 = {
          ContentDE = "Nach mehreren Tagen hast du die Aufgaben der 13. Legion endlich abgeschlossen. Aber Rhythm taucht nicht am vereinbarten Treffpunkt auf. Ist ihr vielleicht etwas zugestoßen? Durchsuche die Gegend und vergewissere dich, dass sie sicher ist.",
          TextMapId = "QuestDesc_100303sp102"
        },
        QuestDesc_100303sp103 = {
          ContentDE = "Um den Bewohnern zu helfen, deren Alltag durch die 13. Legion gestört wurde, sammelt Rhythm wichtige Vorräte. Als ihre Verbündeten bietet ihr eure Hilfe an.",
          TextMapId = "QuestDesc_100303sp103"
        },
        QuestDesc_100303sp104 = {
          ContentDE = "Angeln abgeschlossen. Du hast alles, was die Stadtbewohner brauchen – es ist Zeit, die Vorräte abzuliefern.",
          TextMapId = "QuestDesc_100303sp104"
        },
        QuestDesc_100303sp105 = {
          ContentDE = "Kaum hast du Margie die Vorräte übergeben, trifft schon ein neuer Auftrag von Clive ein. Anscheinend ist die 13. Legion unterwegs – mach dich auf den Weg und melde dich.",
          TextMapId = "QuestDesc_100303sp105"
        },
        QuestDesc_100303sp201 = {
          ContentDE = "Soldaten der 13. Legion sind in der Kanalisation stationiert und patrouillieren jeweils ihre Sektoren. Die Tunnel sind von Spannung erfüllt. Geh zu dem Bereich, den Clive die Nachtfahrer zugeteilt hat.",
          TextMapId = "QuestDesc_100303sp201"
        },
        QuestDesc_100303sp202 = {
          ContentDE = "Soldaten der 13. Legion sind in der Kanalisation stationiert und patrouillieren jeweils ihre Sektoren. Die Tunnel sind von Spannung erfüllt. Geh zu dem Bereich, den Clive die Nachtfahrer zugeteilt hat.",
          TextMapId = "QuestDesc_100303sp202"
        },
        QuestDesc_100303sp203 = {
          ContentDE = "Der Bereich, den Clive dir zugewiesen hat, ist derzeit unzugänglich – wie immer: Die Steuerkonsole ist vom Abwasser abgeschottet. Lass es ab, um die Sperre aufzuheben und zu deinem Sektor vorzurücken.",
          TextMapId = "QuestDesc_100303sp203"
        },
        QuestDesc_100303sp204 = {
          ContentDE = "Nach einigen Verzögerungen erhältst du endlich Zugang zu dem Bereich, den Clive zugewiesen hat. Beeile dich.",
          TextMapId = "QuestDesc_100303sp204"
        },
        QuestDesc_100303sp205 = {
          ContentDE = "Du versuchst, nach der Erkundung des Gebiets an Clive zu berichten – doch Rhythms Funkterminal versagt und die Nachricht bricht ab. Sieh nach, ob du es reparieren kannst. Versuche, es zu reparieren.",
          TextMapId = "QuestDesc_100303sp205"
        },
        QuestDesc_100303sp206 = {
          ContentDE = "Kaum ist das Funkterminal wieder online, erfährst du, dass der Täter die Blockade der Legion durchbrochen hat und direkt auf dich zukommt. Zum Glück trifft Lynn rechtzeitig mit Verstärkung ein. Jetzt – bring es zu Ende!",
          TextMapId = "QuestDesc_100303sp206"
        },
        QuestDesc_10030401 = {
          ContentDE = "Obwohl die Legion den Fall als gelöst erklärt und im Triumph in die Hauptstadt zurückgekehrt ist, wissen du und Rhythm die Wahrheit: Es ist bei weitem noch nicht vorbei.",
          TextMapId = "QuestDesc_10030401"
        },
        QuestDesc_10030402 = {
          ContentDE = "Die bisherigen Hinweise deuten darauf hin, dass der Täter eine Verbindung zur Oper hatte. Die unheimliche Melodie, die er summte, könnte aus einer Arie stammen – und wenn du sie identifizieren könntest, würde das den Kreis der Verdächtigen eingrenzen. Rhythms jüngerer Bruder Blues ist ein großer Opernfan. In ihrem geheimen Basispunkt hat er eine Sammlung von Kassetten hinterlassen. Es ist zwar unwahrscheinlich, aber einen Versuch wert.",
          TextMapId = "QuestDesc_10030402"
        },
        QuestDesc_10030403 = {
          ContentDE = "Jetzt beginnt der schwierige Teil. Teste dein Gedächtnis und deine Ohren – eine Kassette nach der anderen.",
          TextMapId = "QuestDesc_10030403"
        },
        QuestDesc_10030404 = {
          ContentDE = "Stunden vergehen, während du die Aufnahmen durchgehst. Rhythm ist kurz rausgegangen, um frische Luft zu schnappen. Die Suche ist langsam, mühsam – und anstrengend. Mach jetzt erst einmal eine Pause. Schau nach, wie es ihr geht.",
          TextMapId = "QuestDesc_10030404"
        },
        QuestDesc_10030501 = {
          ContentDE = "Es gab nie Ehre darin, ein Lorbeerkranz-Charon zu werden – der Titel war nur Köder. Was in der Innenstadt wirklich auf dich wartete, war der kalte Operationstisch der Alchemie-Akademie. Jetzt, als Monster, kannst du nur noch gehorchen.",
          TextMapId = "QuestDesc_10030501"
        },
        QuestDesc_10030502 = {
          ContentDE = "Nicht mehr menschlich. Keine Gedanken. Kein Wille. Nur die Aufgabe zählt: Eliminiere die Gegner.",
          TextMapId = "QuestDesc_10030502"
        },
        QuestDesc_10030503 = {
          ContentDE = "Nicht mehr menschlich – ohne Gedanken, ohne Wahl. Begib dich zum Testgelände. Eliminiere die Gegner.",
          TextMapId = "QuestDesc_10030503"
        },
        QuestDesc_10030504 = {
          ContentDE = "Nicht mehr menschlich – ohne Gedanken, ohne Wahl. Begib dich zum Testgelände. Eliminiere die Gegner.",
          TextMapId = "QuestDesc_10030504"
        },
        QuestDesc_10030505 = {
          ContentDE = "Nicht mehr menschlich – ohne Gedanken, ohne Wahl. Begib dich zum Testgelände. Eliminiere die Gegner.",
          TextMapId = "QuestDesc_10030505"
        },
        QuestDesc_10030506 = {
          ContentDE = "Der naive Narr hat es tatsächlich geschafft ... Es gibt kein Zurück mehr. Raus hier – und tu es als Mensch.",
          TextMapId = "QuestDesc_10030506"
        },
        QuestDesc_10030507 = {
          ContentDE = "Der naive Narr hat es tatsächlich geschafft ... Es gibt kein Zurück mehr. Raus hier – und tu es als Mensch.",
          TextMapId = "QuestDesc_10030507"
        },
        QuestDesc_10030508 = {
          ContentDE = "Der naive Narr hat es tatsächlich geschafft ... Es gibt kein Zurück mehr. Raus hier – und tu es als Mensch.",
          TextMapId = "QuestDesc_10030508"
        },
        QuestDesc_10030601 = {
          ContentDE = "Der Titel „Lorbeerkranz-Charon“ ist nichts als eine grausame Täuschung. Du kannst Rhythm nicht einem Traum hinterherjagen lassen, der auf Lügen beruht. Sag ihr die Wahrheit über die Alchemie-Akademie ... und tue, was getan werden muss.",
          TextMapId = "QuestDesc_10030601"
        },
        QuestDesc_10030602 = {
          ContentDE = "Im Galea-Theater ist der Silberkerzen-Karneval in vollem Gange. Beim Silberkerzen-Karneval herrscht ausgelassene Maskenpracht – ein perfektes Versteck für ein Monster wie dich. Schlüpfe durch die Feierlichkeiten und finde deinen Kontakt.",
          TextMapId = "QuestDesc_10030602"
        },
        QuestDesc_10030603 = {
          ContentDE = "Seit dem Aufbruch der 13. Legion sind schon einige Tage vergangen. Rhythm scheint sich – wenn auch nur langsam – von dem Verlust von Blues zu erholen. Vielleicht hat sie noch mehr zu sagen. Geh und höre ihr zu.",
          TextMapId = "QuestDesc_10030603"
        },
        QuestDesc_10030604 = {
          ContentDE = "Die Jagd auf Charon ist vorbei. Der Einfluss der Verlassenen in der Region Cocytus wurde zerschlagen. Doch dies ist kein Ende – nur die stille Pause vor dem nächsten Sturm.",
          TextMapId = "QuestDesc_10030604"
        },
        QuestDesc_1003plus01 = {
          ContentDE = "Zwischen nachhallendem Schmerz und schweren Abschieden geht dieser lange Tag schließlich zu Ende.\n Heute Nacht bleibt dir der Schlaf fern – vielleicht hilft dir ein stiller Spaziergang durch die Stadt, deine Gedanken zu ordnen.",
          TextMapId = "QuestDesc_1003plus01"
        },
        QuestDesc_1003plus02 = {
          ContentDE = "Von Outsider und Snow erfährst du, dass du in die Jagd auf Charon verwickelt warst – eine Reihe von Morden, die sich vor fünf Tagen ereignet haben. Bevor du das alles begreifen kannst, erscheint Rhythm ohne Vorwarnung und beendet das Gespräch abrupt. Du kannst ihr jetzt nicht mehr ausweichen – hör dir lieber an, was sie zu sagen hat.",
          TextMapId = "QuestDesc_1003plus02"
        },
        QuestDesc_1003plus03 = {
          ContentDE = "Du hast mehrere vielversprechende Hinweise gesammelt – alle stehen möglicherweise in Verbindung mit der Jagd auf Charon. Wenn die Spur ins Leere führt, versuche, Hinweise miteinander zu kombinieren. Vielleicht ergibt sich daraus eine neue Spur.",
          TextMapId = "QuestDesc_1003plus03"
        },
        QuestDesc_1003plus04 = {
          ContentDE = "Du und Rhythm vereinbaren, bei der Jagd auf Charon zusammenzuarbeiten. Erster Schritt: den Tatort absuchen und Hinweise sammeln, die auf den Aufenthaltsort des Täters schließen lassen.",
          TextMapId = "QuestDesc_1003plus04"
        },
        QuestDesc_1003plus05 = {
          ContentDE = "Eine Reihe übergroßer Plakate am Eingang des Theaters springt dir sofort ins Auge. Vielleicht verraten sie etwas über die jüngsten Ereignisse – ein Blick lohnt sich.",
          TextMapId = "QuestDesc_1003plus05"
        },
        QuestDesc_1003plus06 = {
          ContentDE = "Die Requisitenmeisterin bestreitet entschieden, dass der am Tatort gefundene Vorhang aus dem Galea-Theater stammt. Sie behauptet, alles werde sorgfältig dokumentiert – und eine von mehreren Mitarbeitern unterzeichnete Liste bestätigt das. Sieh lieber selbst nach.",
          TextMapId = "QuestDesc_1003plus06"
        },
        QuestDesc_1003plus07 = {
          ContentDE = "Ein müde aussehender Schauspieler erklärt, dass die Truppe ununterbrochen für den bevorstehenden Silberkerzen-Karneval geprobt hat. Eine nahegelegene Anwesenheitsliste verzeichnet die Probenzeiten aller Beteiligten – sieh sie dir an.",
          TextMapId = "QuestDesc_1003plus07"
        },
        QuestDesc_1003plus08 = {
          ContentDE = "Während du die Anwesenheitsliste durchgehst, hörst du ein Geräusch von oben. Sieh nach.",
          TextMapId = "QuestDesc_1003plus08"
        },
        QuestDesc_1003plus09 = {
          ContentDE = "Du bist in den Unterkünften der Fischer angekommen. Zeit für eine gründliche Suche – Tür für Tür.",
          TextMapId = "QuestDesc_1003plus09"
        },
        QuestDesc_1003plus10 = {
          ContentDE = "Niemand antwortet – aber hinter dir taucht eine Katze auf, die eindringlich miaut, als hätte sie eine Spur aufgenommen. Es könnte sich lohnen, ihr zu folgen.",
          TextMapId = "QuestDesc_1003plus10"
        },
        QuestDesc_1003plus11 = {
          ContentDE = "Du hast den Phoxichor-Dieb gefasst – doch er ist nicht der Mörder. Dennoch gibt er dir einen Hinweis: Der Täter könnte sich in der Kanalisation verstecken. Übergib ihn dem Sicherheitsbüro und triff dich dann wieder mit Rhythm, um euren nächsten Schritt zu besprechen.",
          TextMapId = "QuestDesc_1003plus11"
        },
        QuestDesc_1003plus12 = {
          ContentDE = "Nachdem der Fischer übergeben wurde, triffst du Rhythm in der Kanalisation, um den wahren Täter aufzuspüren. Erst wenn sein Aufenthaltsort bestätigt ist, kann sie Unterstützung von der 6. Legion anfordern – und die Jagd auf Charon beenden.",
          TextMapId = "QuestDesc_1003plus12"
        },
        QuestDesc_1003plus13 = {
          ContentDE = "Du hast die Zivilisten in Sicherheit gebracht – doch kaum weicht die Anspannung, ertönt ein monströses Brüllen aus der Tiefe. Es klingt wie die Kreatur, vor der du gewarnt wurdest. Lass das Abwasser ab und setze die Verfolgung fort.",
          TextMapId = "QuestDesc_1003plus13"
        },
        QuestDesc_1003plus14 = {
          ContentDE = "Ein paar Tage später wacht Rhythm endlich auf. Bring sie auf den neuesten Stand, was passiert ist, während sie bewusstlos war.",
          TextMapId = "QuestDesc_1003plus14"
        },
        QuestDesc_1003plus15 = {
          ContentDE = "Du bist an Rhythms geheimem Basispunkt angekommen. Durchsuche den Ort – das silberne Siegel mit ihrem Namen sollte hier irgendwo sein.",
          TextMapId = "QuestDesc_1003plus15"
        },
        QuestDesc_1003plus16 = {
          ContentDE = "Du bist an Rhythms geheimem Basispunkt angekommen. Durchsuche den Ort – das silberne Siegel mit ihrem Namen sollte hier irgendwo sein.",
          TextMapId = "QuestDesc_1003plus16"
        },
        QuestDesc_1003plus17 = {
          ContentDE = "Soldaten der 13. Legion sind in der Kanalisation stationiert und patrouillieren jeweils ihre Sektoren. Die Tunnel sind von Spannung erfüllt. Geh zu dem Bereich, den Clive die Nachtfahrer zugeteilt hat.",
          TextMapId = "QuestDesc_1003plus17"
        },
        QuestDesc_1003plus18 = {
          ContentDE = "Du hast den Sektor erreicht, den Clive deinem Team zugewiesen hat. Sieh dich gründlich um und prüfe die Umgebung.",
          TextMapId = "QuestDesc_1003plus18"
        },
        QuestDesc_1003plus19 = {
          ContentDE = "Gehe die gesammelten Hinweise erneut durch – einer davon könnte auf die Identität des Mörders hindeuten. Mit einem frischen Blick wird sich dir vielleicht das fehlende Puzzleteil offenbaren.",
          TextMapId = "QuestDesc_1003plus19"
        },
        QuestDesc_1003plus20 = {
          ContentDE = "Rhythm summt eine Melodie – unheimlich ähnlich jener, die der Mörder in jener Nacht sang. Sie stammt aus „Kinder aus dem Schneefeld“, einer bekannten Oper. Ihr habt gerade darüber gesprochen, wie ihr diesen Hinweis nutzen könnt, um den Täter anzulocken ... doch offenbar hat er euch zuerst gefunden.",
          TextMapId = "QuestDesc_1003plus20"
        },
        QuestDesc_1003plus20_1 = {
          ContentDE = "Rhythm summt eine Melodie – unheimlich ähnlich jener, die der Mörder in jener Nacht sang. Sie stammt aus „Kinder aus dem Schneefeld“, einer bekannten Oper. Ihr habt gerade darüber gesprochen, wie ihr diesen Hinweis nutzen könnt, um den Täter anzulocken ... doch offenbar hat er euch zuerst gefunden.",
          TextMapId = "QuestDesc_1003plus20_1"
        },
        QuestDesc_1003plus21 = {
          ContentDE = "Im Galea-Theater ist der Silberkerzen-Karneval in vollem Gange. Beim Silberkerzen-Karneval herrscht ausgelassene Maskenpracht – ein perfektes Versteck für ein Monster wie dich. Schlüpfe durch die Feierlichkeiten und finde deinen Kontakt.",
          TextMapId = "QuestDesc_1003plus21"
        },
        QuestDesc_1003plus22 = {
          ContentDE = "Dein Kontakt sollte ganz in der Nähe sein. Geh hin und nimm das Treffen wahr.",
          TextMapId = "QuestDesc_1003plus22"
        },
        QuestDesc_1003plus23 = {
          ContentDE = "Die Verlassenen sind eine weitere Bedrohung, die über dieser Stadt schwebt. Eliminiere sie.",
          TextMapId = "QuestDesc_1003plus23"
        },
        QuestDesc_1003plus24 = {
          ContentDE = "Gerade als die Schlacht zu Ende ist, stürmen Soldaten der 13. Legion herein. Wenn sie einen Kampf wollen, dann sollen sie ihn bekommen – keiner von ihnen wird hier lebend wegkommen.",
          TextMapId = "QuestDesc_1003plus24"
        },
        QuestDesc_1003plus25 = {
          ContentDE = "Du weißt nicht, wie Rhythm und die Phoxjäger dich aufgespürt haben – aber du hast keine Zeit, darüber nachzudenken. Die Legion ist noch hier, und der Kampf ist nicht vorbei.",
          TextMapId = "QuestDesc_1003plus25"
        },
        QuestDesc_1003plus26 = {
          ContentDE = "Deine Darbietung als Blues war makellos. Rhythm wird niemals erfahren, dass sie ihren eigenen Bruder getötet hat. Weder die 13. Legion noch die Verlassenen werden das Blutvergießen jemals mit ihr oder den Phoxjägern in Verbindung bringen.\n Doch der Vorhang für diese Rolle ist gefallen. Es ist Zeit, ein letztes Mal die Bühne zu betreten – diesmal als Parsifal.",
          TextMapId = "QuestDesc_1003plus26"
        },
        QuestDesc_1003plus27 = {
          ContentDE = "Lass den Vorhang sich heben – und mit ihm alles enden.",
          TextMapId = "QuestDesc_1003plus27"
        },
        QuestDesc_1003plus28 = {
          ContentDE = "Der Lärm beim Ablassen des Abwassers hat einen Schwarm Filthoiden angelockt. Vertreibe sie.",
          TextMapId = "QuestDesc_1003plus28"
        },
        QuestDesc_1003plus29 = {
          ContentDE = "Der Lärm beim Ablassen des Abwassers hat einen Schwarm Filthoiden angelockt. Vertreibe sie.",
          TextMapId = "QuestDesc_1003plus29"
        },
        QuestDesc_1003plus30 = {
          ContentDE = "Der Bereich, den Clive dir zugewiesen hat, ist derzeit unzugänglich – wie immer: Die Steuerkonsole ist vom Abwasser abgeschottet. Lass es ab, um die Sperre aufzuheben und zu deinem Sektor vorzurücken.",
          TextMapId = "QuestDesc_1003plus30"
        },
        QuestDesc_1003plus31 = {
          ContentDE = "Rhythm scheint Fragen zu dem Phoxichor zu haben, der im Schnee gefunden wurde. Sprich mit ihr und teile ihr deine Erkenntnisse mit – das könnte zu neuen Entdeckungen führen.",
          TextMapId = "QuestDesc_1003plus31"
        },
        QuestDesc_1003plus32 = {
          ContentDE = "Nach einer kurzen Suche findest du in der Nähe des Eingangsbereichs nichts Auffälliges. Geh weiter hinein und sprich mit dem Personal des Galea-Theaters.",
          TextMapId = "QuestDesc_1003plus32"
        },
        QuestDesc_1003plus33 = {
          ContentDE = "Den Hilferufen folgend findest du den zweiten Eingeschlossenen. Finde einen Weg, ihn zu befreien.",
          TextMapId = "QuestDesc_1003plus33"
        },
        QuestDesc_1003plus34 = {
          ContentDE = "Nach einem kurzen Austausch beschließt du, mit der 13. Legion zusammenzuarbeiten. Höre dir jetzt die Befehle von Kommandantin Lynn an.",
          TextMapId = "QuestDesc_1003plus34"
        },
        QuestDesc_1003plus35 = {
          ContentDE = "Als du Clive triffst, vertreibt er bereits Schneewölfe in der Nähe des Abgabepunkts. Hilf ihm, das Gebiet zu sichern, und warte gemeinsam auf das Lieferteam.",
          TextMapId = "QuestDesc_1003plus35"
        }
      }
    end
  },
