        RESOURCE_DESC_19004 = {
          ContentDE = "Hier sammelt sich der Seelenabdruck. Dies ist Zorn.",
          TextMapId = "RESOURCE_DESC_19004"
        },
        RESOURCE_DESC_19005 = {
          ContentDE = "Hier sammelt sich der Seelenabdruck. Dies ist Vertrauen.",
          TextMapId = "RESOURCE_DESC_19005"
        },
        RESOURCE_DESC_19006 = {
          ContentDE = "Hier sammelt sich der Seelenabdruck. Dies ist Gelassenheit.",
          TextMapId = "RESOURCE_DESC_19006"
        },
        RESOURCE_DESC_19007 = {
          ContentDE = "Hier sammelt sich der Seelenabdruck. Dies ist Verwirrung.",
          TextMapId = "RESOURCE_DESC_19007"
        },
        RESOURCE_DESC_19008 = {
          ContentDE = "Hier sammelt sich der Seelenabdruck. Dies ist Sehnsucht.",
          TextMapId = "RESOURCE_DESC_19008"
        },
        RESOURCE_DESC_200 = {
          ContentDE = "Eine Zierstatue zur Aufbewahrung von Crystallo, von außerordentlich hohem Wert.",
          TextMapId = "RESOURCE_DESC_200"
        },
        RESOURCE_DESC_20001 = {
          ContentDE = "Vom Filthoid abgestoßenes Hornmaterial – sein härtester Panzer. Mit spezieller Verarbeitung eignet es sich als Schutz für Waffen und Rüstungen.",
          TextMapId = "RESOURCE_DESC_20001"
        },
        RESOURCE_DESC_20002 = {
          ContentDE = "Eine zerbrochene Flasche von Sal Volatil, übersät mit tiefen Kratzern und Einschusslöchern. Der Inhalt ist restlos ausgelaufen, doch das Glas lässt sich noch recyceln.",
          TextMapId = "RESOURCE_DESC_20002"
        },
        RESOURCE_DESC_20003 = {
          ContentDE = "Reinigendes Wasser, mit dem Anhänger der Elysischen Kirche vor Zeremonien ihre Hände reinigen. Meist in gesegneten Gefäßen aufbewahrt und in Tempeln stets vorrätig.",
          TextMapId = "RESOURCE_DESC_20003"
        },
        RESOURCE_DESC_20004 = {
          ContentDE = "Erkennungsmarke, die hyperboreische Soldaten bei sich tragen, mit Name, Dienstgrad, Legion und Eintrittsdatum. Fällt ein Soldat auf dem Schlachtfeld, identifiziert die Legion ihn anhand dieser Marke und schickt sie als ehrendes Andenken in seine Heimat zurück.",
          TextMapId = "RESOURCE_DESC_20004"
        },
        RESOURCE_DESC_20005 = {
          ContentDE = "Natürliches Steinpulver, ein gängiges Verbrauchsmaterial in Alchemie und Bauwesen. Je nach Herkunft variiert die Färbung der Erze, weshalb es auch als Grundstoff für Malpigmente dient.",
          TextMapId = "RESOURCE_DESC_20005"
        },
        RESOURCE_DESC_20006 = {
          ContentDE = "Pergamentrolle, die Elysische Ritter bei sich tragen, beschrieben mit Segensgebeten der Elysischen Kirche. Im Feld schöpfen sie aus diesen Worten oft neue Kraft.",
          TextMapId = "RESOURCE_DESC_20006"
        },
        RESOURCE_DESC_20007 = {
          ContentDE = "Ein Signalkabel mit Hyperboreischem Kennzeichen, etwas grob eingesammelt.\n Vorsicht vor Stromschlägen, solange noch Funken sprühen.",
          TextMapId = "RESOURCE_DESC_20007"
        },
        RESOURCE_DESC_20008 = {
          ContentDE = "Fester Kristall, gewonnen aus einem seltenen Exemplar der Filthoiden. Wird meist zur Erforschung ihrer besonderen biologischen Struktur verwendet.",
          TextMapId = "RESOURCE_DESC_20008"
        },
        RESOURCE_DESC_20009 = {
          ContentDE = "Eine verbreitete Wildpflanze. Ihre Blüten sind meist gefüllt, leuchtend rot und von seidigem Glanz. Kälte- und dürrebeständig, äußerst anpassungsfähig, deshalb auf dem ganzen Kontinent zu finden.\n In den Mythen von Charon heißt es, dies seien die Tränen des Vaters Ask, die sich auf seiner Suche nach Mutter Embla aus Trauer um die verlorene Geliebte in Blüten verwandelten.",
          TextMapId = "RESOURCE_DESC_20009"
        },
        RESOURCE_DESC_2001 = {
          ContentDE = "Ein Beweis für deinen Weg durch Dornen und Sturm, das Echo deines Lachens und deiner Tränen, das Destillat deiner mühsam errungenen Erfahrung – erinnerst du dich? Du bist weder schwach noch allein.",
          TextMapId = "RESOURCE_DESC_2001"
        },
        RESOURCE_DESC_20010 = {
          ContentDE = "Eine rankende Pflanze, die häufig im Schatten wächst. Zäh und biegsam, mit ineinander verflochtenen Fasern. Nach entsprechender Verarbeitung vielseitig einsetzbar – robust, langlebig, kaum abriebanfällig.\n Man sagt, sie habe als Inspiration für Kabelkonstruktionen gedient.",
          TextMapId = "RESOURCE_DESC_20010"
        },
        RESOURCE_DESC_20011 = {
          ContentDE = "Aus Filthoiden gewonnenes Fett. Seine Zähigkeit hängt oft davon ab, wie stark der jeweilige Filthoid war.",
          TextMapId = "RESOURCE_DESC_20011"
        },
        RESOURCE_DESC_20012 = {
          ContentDE = "Aus der Elysischen Kirche. Zur Standardausrüstung der Ritter gehört ein fein gearbeitetes Kettenhemd aus zahllosen zarten Gliedern. Wenn der Orden ausrückt, ist sein Klirren die beste Kriegserklärung.",
          TextMapId = "RESOURCE_DESC_20012"
        },
        RESOURCE_DESC_20013 = {
          ContentDE = "Eine Währung, die nur unter den Lunarian zirkuliert, oft als Dankesgabe von jenen, die um Hilfe bitten.",
          TextMapId = "RESOURCE_DESC_20013"
        },
        RESOURCE_DESC_20014 = {
          ContentDE = "Der Schneeflink ist ein Vogel aus kalten Regionen und in Icelake häufig anzutreffen. Im Flug ist er so schnell, dass man ihn kaum mit bloßem Auge erfasst, nur bei Schneefall bleibt er länger auf Ästen oder im Nest. Seine Federn sind zäh und eignen sich gut als Schreibwerkzeug, doch heute nutzen nur noch wenige Traditionalisten und arme Haushalte diese billigen, aber kurzlebigen Federkiele.",
          TextMapId = "RESOURCE_DESC_20014"
        },
        RESOURCE_DESC_20015 = {
          ContentDE = "Aus dem Hyperboreischen Imperium: austauschbare Metallpanzer für die Standarduniform, meist an den Gelenken angebracht und besonders stoßfest. Bereits in Serienfertigung. Zwei Ersatzplatten gehören zur Standardausrüstung eines hyperboreischen Sturmtrupplers.",
          TextMapId = "RESOURCE_DESC_20015"
        },
        RESOURCE_DESC_20016 = {
          ContentDE = "Aus der Elysischen Kirche: Eine schildförmige Dekoration, getragen von Soldaten der Elysischen Kirche. Man sagt, es bündele göttlichen Segen. Ein Symbol des Schutzwillens gegenüber der Kirche.",
          TextMapId = "RESOURCE_DESC_20016"
        },
        RESOURCE_DESC_20017 = {
          ContentDE = "Aus Hyperborea. Die Beweglichkeit der Legion zu sichern, ist seit jeher ein Kernthema des Aeolipiles. Fahrzeugpanzerung ist eine der Antworten: Als Außenaufsatz trotzt sie Schneestürmen, Orkanböen und Hagel, und hält ein Fahrzeug auch unter Beschuss länger einsatzfähig. Muss es mit voller Geschwindigkeit voran, lässt sich die Panzerung rasch abwerfen.",
          TextMapId = "RESOURCE_DESC_20017"
        },
        RESOURCE_DESC_20018 = {
          ContentDE = "Eine von der Elysischen Kirche errichtete Statue der Schicksalsgöttin. So stark beschädigt, dass ihr ursprüngliches Antlitz nicht mehr zu erkennen ist. Und doch liegt in den Trümmern noch immer ihre anmutige Würde.\n Mit den Jahren treiben hier neue Knospen aus; vom Leben geschmückt, wirkt der Mythos, als wäre er nie verblasst.",
          TextMapId = "RESOURCE_DESC_20018"
        },
        RESOURCE_DESC_20019 = {
          ContentDE = "Ein von der Alchemie-Akademie entwickelter, konzentrierter Brandbeschleuniger. Eigentlich eine farblose Flüssigkeit mit stechendem Geruch. Zur Warnung wurde dieser Gegenstand rot eingefärbt. Nur für Militär und Industrie: Drei Löffel reichen, damit ein Kaminfeuer aus dem Schornstein schießt. Ein Anblick, den niemand erleben will.",
          TextMapId = "RESOURCE_DESC_20019"
        },
        RESOURCE_DESC_2002 = {
          ContentDE = "Aus deinen Erlebnissen geformte Strophen. Wenn alle Teile vollendet sind, wird daraus ein neues Lied geboren.\n Transkribiert und adaptiert von Lirico, diese Zeilen reiten auf dem Wind und den fallenden Blättern, hallen durch den Himmel von Atlasia – gesungen von Barden, geformt von jedem deiner Schritte.",
          TextMapId = "RESOURCE_DESC_2002"
        },
        RESOURCE_DESC_20020 = {
          ContentDE = "Ein gängiges Industriematerial: eine zähflüssige, weiße, latexartige Masse. Aufgetragen hilft sie, die Temperatur eines Gegenstands im Gleichgewicht zu halten. Bei unberechenbarem Gelände und Klima auf Reisen sind ein paar Dosen im Gepäck keine schlechte Idee. Da der Hersteller neuerdings Frucht- und Blütenduftvarianten anbietet, sei hiermit gewarnt: nicht versehentlich essen.",
          TextMapId = "RESOURCE_DESC_20020"
        },
        RESOURCE_DESC_20021 = {
          ContentDE = "Kerzen für Rituale der Elysischen Kirche, begleitet von Kerzenhaltern, die Handwerker in Andacht fertigten. Ihre Brenndauer ist kurz, doch ihr Licht reicht aus, das Antlitz der Gottheit zu erhellen.",
          TextMapId = "RESOURCE_DESC_20021"
        },
        RESOURCE_DESC_20022 = {
          ContentDE = "Eines der alchemistischen Erzeugnisse des Hyperboreischen Imperiums: ein Flüssigmetall, als könnte es jeden Moment zwischen den Fingern zerrinnen. Durch ein komplexes Reinigungsverfahren gewonnen und meist in der Rüstungsindustrie genutzt. Wer seinen Schmelzpunkt nicht im Griff hat, sollte es besser nicht leichtfertig erhitzen.",
          TextMapId = "RESOURCE_DESC_20022"
        },
        RESOURCE_DESC_20023 = {
          ContentDE = "Eine besondere Ware vom anderen Ende der Wüste. Lässt sich zu feinem Schmuck verarbeiten oder zur Verstärkung von Bauteilen nutzen. Die Qualität hängt allerdings davon ab, wie viel echter Sand sich unterwegs beigemischt hat. Da beides kaum zu unterscheiden ist, sollte man nur mit vertrauenswürdigen Händlern handeln.",
          TextMapId = "RESOURCE_DESC_20023"
        },
        RESOURCE_DESC_20024 = {
          ContentDE = "Eine von Filthoiden gewonnene Tentakel. Ihre Struktur ist äußerst zäh und stark haftend; manchmal wird sie als Befestigungsvorrichtung genutzt.\n Laufende Materialien gibt es überall, doch nur wenige bringen sie dazu, brav auf dem Hackblock liegenzubleiben.",
          TextMapId = "RESOURCE_DESC_20024"
        },
        RESOURCE_DESC_20025 = {
          ContentDE = "Ein Präzisionsinstrument aus dem Hyperboreischen Imperium, trotz Kratzern und Hebelspuren am Gehäuse noch völlig intakt.",
          TextMapId = "RESOURCE_DESC_20025"
        },
        RESOURCE_DESC_20026 = {
          ContentDE = "Ein kunstvoll verziertes Buch, das wie ein kostbarer Gedichtband wirkt, in Wahrheit jedoch ein Codebuch zur Entschlüsselung der internen Funkkommunikation der Legion.\n Leider zeigen die Innenseiten Spuren mutwilliger Beschädigung. Übrig geblieben sind nur belanglose Chiffren, zur echten Entschlüsselung von Funksprüchen taugt es nicht mehr.",
          TextMapId = "RESOURCE_DESC_20026"
        },
        RESOURCE_DESC_20027 = {
          ContentDE = "Aus der Elysischen Kirche: eine honigartige, ölige Flüssigkeit. Sie schärft Blankwaffen und dient zugleich der Pflege von Schusswaffen. Fast jeder Soldat der Kirche trägt mehrere Fläschchen bei sich. In den Pausen sieht man sie, wie sie das Mittel sorgfältig auf ihre Waffen auftragen und leise Gebete zum Zurückdrängen der Feinde murmeln.",
          TextMapId = "RESOURCE_DESC_20027"
        },
        RESOURCE_DESC_20028 = {
          ContentDE = "Aus dem Hyperboreischen Imperium: eine modifizierte Explosivkugel. Je nach Einsatzzweck stehen verschiedene austauschbare Geschossspitzen zur Verfügung. Geübte Schützen nutzen deren Eigenheiten, um die Detonation genau dort auszulösen, wo sie es haben wollen.",
          TextMapId = "RESOURCE_DESC_20028"
        },
        RESOURCE_DESC_20029 = {
          ContentDE = "Ein weit verbreiteter Hilfsständer mit Klemmen in mehreren Größen. Handwerker fixieren Waffen darauf, um sie zu justieren und fein abzustimmen.",
          TextMapId = "RESOURCE_DESC_20029"
        },
        RESOURCE_DESC_2003 = {
          ContentDE = "Erhalten durch das Abschließen von Tagebuchaufgaben. Wird verwendet, um tägliche Belohnung abzuholen.\n Von großen Zielen bis zu den kleinsten Besorgungen. Jeder Eintrag darauf bringt einen seinem Vorhaben näher, der Beweis, dass keine Mühe unbemerkt bleibt.",
          TextMapId = "RESOURCE_DESC_2003"
        },
        RESOURCE_DESC_20030 = {
          ContentDE = "Ein spezielles Sprühgerät für Ausrüstung. Damit lässt sich Rostschutzmittel gleichmäßig auftragen, um die Haltbarkeit zu erhöhen. Bei manchen Waffen kann es zudem die Leistung verbessern. Eine Verwechslung mit Serum-Injektoren hätte schwerwiegende Folgen. Unbedingt vorsichtig verwenden.",
          TextMapId = "RESOURCE_DESC_20030"
        },
        RESOURCE_DESC_20031 = {
          ContentDE = "Ein Polymer, das anhand von Filthoiden als Probe alchemistisch hergestellt wurde, ein Prunkstück der Spathatoi. Sein Herstellungsverfahren zählt zu den streng gehüteten Geheimnissen der Spathatoi.",
          TextMapId = "RESOURCE_DESC_20031"
        },
        RESOURCE_DESC_20032 = {
          ContentDE = "Eine eisige Flüssigkeit aus dem Norden, in einem Spezialbehälter verwahrt. Selbst bei Zimmertemperatur bilden sich Eiskristalle auf der Oberfläche. Ein Bild, das sonst in Gedichten auftaucht und nun als Kühlmittel dient.",
          TextMapId = "RESOURCE_DESC_20032"
        },
        RESOURCE_DESC_20033 = {
          ContentDE = "Ein Siegel zum Widerrufen einer Beschwörung.\n Das Beisammensein mag kurz gewesen sein, doch die Sehnsucht reißt nicht ab. Vielleicht liegt das nächste Wiedersehen nur einen Wimpernschlag entfernt.",
          TextMapId = "RESOURCE_DESC_20033"
        },
        RESOURCE_DESC_2004 = {
          ContentDE = "Aus deinen Erlebnissen geformte Strophen. Wenn alle Teile vollendet sind, wird daraus ein neues Lied geboren.\n Transkribiert und adaptiert von Lirico, diese Zeilen reiten auf dem Wind und den fallenden Blättern, hallen durch den Himmel von Atlasia – gesungen von Barden, geformt von jedem deiner Schritte.",
          TextMapId = "RESOURCE_DESC_2004"
        },
        RESOURCE_DESC_2007 = {
          ContentDE = "Ein Buch voller Erfahrungen im Umgang mit Waffen. Es wirkt schwer, doch genau diese „Gewichtung“ wird zu deiner Stärke.",
          TextMapId = "RESOURCE_DESC_2007"
        },
        RESOURCE_DESC_201 = {
          ContentDE = "Aus dem Hyperboreischen Imperium: ein Präzisionsgerät, das einem Werkzeugkasten ähnelt. Sobald die Zahnräder anlaufen, wird der darin platzierte Dämonenkeil so angepasst, dass er besser zum Zustand seines Trägers passt. Da es direkt am Anwender ansetzt, arbeitet dieses Modell besonders präzise, und kann nach der Anwendung die Fähigkeiten des Nutzers weiter steigern.",
          TextMapId = "RESOURCE_DESC_201"
        },
        RESOURCE_DESC_2011 = {
          ContentDE = "Ein einzelnes Notenblatt mit einem Heldengesang, der unter Wanderbarden kursiert, übersät mit handschriftlichen Anmerkungen und Korrekturen. Um ihre Ansichten vollständig darzulegen, haben die Barden jede noch so kleine Lücke mit winziger Schrift für Debatten genutzt. Auf engstem Raum werden Standpunkte aufgebaut und wieder verworfen, die ganze Seite zu lesen, ist fast ein Nervenspiel.",
          TextMapId = "RESOURCE_DESC_2011"
        },
        RESOURCE_DESC_202 = {
          ContentDE = "Aus dem Hyperboreischen Imperium: ein Präzisionsgerät, das einem Werkzeugkasten ähnelt. Sobald die Zahnräder anlaufen, wird der darin platzierte Dämonenkeil so angepasst, dass er besser zum Zustand seines Trägers passt. Dieses Modell ist besonders gut darin, verschiedenste Standardwaffen auszulesen, und kann nach der Anwendung die Leistungsfähigkeit der Waffe weiter erhöhen.",
          TextMapId = "RESOURCE_DESC_202"
        },
        RESOURCE_DESC_203 = {
          ContentDE = "Alles wird verbrennen, alles wird verschlungen werden, zu Asche und Schlacke zermahlen, bis es im Abgrund aufgeht.",
          TextMapId = "RESOURCE_DESC_203"
        },
        RESOURCE_DESC_204 = {
          ContentDE = "Ein von der Alchemie-Akademie entwickeltes Mittel, das die Ausdauer steigert, ein weit verbreiteter Militärbedarf.",
          TextMapId = "RESOURCE_DESC_204"
        },
        RESOURCE_DESC_205 = {
          ContentDE = "Ein Splitter eines heiligen Relikts, aus dem Abgrund über zahllose Zyklen hinweg geborgen. In ihm scheint ein Segen von unvergleichlicher Größe zu ruhen.",
          TextMapId = "RESOURCE_DESC_205"
        },
        RESOURCE_DESC_20500 = {
          ContentDE = "Ein Schlüsselchen, das jemand zurückgelassen hat. Öffnet eine verschlossene Truhe.",
          TextMapId = "RESOURCE_DESC_20500"
        },
        RESOURCE_DESC_20510 = {
          ContentDE = "Ein Statuenfragment. Der Beschaffenheit nach stammt es wohl von der Schicksalsgöttin im geheimnisvollen Ruinenkomplex von Purgatorio-Insel. Ob wohl etwas Gutes geschieht, wenn man die Statue damit repariert?",
          TextMapId = "RESOURCE_DESC_20510"
        },
        RESOURCE_DESC_20511 = {
          ContentDE = "Rohes Erz, draußen verstreut. Mit etwas Schmiedearbeit könnte es brauchbar sein.",
          TextMapId = "RESOURCE_DESC_20511"
        },
        RESOURCE_DESC_20512 = {
          ContentDE = "Eine herrenlose Silbermünze. Den Besitzer ausfindig zu machen, dürfte schwierig werden.",
          TextMapId = "RESOURCE_DESC_20512"
        },
        RESOURCE_DESC_20513 = {
          ContentDE = "Klare, funkelnde und doch billige Erzsplitter. Zum Raffinieren taugen sie kaum, doch als „erstes Schmuckstück“ vom Jungen für das Mädchen sind sie unbezahlbar.",
          TextMapId = "RESOURCE_DESC_20513"
        },
        RESOURCE_DESC_20514 = {
          ContentDE = "Abgenutzte Schutzrüstung. Warum ihr Besitzer sie zurückließ, ist unklar.",
          TextMapId = "RESOURCE_DESC_20514"
        },
        RESOURCE_DESC_20515 = {
          ContentDE = "Ein zurückgelassenes Abzeichen. Sein früherer Besitzer hat es wohl zu Geld gemacht.",
          TextMapId = "RESOURCE_DESC_20515"
        },
        RESOURCE_DESC_20516 = {
          ContentDE = "Wenn von Schrott die Rede ist, denkt man zuerst an leere Flaschen und Dosen. Genug davon zusammenzukratzen und zu verkaufen, reicht für das Nötigste, mehr aber auch nicht.",
          TextMapId = "RESOURCE_DESC_20516"
        },
        RESOURCE_DESC_20517 = {
          ContentDE = "Grundmaterial fürs Überleben in der Wildnis: taugt für einfache Werkzeuge oder als Brennstoff zum Wärmen.",
          TextMapId = "RESOURCE_DESC_20517"
        },
        RESOURCE_DESC_20518 = {
          ContentDE = "Ein Edelstein, der unendlich lange auf der Hand einer Göttinnenstatue auf Purgatorio-Insel gelegen hat. Könnte er sprechen, hätte er gewiss viele Geschichten, doch am Ende ist er nur ein strahlend schöner Stein.",
          TextMapId = "RESOURCE_DESC_20518"
        },
        RESOURCE_DESC_206 = {
          ContentDE = "Erhöht die Belohnungen bei Missionen um 100 %.\n Seit die Nachtfahrer unter den Phoxjägern zunehmend Bekanntheit erlangen, häufen sich auch namentlich zugewiesene Missionen. Das bedeutet zwar mehr Arbeit, bringt aber auch deutlich üppigere Entlohnung.",
          TextMapId = "RESOURCE_DESC_206"
        },
        RESOURCE_DESC_207 = {
          ContentDE = "Erhöht die Belohnungen bei Missionen um 200 %.\n Seit die Nachtfahrer unter den Phoxjägern zunehmend Bekanntheit erlangen, häufen sich auch namentlich zugewiesene Missionen. Das bedeutet zwar mehr Arbeit, bringt aber auch deutlich üppigere Entlohnung.",
          TextMapId = "RESOURCE_DESC_207"
        },
        RESOURCE_DESC_208 = {
          ContentDE = "Erhöht die Belohnungen bei Missionen um 800 %.\n Seit die Nachtfahrer unter den Phoxjägern zunehmend Bekanntheit erlangen, häufen sich auch namentlich zugewiesene Missionen. Das bedeutet zwar mehr Arbeit, bringt aber auch deutlich üppigere Entlohnung.",
          TextMapId = "RESOURCE_DESC_208"
        },
        RESOURCE_DESC_209 = {
          ContentDE = "Erhöht die Belohnungen bei Missionen um 2000 %.\n Seit die Nachtfahrer unter den Phoxjägern zunehmend Bekanntheit erlangen, häufen sich auch namentlich zugewiesene Missionen. Das bedeutet zwar mehr Arbeit, bringt aber auch deutlich üppigere Entlohnung.",
          TextMapId = "RESOURCE_DESC_209"
        },
        RESOURCE_DESC_210 = {
          ContentDE = "Eine Münze, auf der das Emblem eines Fisches eingraviert ist – bei Anglern aus aller Welt sehr beliebt. Je mehr man sammelt, desto höher steigt man in der Angel-Rangliste auf. Du kannst sie gegen bessere Ausrüstung eintauschen und dich damit als der beste Angler überhaupt beweisen.",
          TextMapId = "RESOURCE_DESC_210"
        },
        RESOURCE_DESC_211 = {
          ContentDE = "Gerüchte einholen und Hinweise zusammensetzen gehört zum Handwerk der Phoxjäger. Wer beharrlich dranbleibt und stetig aufbaut, dem flattern Missionen bald in Scharen ins Haus.",
          TextMapId = "RESOURCE_DESC_211"
        },
        RESOURCE_DESC_214 = {
          ContentDE = "Mit Bühnenlicht und Herzschlag geprägt, bewahrt es das Nachglühen der Show. Kann gegen verschiedene Gegenstände eingelöst werden.",
          TextMapId = "RESOURCE_DESC_214"
        },
        RESOURCE_DESC_215 = {
          ContentDE = "Ein Schicksal aus unzähligen Wegen, das jeden Augenblick festhält, den „du“ gegangen bist. Alles, was dich verwirrte, alles, was enttäuscht wurde, alles, woraus es kein Entrinnen gab ... wird am Ende auf Ihren Spinnfäden eine Antwort finden.",
          TextMapId = "RESOURCE_DESC_215"
        },
        RESOURCE_DESC_216 = {
          ContentDE = "Schwere Missionen und außergewöhnliche Abenteuer schreiben gemeinsam die Legende der Phoxjäger, besungen in Straßen und Gassen.",
          TextMapId = "RESOURCE_DESC_216"
        },
        RESOURCE_DESC_217 = {
          ContentDE = "Schaltet in der Aktion „Phoxjäger-Stufen“ die Herausforderung der Apex-Rangliste frei",
          TextMapId = "RESOURCE_DESC_217"
        },
        RESOURCE_DESC_218 = {
          ContentDE = "Wird im Apex-Shop der Aktion „Phoxjäger-Stufen“ gegen Waren eingetauscht",
          TextMapId = "RESOURCE_DESC_218"
        },
        RESOURCE_DESC_29001 = {
          ContentDE = "Abzeichen, die überall auf Purgatorio-Insel gesammelt werden können. Sie sind der Beweis für Mut, Weisheit und Geduld während der Expedition. Sammle genug davon und überreiche sie der Luno-Abenteurerin auf dem Platz von Icelake, um wertvolle Belohnungen zu erhalten.",
          TextMapId = "RESOURCE_DESC_29001"
        },
        RESOURCE_DESC_29002 = {
          ContentDE = "Abzeichen, die in ganz Icelake gesammelt werden können. Sie sind der Beweis für Mut, Weisheit und Geduld während der Expedition. Sammle genug davon und überreiche sie der Luno-Abenteurerin auf dem Platz von Icelake, um wertvolle Belohnungen zu erhalten.",
          TextMapId = "RESOURCE_DESC_29002"
        },
        RESOURCE_DESC_29003 = {
          ContentDE = "Abzeichen, die in ganz Lonza-Festung gesammelt werden können. Sie sind der Beweis für Mut, Weisheit und Geduld während der Expedition. Sammle genug davon und überreiche sie der Luno-Abenteurerin auf dem Platz von Icelake, um wertvolle Belohnungen zu erhalten.",
          TextMapId = "RESOURCE_DESC_29003"
        },
        RESOURCE_DESC_29004 = {
          ContentDE = "Abzeichen, die in ganz Nebelkai gesammelt werden können. Sie sind der Beweis für Mut, Weisheit und Geduld während der Expedition. Sammle genug davon und überreiche sie der Luno-Abenteurerin in Dunstmarkt, um wertvolle Belohnungen zu erhalten.",
          TextMapId = "RESOURCE_DESC_29004"
        },
        RESOURCE_DESC_29005 = {
          ContentDE = "Leuchtende Runen, die in Huaxu in der Luft schweben. Man sagt, sie entstünden, wenn Taixu durch Weihrauch erweckt wird. Mit der Sogkraft der Mechanischen Nexus lassen sie sich einsammeln.",
          TextMapId = "RESOURCE_DESC_29005"
        },
        RESOURCE_DESC_3000001 = {
          ContentDE = "Eine Schachtel Papiersterne, gefaltet aus abgelaufenen Fahrkarten. Man sagt, eine bestimmte Anzahl davon könne Wünsche wahr werden lassen, offenbar stimmt das nicht.",
          TextMapId = "RESOURCE_DESC_3000001"
        },
        RESOURCE_DESC_3000002 = {
          ContentDE = "In das dünne, abgetragene Futter ist ein handtellergroßes Tagebuch eingenäht. Auf dem Einband ist der Name „Alice“ noch halbwegs zu erkennen, doch die meisten Einträge sind von Flecken verschluckt, nur die jüngsten Zeilen lassen sich gerade noch entziffern.",
          TextMapId = "RESOURCE_DESC_3000002"
        },
        RESOURCE_DESC_3000003 = {
          ContentDE = "Ein zerfledderter Abenteuerroman: Der Held stürmt mit seinem mageren Pferd eine Burg und erbeutet am Ende den Schatz.",
          TextMapId = "RESOURCE_DESC_3000003"
        },
        RESOURCE_DESC_3000004 = {
          ContentDE = "Ein Porträt von Berenica im Profil, aus Draht gebogen. Die Gesichtszüge sind erstaunlich treffsicher eingefangen.",
          TextMapId = "RESOURCE_DESC_3000004"
        },
        RESOURCE_DESC_3000005 = {
          ContentDE = "Ein standardisiertes Sanitätsset der Legion. Enthält diverse Mittel zum Stillen von Blutungen und zum Lindern von Schmerzen, für allzu schwere Verletzungen hilft es jedoch kaum.",
          TextMapId = "RESOURCE_DESC_3000005"
        },
        RESOURCE_DESC_3000006 = {
          ContentDE = "Ein Foto, das Avar dicht bei sich trägt. Darauf ist er mit Daphne aus Kindertagen zu sehen. Der vergilbte Film kann das strahlende Lächeln nicht verbergen.",
          TextMapId = "RESOURCE_DESC_3000006"
        },
        RESOURCE_DESC_3000007 = {
          ContentDE = "Ein Foto, das Avar dicht bei sich trägt. Darauf ist er mit Daphne aus Kindertagen zu sehen. Das strahlende Lächeln wird von dunkelrotem Blut überdeckt.",
          TextMapId = "RESOURCE_DESC_3000007"
        },
        RESOURCE_DESC_3000008 = {
          ContentDE = "Eine Blume aus Psyche, am Stiel scheint noch die Restwärme ihrer Handfläche zu haften.",
          TextMapId = "RESOURCE_DESC_3000008"
        },
        RESOURCE_DESC_3000009 = {
          ContentDE = "Ein schlichtes Rezept, doch die Rückseite ist voller gefährlicher Zeichen, welche die Leute aus dem Imperium nicht sehen dürfen.",
          TextMapId = "RESOURCE_DESC_3000009"
        },
        RESOURCE_DESC_3000010 = {
          ContentDE = "Ein Geschenk von Faye: ein von ihr eigenhändig gemaltes „Porträt“ von dir – für dich wirkt das rot-weiß verschlungene Farbgewirr höchstens entfernt menschenähnlich und lässt nicht einmal Geschlecht erkennen, aber wenn sie sagt, es bist du, dann ist es wohl so. Vermutlich braucht man für den Geschmack der Leute aus der Innenstadt eine gewisse „Einstiegshürde“.",
          TextMapId = "RESOURCE_DESC_3000010"
        },
        RESOURCE_DESC_3000011 = {
          ContentDE = "Ein kunstvoll gefertigter Schlüssel, seltsam vertraut, und doch fällt dir seine Herkunft nicht ein. Vielleicht wird er dir, wenn die Zeit reif ist, eine längst schlummernde Geschichte wieder öffnen.",
          TextMapId = "RESOURCE_DESC_3000011"
        },
        RESOURCE_DESC_30001 = {
          ContentDE = "Gelartiges Material zur Herstellung von Spurwechselmodulen. Reine Zusammensetzung, wasserlöslich und bei Hitze inaktiv, daher nur unter strengen Bedingungen lagerbar. Trotzdem ist sein Nutzen groß genug, um es mitzuführen.",
          TextMapId = "RESOURCE_DESC_30001"
        },
        RESOURCE_DESC_30002 = {
          ContentDE = "Material zur Herstellung von Waffen-Spurwechselmodulen. Speziell behandelte Magnetsteine reagieren auf unterschiedliche Metallbauteile mit Vibrationen in verschiedenen Frequenzen. Erfahrene Nutzer spüren so selbst kleinste Unregelmäßigkeiten in einer Waffe auf.",
          TextMapId = "RESOURCE_DESC_30002"
        },
        RESOURCE_DESC_3001 = {
          ContentDE = "Wird verwendet, um nach einer fehlgeschlagenen Eindruck-Prüfung erneut zu prüfen.\n Zwischen Menschen läuft es nie ohne Stolpersteine. Stelle dich ihnen. Warum nicht noch einmal versuchen?",
          TextMapId = "RESOURCE_DESC_3001"
        },
        RESOURCE_DESC_3002 = {
          ContentDE = "Eine Lieblingsleckerei der Geniemons. Wird verwendet, um sie zu füttern.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „M-mmh! Lecker!“",
          TextMapId = "RESOURCE_DESC_3002"
        },
        RESOURCE_DESC_3003 = {
          ContentDE = "Eine absolute Lieblingsleckerei der Geniemons. Wird verwendet, um sie zu füttern.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „M-mmh! M-mmh! Lecker!“",
          TextMapId = "RESOURCE_DESC_3003"
        },
        RESOURCE_DESC_3004 = {
          ContentDE = "Eine bei Geniemons beliebte Nährpaste. Wird zum Geniemon-Hochstufen verwendet und gewährt 100 EP.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „Lecker!“",
          TextMapId = "RESOURCE_DESC_3004"
        },
        RESOURCE_DESC_3005 = {
          ContentDE = "Eine bei Geniemons beliebte Nährpaste. Wird zum Geniemon-Hochstufen verwendet und gewährt 300 EP.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „M-mmh! Lecker!“",
          TextMapId = "RESOURCE_DESC_3005"
        },
        RESOURCE_DESC_3006 = {
          ContentDE = "Eine bei Geniemons beliebte Nährpaste. Wird zum Geniemon-Hochstufen verwendet und gewährt 1000 EP.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „M-mmh! M-mmh! Lecker!“",
          TextMapId = "RESOURCE_DESC_3006"
        },
        RESOURCE_DESC_3007 = {
          ContentDE = "Eine bei Geniemons beliebte Getränkespezialität. Wird zum Geniemon-Aufsteigen verwendet.\n Ganz wie der Name verspricht: Könnten Geniemons sprechen, würden sie garantiert rufen: „M-mmh! Lecker!“",
          TextMapId = "RESOURCE_DESC_3007"
        },
        RESOURCE_DESC_3008 = {
          ContentDE = "Eine Lieblingsleckerei der Geniemons. Wird verwendet, um sie zu füttern, und in Eldritch-Geniemon zu verwandeln.\n Für Geniemons so lecker, dass sie sich glatt verformen.",
          TextMapId = "RESOURCE_DESC_3008"
        },
        RESOURCE_DESC_3010 = {
          ContentDE = "Erhöht das Eindruck-Attribut „Nutzen“ einer Figur in Icelake",
          TextMapId = "RESOURCE_DESC_3010"
        },
        RESOURCE_DESC_30101 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie der Klagende See hervorbringt.",
          TextMapId = "RESOURCE_DESC_30101"
        },
        RESOURCE_DESC_30102 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Meersalz hervorbringt.",
          TextMapId = "RESOURCE_DESC_30102"
        },
        RESOURCE_DESC_30103 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Baumkronen hervorbringt.",
          TextMapId = "RESOURCE_DESC_30103"
        },
        RESOURCE_DESC_30104 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Erbsen hervorbringt.",
          TextMapId = "RESOURCE_DESC_30104"
        },
        RESOURCE_DESC_30105 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Dünen hervorbringt.",
          TextMapId = "RESOURCE_DESC_30105"
        },
        RESOURCE_DESC_30106 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Roterde hervorbringt.",
          TextMapId = "RESOURCE_DESC_30106"
        },
        RESOURCE_DESC_30107 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Rouge hervorbringt.",
          TextMapId = "RESOURCE_DESC_30107"
        },
        RESOURCE_DESC_30108 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie Rabengefieder hervorbringt.",
          TextMapId = "RESOURCE_DESC_30108"
        },
        RESOURCE_DESC_30109 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie ein Gewitterhimmel hervorbringt.",
          TextMapId = "RESOURCE_DESC_30109"
        },
        RESOURCE_DESC_3011 = {
          ContentDE = "Erhöht das Eindruck-Attribut „Moral“ einer Figur in Icelake",
          TextMapId = "RESOURCE_DESC_3011"
        },
        RESOURCE_DESC_30110 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie ein Sternenstrom hervorbringt.",
          TextMapId = "RESOURCE_DESC_30110"
        },
        RESOURCE_DESC_30111 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der Töne wie reife Ähren hervorbringt.",
          TextMapId = "RESOURCE_DESC_30111"
        },
        RESOURCE_DESC_30112 = {
          ContentDE = "Ein Farbstoff aus mehreren Rohstoffen, der die Farbe jedes Basisfarbstoffs hervorbringt.",
          TextMapId = "RESOURCE_DESC_30112"
        },
        RESOURCE_DESC_3012 = {
          ContentDE = "Erhöht das Eindruck-Attribut „Weisheit“ einer Figur in Icelake",
          TextMapId = "RESOURCE_DESC_3012"
        },
        RESOURCE_DESC_3013 = {
          ContentDE = "Erhöht das Eindruck-Attribut „Empathie“ einer Figur in Icelake",
          TextMapId = "RESOURCE_DESC_3013"
        },
        RESOURCE_DESC_3014 = {
          ContentDE = "Erhöht das Eindruck-Attribut „Chaos“ einer Figur in Icelake",
          TextMapId = "RESOURCE_DESC_3014"
        },
        RESOURCE_DESC_3016 = {
          ContentDE = "Ein von Alchemisten gefertigtes Verstärkungswerkzeug für Dämonenkeile. An der materialarmen Front war es lange ein leidiges Problem, mit begrenzten Mitteln das grenzenlose Potenzial eines Dämonenkeils schnell zu entfalten.",
          TextMapId = "RESOURCE_DESC_3016"
        },
        RESOURCE_DESC_3017 = {
          ContentDE = "Erhöht den Nutzen-Eindruck der Figur in Huaxu",
          TextMapId = "RESOURCE_DESC_3017"
        },
        RESOURCE_DESC_3018 = {
          ContentDE = "Erhöht den Moral-Eindruck der Figur in Huaxu",
          TextMapId = "RESOURCE_DESC_3018"
        },
        RESOURCE_DESC_3019 = {
          ContentDE = "Erhöht den Weisheit-Eindruck der Figur in Huaxu",
          TextMapId = "RESOURCE_DESC_3019"
        },
        RESOURCE_DESC_3020 = {
          ContentDE = "Erhöht den Empathie-Eindruck der Figur in Huaxu",
          TextMapId = "RESOURCE_DESC_3020"
        },
        RESOURCE_DESC_3021 = {
          ContentDE = "Erhöht den Chaos-Eindruck der Figur in Huaxu",
          TextMapId = "RESOURCE_DESC_3021"
        },
        RESOURCE_DESC_40001 = {
          ContentDE = "Ein Fläschchen Sal Volatil, ein Muss in jedem Verbandskasten. Wenn Krankheit oder Schmerz den Kopf vernebeln, schenkt es dir für einen Moment Klarheit.",
          TextMapId = "RESOURCE_DESC_40001"
        },
        RESOURCE_DESC_40003 = {
          ContentDE = "Eine Versorgungskiste voller Munition, Quelle des Überlebens und Ende des Lebens zugleich, auf dem Schlachtfeld.",
          TextMapId = "RESOURCE_DESC_40003"
        },
        RESOURCE_DESC_4010001 = {
          ContentDE = "Eine Unterart des Schmetterlings: Sein sattes Grün ist der Ruf des Frühlings.",
          TextMapId = "RESOURCE_DESC_4010001"
        },
        RESOURCE_DESC_4010002 = {
          ContentDE = "Eine Unterart des Schmetterlings: Sein Indigoblau wirkt rein und schneidend kühl.",
          TextMapId = "RESOURCE_DESC_4010002"
        },
        RESOURCE_DESC_4010003 = {
          ContentDE = "Farbloses, geschmackloses Quellwasser. In Elysium glaubt man, es sei ein Geschenk der Götter, es reinige Körper und Geist und spüle den Staub der Welt fort.",
          TextMapId = "RESOURCE_DESC_4010003"
        },
        RESOURCE_DESC_4010004 = {
          ContentDE = "Ein Pilz, der selbst unter extremer Kälte überlebt. Von außen wird er oft für ein Häufchen ungeschmolzener Schneeflocken gehalten, doch er enthält Giftstoffe. Bei Verzehr kann er Halluzinationen auslösen, im Ernstfall lebensgefährlich.\n \n NICHT ESSEN! NICHT ESSEN! NICHT ESSEN!",
          TextMapId = "RESOURCE_DESC_4010004"
        },
        RESOURCE_DESC_4010005 = {
          ContentDE = "Eine Flüssigkeit, die hauptsächlich aus Phoxenen gewonnen wird. Als wichtigste Energiequelle hält sie das Hyperboreische Imperium am Laufen. Ihre Einsatzgebiete sind weit zahlreicher, als man gemeinhin annimmt.",
          TextMapId = "RESOURCE_DESC_4010005"
        },
        RESOURCE_DESC_4010006 = {
          ContentDE = "Eine der verbreiteten Blütenpflanzen auf dem Kontinent Atlasia. Kann medizinisch verwendet werden.",
          TextMapId = "RESOURCE_DESC_4010006"
        },
        RESOURCE_DESC_4010007 = {
          ContentDE = "Jeden Tag spült das Meer Muscheln an den Strand, doch eine unversehrte, farbenprächtige zu finden, ist immer ein kleines Glück.",
          TextMapId = "RESOURCE_DESC_4010007"
        },
        RESOURCE_DESC_4010008 = {
          ContentDE = "Eine kälte liebende Süßwasserpflanze, die man „Winterlotus“ nennt. Ihre Samen sind durchsichtig, traumhaft wie Schaum und ebenso zerbrechlich.\n \n HOCHGIFTIG! HOCHGIFTIG! HOCHGIFTIG!",
          TextMapId = "RESOURCE_DESC_4010008"
        },
        RESOURCE_DESC_4010009 = {
          ContentDE = "Ein unverzichtbares Notstromgerät für große Anlagen. Enthält vorkalibrierten Phoxichor und kann lange im Aktivzustand bleiben. Zum Einsatz einfach in den vorgesehenen Energieschacht der Maschine einsetzen.",
          TextMapId = "RESOURCE_DESC_4010009"
        },
        RESOURCE_DESC_4010010 = {
          ContentDE = "Eine häufige kleine Blume ohne offiziellen Namen. Je nach Region hat sie andere Bezeichnungen. Kaum beachtet und nie absichtlich angepflanzt, doch egal wie oft man sie pflückt, blüht sie nach einer Weile wieder in Massen. Erstaunlich zäh.",
          TextMapId = "RESOURCE_DESC_4010010"
        },
        RESOURCE_DESC_4010011 = {
          ContentDE = "Eine Pflanze, die in den Fugen von Stein und Ziegeln wurzelt. Sie mag feuchte Schattenplätze, scheut aber selbst starke Lichtstrahlung nicht; kältefest, dürrefest und genügsam. Manche Haushalte streuen gezielt Samen der Heiligen Klangglöckchen an ihre Wände, und ernten im nächsten Jahr einen natürlichen Wandschmuck.",
          TextMapId = "RESOURCE_DESC_4010011"
        },
        RESOURCE_DESC_4010012 = {
          ContentDE = "Häufig in dicht bewaldeten Gegenden zu finden. In manchen abgelegenen Regionen gelten Vogeleier als beliebtes Frühstück. Stehle aber besser keine Nester in Hausnähe. Wenn die Nestbesitzerin dich erwischt, werden deine Fensterscheiben wohl nie wieder sauber.",
          TextMapId = "RESOURCE_DESC_4010012"
        },
        RESOURCE_DESC_4010013 = {
          ContentDE = "Ein essbarer Pilz mit ausgezeichnetem Geschmack, auf dem ganzen Kontinent verbreitet. Fast jedes Land hat seine ganz eigene Art, ihn zuzubereiten.",
          TextMapId = "RESOURCE_DESC_4010013"
        },
        RESOURCE_DESC_4010014 = {
          ContentDE = "Die häufigste und zugleich wichtigste Blume Huaxus. Sie wächst im Verbund mit der Himmelbaum, gedeiht jedoch ausschließlich in Huaxu. In voller Blüte verströmt sie einen betörenden Duft; zermahlen und nach besonderem Verfahren mit Himmelbaumstaub vermengt, lässt sich daraus ein Räucherwerk gewinnen, das die Kristallstaubkünste verstärkt. Ausgerechnet diese zarten Pflanzen, die man mit einem Griff zerdrückt, tragen das gewaltige Gefüge der Himmelsgesetze.",
          TextMapId = "RESOURCE_DESC_4010014"
        },
        RESOURCE_DESC_4010015 = {
          ContentDE = "Ein Erzeugnis der Plage von Zhuyin. Diese Kristalle hemmen das Wachstum von Pflanzen und bringen so ganze Gebiete ökologisch zum Stillstand. Wegen dieser rücksichtslosen Eigenschaft nennt man sie „Räuberstein“.",
          TextMapId = "RESOURCE_DESC_4010015"
        },
        RESOURCE_DESC_4010016 = {
          ContentDE = "Zerbrochene Waffen, wie sie auf der Krähenlied-Hohl überall liegen. Einige wurden mit dem Wasser bis nach Dunstmarkt getrieben. Stumme Zeugen der düsteren Vergangenheit der Xuanheng-Sekte und Jishu-Sekte. Könnten sie sprechen und ehrlich erzählen, was sie sahen und hörten, wäre Huaxu heute vielleicht ein anderes.",
          TextMapId = "RESOURCE_DESC_4010016"
        },
        RESOURCE_DESC_4010017 = {
          ContentDE = "Ein in Huaxu verbreitetes Insekt. Man sagt, sein Zirpen klinge wie ein Webstuhl, daher der Name. Es passt seine Farbe der Umgebung an; im Sommer ist die Suche danach zwischen Gras und Bäumen ein beliebter Zeitvertreib der Kinder.",
          TextMapId = "RESOURCE_DESC_4010017"
        },
        RESOURCE_DESC_4010018 = {
          ContentDE = "Auch „Erdloong“ genannt. Er sonnt sich gern auf warmen Steinen, ist aber erstaunlich wachsam: Spürt er durch den Fels die Erschütterung des Bodens, verschwindet er sofort in versteckten Spalten. Manche halten ihn sogar als Haustier. Der leuchtend blaue Schwanz soll sich überraschend angenehm anfühlen.",
          TextMapId = "RESOURCE_DESC_4010018"
        },
        RESOURCE_DESC_4010019 = {
          ContentDE = "Ein Frosch, der starr zum Himmel hinaufsieht, als würde er mit ihm Zwiesprache halten. Erfahrene Bauern wissen: Wenn der Regenblick-Frosch unablässig ruft, rückt ein Schauer näher. Es ist die Zeit, das getrocknete Getreide einzuholen.",
          TextMapId = "RESOURCE_DESC_4010019"
        },
        RESOURCE_DESC_4010020 = {
          ContentDE = "Einst war es eine gewöhnliche Grünfliege, überall zu finden. Doch wie die Gritblight-Ebene einst ein lebendiges Grünland war, hat die Plage von Zhuyin hier alles nach und nach mit Staubstau befleckt, bis es zu einem unheilvollen Schwarzviolett wurde.",
          TextMapId = "RESOURCE_DESC_4010020"
        },
        RESOURCE_DESC_4020001 = {
          ContentDE = "Stattliche braune Nüsse, ebenfalls essbar – vorausgesetzt, man bekommt ihre steinharte Schale auf, wie ein Nagetier.",
          TextMapId = "RESOURCE_DESC_4020001"
        },
        RESOURCE_DESC_4020002 = {
          ContentDE = "Eine seltenere Eisenschalennuss, ebenfalls essbar. Sie ist fettreicher als die gewöhnliche Eisenschalennuss und springt beim Rösten von selbst auf, einer der Lieblingssnacks der Kinder.",
          TextMapId = "RESOURCE_DESC_4020002"
        },
        RESOURCE_DESC_4020003 = {
          ContentDE = "Ein silbrig schimmerndes Erz, dessen Metallglanz je nach Reinheit von Schwarz bis Silber reicht.",
          TextMapId = "RESOURCE_DESC_4020003"
        },
        RESOURCE_DESC_4020004 = {
          ContentDE = "Eine seltenere Variante von Silberit: Mit eingemischten Verunreinigungen, und gerade deshalb noch auffälliger im Schimmer.",
          TextMapId = "RESOURCE_DESC_4020004"
        },
        RESOURCE_DESC_4020005 = {
          ContentDE = "Fachlich „Seestein“ genannt, im Volksmund jedoch „Ploppstein“, weil ihn fast jeder schon einmal zum Steinehüpfen benutzt hat. Wie oft es „plopp“ macht, ist eine der wichtigsten Voraussetzungen, um zum Anführer der Kinder zu taugen.",
          TextMapId = "RESOURCE_DESC_4020005"
        },
        RESOURCE_DESC_4020006 = {
          ContentDE = "Weiße Stalaktiten, die die Menschen Huaxus „Bergkoralle“ nennen. Ihre Existenz bezeugt zahllose Jahre von Wandel zwischen Bergen und Meeren. Zu Pulver vermahlen und eingenommen, sollen sie Husten bei schwacher Lunge sowie allgemeine Schwäche lindern, kratzen allerdings etwas im Hals.",
          TextMapId = "RESOURCE_DESC_4020006"
        },
        RESOURCE_DESC_4030001 = {
          ContentDE = "Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030001"
        },
        RESOURCE_DESC_4030002 = {
          ContentDE = "Ein Schmiedehammer der Luno-Schmiedin, stark genug, um fast jedes Material in Form zu bringen. Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030002"
        },
        RESOURCE_DESC_4030003 = {
          ContentDE = "Bankettkerzen, bereitgestellt von der Luno-Dienerin, die überall eine warme, gemütliche Atmosphäre verbreiten. Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030003"
        },
        RESOURCE_DESC_4030004 = {
          ContentDE = "Ein Notfallset zusammengestellt von Luno-Schwermut. Mit Vorräten für dreißig Tage, bestehend aus konservierten Lebensmitteln, Trinkwasser und einfachen Nähutensilien. Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030004"
        },
        RESOURCE_DESC_4030005 = {
          ContentDE = "Eine Auswahl an „stilvollen“ Kleinigkeiten der Luno-Abenteurerin. Sie sind überraschend schöne Dekoartikel – obwohl sie bei näherer Betrachtung eigentlich nur Steine, Muscheln und Blätter sind, die sie auf ihren Reisen gesammelt hat. Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030005"
        },
        RESOURCE_DESC_4030006 = {
          ContentDE = "Karmesinrote Seide aus Huaxu, geliefert von einer eingeladenen Luno-Sternenweberin – glatt, glänzend und eine Seltenheit in Icelake. Wird verwendet, um die feierliche Stimmung während der Aktion „Festliches Beisammensein“ zu steigern",
          TextMapId = "RESOURCE_DESC_4030006"
        },
        RESOURCE_DESC_41001 = {
          ContentDE = "Aus irgendeinem Grund hört man beim Grillen immer eine vertraute, beschwingte Melodie.",
          TextMapId = "RESOURCE_DESC_41001"
        },
        RESOURCE_DESC_41002 = {
          ContentDE = "Hier ist niemand. Nur ein Karton.",
          TextMapId = "RESOURCE_DESC_41002"
        },
        RESOURCE_DESC_41003 = {
          ContentDE = "Magie, erstaunlich, nicht wahr?",
          TextMapId = "RESOURCE_DESC_41003"
        },
        RESOURCE_DESC_41004 = {
          ContentDE = "Hier ist niemand. Nur Gebüsch.",
          TextMapId = "RESOURCE_DESC_41004"
        },
        RESOURCE_DESC_41005 = {
          ContentDE = "Hier ist niemand. Nur ein Karton.",
          TextMapId = "RESOURCE_DESC_41005"
        },
        RESOURCE_DESC_41006 = {
          ContentDE = "Hier ist niemand. Nur ein Karton.",
          TextMapId = "RESOURCE_DESC_41006"
        },
        RESOURCE_DESC_41007 = {
          ContentDE = "Die Waffe immer wieder zu prüfen, gehört zu den zuverlässigsten Wegen, die eigenen Chancen zu erhöhen.",
          TextMapId = "RESOURCE_DESC_41007"
        },
        RESOURCE_DESC_41008 = {
          ContentDE = "Die Waffe immer wieder zu prüfen, gehört zu den zuverlässigsten Wegen, die eigenen Chancen zu erhöhen.",
          TextMapId = "RESOURCE_DESC_41008"
        },
        RESOURCE_DESC_41009 = {
          ContentDE = "Gerade Gewohnheitsbewegungen verraten oft, was tief im Inneren wirklich vorgeht.",
          TextMapId = "RESOURCE_DESC_41009"
        },
        RESOURCE_DESC_41010 = {
          ContentDE = "Niemand kann einer Truhe widerstehen, die einem unterwegs vor die Füße fällt.",
          TextMapId = "RESOURCE_DESC_41010"
        },
        RESOURCE_DESC_41011 = {
          ContentDE = "Hilfe! Das Bett lässt mich nicht mehr los.",
          TextMapId = "RESOURCE_DESC_41011"
        },
        RESOURCE_DESC_41012 = {
          ContentDE = "Spiele ein Lied, eine kleine Ode an den Mittsommer und das Stiefmütterchen.",
          TextMapId = "RESOURCE_DESC_41012"
        },
        RESOURCE_DESC_41013 = {
          ContentDE = "Woher wusstest du, dass ich heute einen richtig großen Fisch an Land gezogen habe?",
          TextMapId = "RESOURCE_DESC_41013"
        },
        RESOURCE_DESC_41014 = {
          ContentDE = "Nach einem Sprint wie der Wind: Genieß einen Moment der Stille.",
          TextMapId = "RESOURCE_DESC_41014"
        },
        RESOURCE_DESC_41015 = {
          ContentDE = "Spiele ein Lied, eine kleine Ode an den Mittsommer und das Stiefmütterchen.",
          TextMapId = "RESOURCE_DESC_41015"
        },
        RESOURCE_DESC_41016 = {
          ContentDE = "Spiele ein Lied, eine kleine Ode an den Mittsommer und das Stiefmütterchen.",
          TextMapId = "RESOURCE_DESC_41016"
        },
        RESOURCE_DESC_41017 = {
          ContentDE = "Nach einem Sprint wie der Wind: Genieß einen Moment der Stille.",
          TextMapId = "RESOURCE_DESC_41017"
        },
        RESOURCE_DESC_41018 = {
          ContentDE = "Nach einem Sprint wie der Wind: Genieß einen Moment der Stille.",
          TextMapId = "RESOURCE_DESC_41018"
        }
      }
    end
  },
  {
    MinKey = "RESOURCE_DESC_41019",
    MaxKey = "RESOURCE_NAME_10018",
    Loader = function()
      return {
        RESOURCE_DESC_41019 = {
          ContentDE = "Quak-quak, ein Lachen, das Sonnenlicht in Regenbögen bricht.",
          TextMapId = "RESOURCE_DESC_41019"
        },
        RESOURCE_DESC_41020 = {
          ContentDE = "Bewahre ein bisschen Sonnenschein und ein Stück Strand im Herzen, dann ist überall Sommer, wohin du auch gehst.",
          TextMapId = "RESOURCE_DESC_41020"
        },
        RESOURCE_DESC_41021 = {
          ContentDE = "Bewahre ein bisschen Sonnenschein und ein Stück Strand im Herzen, dann ist überall Sommer, wohin du auch gehst.",
          TextMapId = "RESOURCE_DESC_41021"
        },
        RESOURCE_DESC_41022 = {
          ContentDE = "Bewahre ein bisschen Sonnenschein und ein Stück Strand im Herzen, dann ist überall Sommer, wohin du auch gehst.",
          TextMapId = "RESOURCE_DESC_41022"
        },
        RESOURCE_DESC_41023 = {
          ContentDE = "Eine alltägliche Geste, um dich zu präsentieren.",
          TextMapId = "RESOURCE_DESC_41023"
        },
        RESOURCE_DESC_41024 = {
          ContentDE = "Eine alltägliche Geste, zum Grüßen.",
          TextMapId = "RESOURCE_DESC_41024"
        },
        RESOURCE_DESC_41025 = {
          ContentDE = "Eine alltägliche Geste, um Zustimmung zu zeigen.",
          TextMapId = "RESOURCE_DESC_41025"
        },
        RESOURCE_DESC_41026 = {
          ContentDE = "Eine alltägliche Geste, um abzulehnen.",
          TextMapId = "RESOURCE_DESC_41026"
        },
        RESOURCE_DESC_41027 = {
          ContentDE = "Eine alltägliche Geste, zum Jubeln.",
          TextMapId = "RESOURCE_DESC_41027"
        },
        RESOURCE_DESC_41028 = {
          ContentDE = "Fertigkeit ausführen: „Spezialpose“.",
          TextMapId = "RESOURCE_DESC_41028"
        },
        RESOURCE_DESC_41029 = {
          ContentDE = "Tada. Ta, tada! TA-DA!! DAAA! Auftritt!!!",
          TextMapId = "RESOURCE_DESC_41029"
        },
        RESOURCE_DESC_41030 = {
          ContentDE = "Tada. Ta, tada! TA-DA!! DAAA! Auftritt!!!",
          TextMapId = "RESOURCE_DESC_41030"
        },
        RESOURCE_DESC_41034 = {
          ContentDE = "Leg eine Pause ein und ruh dich im gefleckten Sonnenlicht aus.",
          TextMapId = "RESOURCE_DESC_41034"
        },
        RESOURCE_DESC_41035 = {
          ContentDE = "Leg eine Pause ein und ruh dich im gefleckten Sonnenlicht aus.",
          TextMapId = "RESOURCE_DESC_41035"
        },
        RESOURCE_DESC_41036 = {
          ContentDE = "Wann hat dieser herrliche Mond angefangen zu existieren? Mein Glas erhebend fragte ich den azurblauen Himmel.",
          TextMapId = "RESOURCE_DESC_41036"
        },
        RESOURCE_DESC_41037 = {
          ContentDE = "Tosende Gezeiten zerschmettern den geschwärzten Frost; wo die Winde sich vereinen, wird ein kaltes Glänzen heraufbeschworen.",
          TextMapId = "RESOURCE_DESC_41037"
        },
        RESOURCE_DESC_41038 = {
          ContentDE = "Aus dreifacher Geometrie verlieh die Göttin ihr Lob und vertraute die Schönheit selbst der Schleifung zur tödlichen Schneide an.",
          TextMapId = "RESOURCE_DESC_41038"
        },
        RESOURCE_DESC_41039 = {
          ContentDE = "Epulare Eleganz",
          TextMapId = "RESOURCE_DESC_41039"
        },
        RESOURCE_DESC_41040 = {
          ContentDE = "Bei Wein und Worten werden Schicksale gezogen und Geschicke entfaltet.",
          TextMapId = "RESOURCE_DESC_41040"
        },
        RESOURCE_DESC_41041 = {
          ContentDE = "Großes Epular",
          TextMapId = "RESOURCE_DESC_41041"
        },
        RESOURCE_DESC_41042 = {
          ContentDE = "Aus dem Nichts gehauen – ein Epular für alle Reiche.",
          TextMapId = "RESOURCE_DESC_41042"
        },
        RESOURCE_DESC_42002 = {
          ContentDE = "Ein quadratisches Mechanismus-Konstrukt von komplexer, filigraner Bauart, geschmiedet nach den verloren geglaubten Techniken der Jishu-Sekte. Sein Energiekern erzeugt einen gewaltigen Sog und kann die Gritblight vertreiben, die die Plage von Zhuyin hinterlässt.",
          TextMapId = "RESOURCE_DESC_42002"
        },
        RESOURCE_DESC_5000000 = {
          ContentDE = "Zum Verstärken von Dämonenkeilen mit hoher Seltenheit",
          TextMapId = "RESOURCE_DESC_5000000"
        },
        RESOURCE_DESC_5011010 = {
          ContentDE = "Diese Fischart ist in ganz Atlasia von großer wirtschaftlicher Bedeutung und ist in allen Meeren verbreitet. Sie zieht in großen Schwärmen durch das offene Meer und wandert mit dem Wandel der Jahreszeiten in die flachen Küstengewässer, Jahr für Jahr.",
          TextMapId = "RESOURCE_DESC_5011010"
        },
        RESOURCE_DESC_5011020 = {
          ContentDE = "Ein Fisch mit brillanten Farben, der in kristallklarem Wasser lebt und leicht an den auffälligen Stacheln entlang seines Rückens zu erkennen ist. Von Natur aus scheu – will man ihn angeln, ist Geduld wichtiger als Geschwindigkeit.",
          TextMapId = "RESOURCE_DESC_5011020"
        },
        RESOURCE_DESC_5011030 = {
          ContentDE = "Ein schlanker Meeresfisch, der in aufrechter Haltung schwimmt und dessen Schuppen in der Bewegung wie flüssiges Silber glänzen. Unglücklicherweise verdirbt er schnell, sobald man ihn aus dem Wasser holt, und aufgrund der hohen Transportkosten findet man ihn nur selten auf den Tischen im Landesinneren.",
          TextMapId = "RESOURCE_DESC_5011030"
        },
        RESOURCE_DESC_5012010 = {
          ContentDE = "Benannt nach den langen Barteln am Maul lebt diese Süßwasserart in schlammigem Untergrund, der dicht mit Wasserpflanzen überwuchert ist. Es taucht nur zum Fressen nach Sonnenuntergang auf und kann mehrere Jahrzehnte lang überleben – sofern er nicht an einem Angelhaken endet.",
          TextMapId = "RESOURCE_DESC_5012010"
        },
        RESOURCE_DESC_5012020 = {
          ContentDE = "Ein dicht mit perlartigen Flecken bedeckter Fisch, der bis zu zwei Meter lang werden kann. Die Jungtiere sind von Natur aus sanftmütig und schwimmen selten weit von ihren Eltern weg.",
          TextMapId = "RESOURCE_DESC_5012020"
        },
        RESOURCE_DESC_5012030 = {
          ContentDE = "Der Schalengnarl lebt in vielen Süßgewässern und ist eines der wenigen Tiere, die fast allen Gemeinschaften auf dem Kontinent schmecken. Die Zubereitungsmethoden variieren je nach Region. In manchen Gegenden werden sogar große Sommerfeste veranstaltet, bei denen dieses Fleischgericht im Mittelpunkt steht.",
          TextMapId = "RESOURCE_DESC_5012030"
        },
        RESOURCE_DESC_5013010 = {
          ContentDE = "Mit seinen scharfen Zähnen und seinem finsteren Grinsen sieht dieser Fisch weitaus gefährlicher aus, als er tatsächlich ist. Das größte jemals gemessene Exemplar war gerade einmal 5 Zentimeter groß. Er jagt immer alleine und sein Biss ist ungefährlich – er hinterlässt höchstens eine kleine, kreisförmige Narbe.",
          TextMapId = "RESOURCE_DESC_5013010"
        },
        RESOURCE_DESC_5013020 = {
          ContentDE = "Dieser Fisch verharrt die meiste Zeit seines Lebens nahezu bewegungslos auf der Seite liegend im Schlamm. Er wartet mit aufgerissenem Maul darauf, dass Plankton und kleine Fische hineintreiben. Nachdem er einmal zugebissen hat, kaut er stundenlang, ohne sich auch nur im Geringsten zu bewegen – eine Gewohnheit, die zu seinem Namen beigetragen hat.",
          TextMapId = "RESOURCE_DESC_5013020"
        },
        RESOURCE_DESC_5013030 = {
          ContentDE = "Eine sehr bizarre Kreatur, die einer Kreuzung zwischen einer Krabbe und einer Spinne ähnelt. Dieses Tier erklimmt Wände wie die Spinne und geistert durch die Tiefen wie die Krabbe. Es gibt zwar viele Möglichkeiten, eines dieser Exemplare zu fangen, das Angeln ist jedoch nach wie vor die sicherste Methode.",
          TextMapId = "RESOURCE_DESC_5013030"
        },
        RESOURCE_DESC_5021010 = {
          ContentDE = "Eine winzige Qualle, die ausschließlich in den Gewässern um die Purgatorio-Insel vorkommt und für ihre Biolumineszenz bekannt ist. Allerdings ungenießbar. In mondlosen Nächten beleuchtet sie die Wellen, schwebt wie ein treibender Stern durch das Wasser und weist den Fischern den Weg nach Hause.",
          TextMapId = "RESOURCE_DESC_5021010"
        },
        RESOURCE_DESC_5021020 = {
          ContentDE = "Einer der wichtigsten Fänge für die Dorfbewohner auf der Purgatorio-Insel. Vor allem geschätzt wegen des zarten, aromatischen Fleisches, das sich aus einem Leben in ständiger Bewegung ergibt, in dem das Tier unablässig den Gezeiten folgt.",
          TextMapId = "RESOURCE_DESC_5021020"
        },
        RESOURCE_DESC_5021030 = {
          ContentDE = "Diese auf der Purgatorio-Insel heimische Art kann über die Wasseroberfläche gleiten. An klaren Tagen sieht man sie manchmal wie Vögel in die Luft schießen man erkennt ihre leuchtenden Schwingen, die in der Sonne schimmern.",
          TextMapId = "RESOURCE_DESC_5021030"
        },
        RESOURCE_DESC_5021040 = {
          ContentDE = "Das beliebteste Wasserwesen auf der Purgatorio-Insel, das anderswo keine Entsprechung hat. Obwohl dieses Tier schlichtweg ungenießbar ist, bereitet es den Inselbewohnern, die weit entfernt von der übrigen Welt leben, große Freude und lockert die Monotonie ihres isolierten Alltags auf.",
          TextMapId = "RESOURCE_DESC_5021040"
        },
        RESOURCE_DESC_5021050 = {
          ContentDE = "Ein seltener und außerordentlich schöner Fisch, dessen Flossen wie die glitzernden Zweige eines Himmelsbaums schimmern. Auf der Purgatorio-Insel wird er als Geschenk der Götter verehrt – und nachdem man ihn aus dem Wasser geangelt hat, wird er oft in stiller Ehrfurcht wieder zurück ins Meer gesetzt.",
          TextMapId = "RESOURCE_DESC_5021050"
        },
        RESOURCE_DESC_5022010 = {
          ContentDE = "Eine Besonderheit der Huaxu-Gewässer, von den Einheimischen auch gerne als „Fledermaus des Meeres“ bezeichnet. Dieses Tier lebt in der Regel am Meeresboden und zeigt sich nur an der Oberfläche, um Nahrung aufzunehmen. Sein Rücken zeichnet sich durch perlmuttartige Erhebungen aus – eine Textur, die für die Umwicklung der Griffe edler Waffen sehr geschätzt wird.",
          TextMapId = "RESOURCE_DESC_5022010"
        },
        RESOURCE_DESC_5022020 = {
          ContentDE = "Eine Krabbe, die sich in verlassenen Teilen eines Uhrwerks ein Zuhause geschaffen hat. In biologischer Hinsicht unterscheidet sie sich allerdings nur unwesentlich von gewöhnlichen Einsiedlerkrebsen. Nach dem Niedergang der Jishu-Sekte blieben allüberall verstreute mechanische Relikte zurück, die nun von diesen Wesen über die Meere hinweg als Behausungen genutzt werden.",
          TextMapId = "RESOURCE_DESC_5022020"
        },
        RESOURCE_DESC_5022030 = {
          ContentDE = "Eine geheimnisvolle aquatische Lebensform, die bereits in uralten Texten erwähnt wird. Sie soll giftigen Sand auf die Schatten von Passanten spucken, woraufhin diese von seltsamen Krankheiten befallen werden.",
          TextMapId = "RESOURCE_DESC_5022030"
        },
        RESOURCE_DESC_5022040 = {
          ContentDE = "Diese extrem aggressive Art wird wegen ihres zarten, aromatischen Fleisches geschätzt und auf den Esstischen in Huaxu häufig serviert. Trotz des abscheulichen Erscheinungsbildes erscheint der biolumineszierenden Köder auf dem Kopf dieses Tieres seltsam anmutig.",
          TextMapId = "RESOURCE_DESC_5022040"
        },
        RESOURCE_DESC_5022050 = {
          ContentDE = "Dieser schnelle und aggressive Jäger, der nach der einstmals sehr beliebten Zwillingshaarknoten-Frisur von Huaxu benannt wurde, ist ein opportunistisches Raubtier, das mühelos Netze zerreißt – selbst für erfahrene Fischer eine echte Herausforderung.",
          TextMapId = "RESOURCE_DESC_5022050"
        },
        RESOURCE_DESC_5023010 = {
          ContentDE = "Ein Fisch, der Phoxene auffallend ähnlich sieht und eine verblüffende Textur aufweist, die sich fast nicht von der echter Phonexe unterscheiden lässt. Keine zwei Exemplare gleichen sich, jedoch weisen sie alle eine bedauerliche Gemeinsamkeit auf: Ihr Fleisch ist hart wie Stein. Dieses Tier wird nur in Zeiten größter Not verzehrt.",
          TextMapId = "RESOURCE_DESC_5023010"
        },
        RESOURCE_DESC_5023020 = {
          ContentDE = "Ein leuchtend bunter Fisch, der wie ein Seidenhauch durch das Wasser gleitet. Seine transparenten Flossen umspielen das Tier wie wallende Schleier, und jede Bewegung ist von müheloser Anmut geprägt – es wirkt so elegant wie die sagenumwobene Dame des Meeres, die in ruhiger Würde durch ihr flüssiges Reich gleitet.",
          TextMapId = "RESOURCE_DESC_5023020"
        },
        RESOURCE_DESC_5023030 = {
          ContentDE = "Einer der wichtigsten Speisefische in Icelake, den man leicht anhand seines einzigen Horns auf dem Kopf erkennen kann. Groß, zart und praktisch grätenfrei. Perfekt für Sashimi, zum Grillen, Braten oder Backen. Ein echt vielseitiger Fang für jedes Gericht.",
          TextMapId = "RESOURCE_DESC_5023030"
        },
        RESOURCE_DESC_5023040 = {
          ContentDE = "Ein seltener, kälteresistenter Fisch, der nur im Icelake vorkommt. Da er einen harten, gekerbten Panzer hat und über keine Rücken- oder Bauchflossen verfügt, lässt er sich leicht greifen, ähnlich wie die Holzknüppel, die früher zum Waschen von Wäsche verwendet wurden.",
          TextMapId = "RESOURCE_DESC_5023040"
        },
        RESOURCE_DESC_5023050 = {
          ContentDE = "Eine Art, die ausschließlich in den Gewässern von Icelake vorkommt. Auf seinem Rücken sind spitze, Eiskristall-ähnliche Stacheln, die im Dunkeln leicht leuchten. An klaren Tagen signalisiert ein Streifen blassen Lichts unter der Wasseroberfläche oft das lautlose Vorbeiziehen eines Schimmerrückens.",
          TextMapId = "RESOURCE_DESC_5023050"
        },
        RESOURCE_DESC_5024010 = {
          ContentDE = "Ein quirliger Fisch mit hübschen Schleierflossen, der wegen seines Aussehens geschätzt wird. Je voller die Flossen, desto leuchtender die Farben, desto höher der Preis. Da sie gegenüber Artgenossen ein sehr ausgeprägtes Territorialverhalten an den Tag legen, muss jedes Tier einzeln gehalten werden.",
          TextMapId = "RESOURCE_DESC_5024010"
        },
        RESOURCE_DESC_5024020 = {
          ContentDE = "Ein kleiner Tintenfisch, benannt nach Shouxing, dem Gott der Langlebigkeit aus der Huaxu-Mythologie. Er ist zwar winzig, kann sich aber mit seinen Tentakeln mit erstaunlicher Kraft durch die Luft katapultieren. In Huaxu gilt er als Symbol für ein langes Leben – wenn ein älterer Mensch Geburtstag feiert, dürfen Desserts, die nach seinem Ebenbild geformt sind, keinesfalls fehlen.",
          TextMapId = "RESOURCE_DESC_5024020"
        },
        RESOURCE_DESC_5024030 = {
          ContentDE = "Dieser mit feinen Stacheln bedeckte Fisch bläht sich bei Gefahr zu einer stacheligen Kugel auf, indem er seinen Leib mit Luft oder Wasser füllt. Er ist zwar extrem giftig und für seine schwierige Zubereitung bekannt, gilt in Huaxu aber dennoch als Delikatesse.",
          TextMapId = "RESOURCE_DESC_5024030"
        },
        RESOURCE_DESC_5024040 = {
          ContentDE = "Ein farbprächtiger Fisch aus Huaxu, bekannt für seinen beutelartigen Bauch und die Tatsache, dass er meist am Meeresgrund lebt. Trotz seiner geringen Größe ist er wegen seines zarten, grätenfreien Fleisches sehr beliebt – und in vielen lokalen Restaurants eine beliebte Speise.",
          TextMapId = "RESOURCE_DESC_5024040"
        },
        RESOURCE_DESC_5024050 = {
          ContentDE = "Ein seltener Huaxu-Fisch, der bis zu vier Meter lang werden kann. Er zeichnet sich durch eine spitze Maulpartie und vier Paar Bauchflossen aus und erinnert mit seinen symmetrischen Mustern und schimmernden Schuppen an den Silberdrachen. Obwohl der Wasserwyrm nicht durch die Neun Kapitel von Dafeng geschützt ist, wird er kaum gejagt. Da er eine große Ähnlichkeit mit dem Silberdrachen aufweist, wird er in ganz Huaxu verehrt – und kaum jemand würde es wagen, den Frevel zu begehen, ihn als Mahlzeit zu servieren.",
          TextMapId = "RESOURCE_DESC_5024050"
        },
        RESOURCE_DESC_5025010 = {
          ContentDE = "Ein Fisch mit Barteln und langem Schwanz, der sich gerne in Spalten und Winkeln versteckt und widerstandsfähig genug ist, um selbst in stehenden oder verschmutzten Gewässern zu überleben. Im Gegensatz zu echten Ratten knabbert er nicht an Kleidung und stiehlt auch kein Essen – deshalb wird er von den Kindern in den Slums oft als pflegeleichtes Haustier gehalten.",
          TextMapId = "RESOURCE_DESC_5025010"
        },
        RESOURCE_DESC_5025020 = {
          ContentDE = "Ein Geschöpf mit glatter Haut, schuppenlos, mit einem röhrenförmigen Maul, das mit Reihen scharfer Zähne gesäumt ist – ohne Ober- oder Unterkiefer. Dieses Tier vergräbt sich im Faulschlamm und beißt sich an allem fest, das ihm zu nahe kommt ... und wenn es das einmal getan hat, lässt es niemals wieder los. Unter Kanalarbeitern gilt es als das widerlichste Wesen, dem man dort unten begegnen kann.",
          TextMapId = "RESOURCE_DESC_5025020"
        },
        RESOURCE_DESC_5025030 = {
          ContentDE = "Ein vollständig transparenter Fisch mit feinen, zarten Gräten. Er ist mit bloßem Auge fast nicht zu erkennen und besitzt ein gallertartiges, absolut ungenießbares Fleisch – Forscher glauben jedoch, dass man es zu einem seltenen und ganz besonderen Gel verarbeiten kann.",
          TextMapId = "RESOURCE_DESC_5025030"
        },
        RESOURCE_DESC_5025040 = {
          ContentDE = "Ein bizarrer Fisch mit Gliedmaßen, der sich im Schlamm versteckt und gelegentlich markerschütternde Schreie ausstößt. Er besitzt eine unheimliche Ähnlichkeit mit einem Filthoid – ob das nur Zufall ist oder mehr dahintersteckt, bleibt jedoch ein Rätsel.",
          TextMapId = "RESOURCE_DESC_5025040"
        },
        RESOURCE_DESC_5025050 = {
          ContentDE = "Ein bräunlicher Fisch, der an den Seiten sechs zuckende Flossen aufweist. Seine ruckartigen Bewegungen ziehen Wellen durch das Wasser. Es ist ein verstörender Anblick – und noch dazu ist er erschreckend schnell. Zwei antennenartige Fortsätze ragen aus seinem Kopf und sind das erste Anzeichen dafür, dass er in der Nähe lauert. Gnadenlos und beharrlich verfolgt er seine Beute sogar bis aufs Festland.",
          TextMapId = "RESOURCE_DESC_5025050"
        },
        RESOURCE_DESC_5026010 = {
          ContentDE = "Eine Fischart, die in Huaxu beheimatet ist und wegen ihres ungewöhnlichen Aussehens Aufmerksamkeit erregt: Sie sieht aus wie eine runde Steinmühle und hat beide Augen auf einer Seite des Körpers. In frühen Aufzeichnungen wird berichtet, dass sich dieses Tier mit einem perfekten Spiegelzwilling verbinden muss, um schwimmen zu können – allerdings wird diese Geschichte von den einheimischen Fischern als Märchen abgestempelt.\n \n ",
          TextMapId = "RESOURCE_DESC_5026010"
        },
        RESOURCE_DESC_5026020 = {
          ContentDE = "Eine hübsche kleine Seekrabbe, die nach ihren Paddelbeinen benannt ist, die den Blütenblättern von Orchideen ähneln. Dieses Tier ist in den Gewässern von Huaxu weit verbreitet und schmeckt blanchiert einfach köstlich. Bekannt dafür, dass es schon an so manchem neugierigen Finger geknabbert hat – liebenswert und nervtötend zugleich, aber gerade deshalb umso unvergesslicher.",
          TextMapId = "RESOURCE_DESC_5026020"
        },
        RESOURCE_DESC_5026030 = {
          ContentDE = "Einfach ein ganz normaler Seestern.\n Als Dekoration hübsch anzusehen, aber bei Weitem nicht so schön wie eine Perle.\n Als Nahrungsmittel durchaus passabel, schmeckt aber nicht besonders lecker, weshalb sich nur wenige Leute dafür interessieren.\n Als Fang besser als nichts, aber man kann auch nicht gerade damit prahlen.\n Kurz gesagt, ein Seestern – mehr gibt es dazu eigentlich nicht zu sagen.",
          TextMapId = "RESOURCE_DESC_5026030"
        },
        RESOURCE_DESC_5026040 = {
          ContentDE = "Ein leuchtend scharlachrotes Tier aus dem Meer, das in seiner Form in etwa einer Garnele ähnelt, sich aber von echten Garnelen deutlich unterscheidet und etwa so lang wie ein Feuerwerkskörper ist. Von Natur aus aufbrausend entbrennt dieses Tier schon bei der kleinsten Provokation, daher stammt auch sein Name. Es wird in der Regel frittiert und dann mit einer Gewürzmischung aus Salz und Pfeffer unter Rühren gebraten, was ihm einen aromatischen, köstlichen Geschmack verleiht. Man verzehrt es am besten im ersten Monat des Mondjahres in Gesellschaft der Familie, während draußen Feuerwerkskörper knallen – was für ein Genuss!",
          TextMapId = "RESOURCE_DESC_5026040"
        },
        RESOURCE_DESC_5026050 = {
          ContentDE = "Ein wilder, blaugrüner Riesenfisch, der nach den alten Huaxu-Legenden über den Kun benannt ist – den legendären großen Fisch, der angeblich alles und jeden verschlingt. Unter den Fischern von Huaxu gilt es als eine der schlimmsten Verwünschungen, jemandem zu wünschen, dass ihm ein blitzschneller Azurwellen-Kun in den Oberschenkel beißen möge.",
          TextMapId = "RESOURCE_DESC_5026050"
        },
        RESOURCE_DESC_5027010 = {
          ContentDE = "Ein Flussfisch, der für sein delikates Aroma bekannt ist und einem kleinen Messer ähnelt. Der Legende nach versteckte ein Attentäter einst einen Dolch in einem Teller mit einfach Klingenflossen, und zog ihn erst hervor, als sein ahnungsloser Widersacher sich ganz dem Genuss der bevorstehenden Mahlzeit hingab. Die Geschichte belegt zumindest zwei Tatsachen: Klingenflossen sehen wirklich aus wie Klingen – und sie schmecken außergewöhnlich gut.",
          TextMapId = "RESOURCE_DESC_5027010"
        },
        RESOURCE_DESC_5027020 = {
          ContentDE = "Ein temperamentvoller Flussfisch, der Lebendfutter bevorzugt und so aggressiv ist, dass er sogar mit einem Haken ohne Köder gefangen werden kann. Wenn die Frühlingsluft vom Duft der Pfirsichblüten erfüllt ist, schmeckt er am saftigsten. Traditionell wird sein Fleisch eingeschnitten und gedämpft, dann mit leichter Sojasauce und heißem Öl serviert – so bewirtet man in Huaxu Ehrengäste auf besonders opulente Weise.",
          TextMapId = "RESOURCE_DESC_5027020"
        },
        RESOURCE_DESC_5027030 = {
          ContentDE = "Ein traditionsreicher Speisefisch, der aber nicht so leicht zu fangen ist. Die bekannteste Zubereitung ist ein herzhafter Fischeintopf. Mit der ersten herbstlichen Brise sehnen sich Sternenweber, die weit weg von ihrer Heimat weilen, unweigerlich nach ihrem Duft.",
          TextMapId = "RESOURCE_DESC_5027030"
        },
        RESOURCE_DESC_5027040 = {
          ContentDE = "Eine Zierfischart mit einer sattelförmigen Rückenflosse. Die Jungtiere haben eine hellgraue Färbung, während die erwachsenen Tiere ein buntes Farbspektrum entwickeln. Anspruchslos in Bezug auf die Wasserbedingungen und leicht zu halten.",
          TextMapId = "RESOURCE_DESC_5027040"
        },
        RESOURCE_DESC_5027050 = {
          ContentDE = "Der größte Süßwasserfisch in Huaxu, vollständig golden und äußerst selten. Galt lange Zeit als Symbol der Kaiser. Da es in Huaxu mittlerweile keine Kaiser mehr gibt, denkt man bei diesem Begriff heute eher an diesen riesigen Fisch als an irgendeinen Herrscher aus vergangenen Zeiten.",
          TextMapId = "RESOURCE_DESC_5027050"
        },
        RESOURCE_DESC_5028010 = {
          ContentDE = "Ein schlanker, bunter Fisch, der am Meeresgrund lebt und erfolgreich aus dem Hinterhalt angreift. Seine großen Augen erstrahlen nachts in einem sanften Licht, das unvorsichtige kleine Fische anlocken soll. Wenn ein Fischer in das dunkle Wasser hinabblickt, können sie wie blau leuchtende Augen aussehen, die aus dem Flussbett herauslugen.",
          TextMapId = "RESOURCE_DESC_5028010"
        },
        RESOURCE_DESC_5028020 = {
          ContentDE = "Ein kleiner Fisch, der oft paarweise anzutreffen ist, flink genug, um zu springen, und kurzzeitig über das Land zu kriechen. Er lebt in flachen Küstengewässern und an Flussufern und gräbt kleine Höhlen. Es bespritzt seinen Partner mit Wasser, um ihn feucht zu halten. Aufgrund dieses Verhaltens wurde er in alten Schriftstücken zum Symbol für gegenseitige Hingabe, und in den jüngsten Jahren wurde er aufgrund seines skurrilen Aussehens ziemlich beliebt.",
          TextMapId = "RESOURCE_DESC_5028020"
        },
        RESOURCE_DESC_5028030 = {
          ContentDE = "Ein Fisch, der an völlig lichtlosen Orten lebt. Sein Körper ist milchig, blass und halbtransparent mit einem perlmuttartigen Schimmer, und seine Augen haben sich vollständig zurückgebildet. So selten wie ein weißer Rabe.",
          TextMapId = "RESOURCE_DESC_5028030"
        },
        RESOURCE_DESC_5028040 = {
          ContentDE = "Diese Art lebt an dunklen, feuchten Orten, zeichnet sich durch extrem spröde Haut aus und hat einen Rückenschild, dessen Farbe sich im Laufe der Jahreszeiten verändert. Obwohl er von vielen als ausgesprochen hässlich angesehen wird, gilt er seit Langem als traditioneller Heilstoff.",
          TextMapId = "RESOURCE_DESC_5028040"
        },
        RESOURCE_DESC_5028050 = {
          ContentDE = "Ein Lebewesen aus dunklen und feuchten Gewässern mit großen Brustflossen, die mit Stacheln versehen sind. Seine leuchtende Farbgebung und seine Schwimmbewegungen lassen ihn wie eine Motte erscheinen. Seine Flossen sind hochgiftig und wurden in der Antike zu Waffen verarbeitet.",
          TextMapId = "RESOURCE_DESC_5028050"
        },
        RESOURCE_DESC_5110100 = {
          ContentDE = "Eine Angelrute, gefertigt von der Luno-Schmiedin, mit einem Oberflächenmonitor im Stil von Cinder, ihrem treuen kleinen Assistenten. Wenn ein Fisch anbeißt, leuchtet Cinder auf, um dies zu signalisieren – einige Kunden haben berichtet, dass sie das Leuchten so faszinierend fanden, dass sie am Ende mit einem leeren Eimer nach Hause gegangen sind.",
          TextMapId = "RESOURCE_DESC_5110100"
        },
        RESOURCE_DESC_5110200 = {
          ContentDE = "Eine Angelrute, gefertigt von der Luno-Schmiedin, mit einem Oberflächenmonitor im Stil von Cinder, ihrem treuen kleinen Assistenten. Wenn ein Fisch anbeißt, leuchtet Cinder auf, um dies zu signalisieren – einige Kunden haben berichtet, dass sie das Leuchten so faszinierend fanden, dass sie am Ende mit einem leeren Eimer nach Hause gegangen sind.",
          TextMapId = "RESOURCE_DESC_5110200"
        },
        RESOURCE_DESC_5110300 = {
          ContentDE = "Eine Angelrute, gefertigt von der Luno-Schmiedin, mit einem Oberflächenmonitor im Stil von Cinder, ihrem treuen kleinen Assistenten. Wenn ein Fisch anbeißt, leuchtet Cinder auf, um dies zu signalisieren – einige Kunden haben berichtet, dass sie das Leuchten so faszinierend fanden, dass sie am Ende mit einem leeren Eimer nach Hause gegangen sind.",
          TextMapId = "RESOURCE_DESC_5110300"
        },
        RESOURCE_DESC_5110400 = {
          ContentDE = "Eine Angelrute, gefertigt von der Luno-Schmiedin, mit einem Oberflächenmonitor im Stil von Cinder, ihrem treuen kleinen Assistenten. Wenn ein Fisch anbeißt, leuchtet Cinder auf, um dies zu signalisieren – einige Kunden haben berichtet, dass sie das Leuchten so faszinierend fanden, dass sie am Ende mit einem leeren Eimer nach Hause gegangen sind.",
          TextMapId = "RESOURCE_DESC_5110400"
        },
        RESOURCE_DESC_5110500 = {
          ContentDE = "Eine Angelrute, gefertigt von der Luno-Schmiedin, mit einem Oberflächenmonitor im Stil von Cinder, ihrem treuen kleinen Assistenten. Wenn ein Fisch anbeißt, leuchtet Cinder auf, um dies zu signalisieren – einige Kunden haben berichtet, dass sie das Leuchten so faszinierend fanden, dass sie am Ende mit einem leeren Eimer nach Hause gegangen sind.",
          TextMapId = "RESOURCE_DESC_5110500"
        },
        RESOURCE_DESC_5210100 = {
          ContentDE = "Ein handelsüblicher Köder, der die Aufmerksamkeit der Fische auf sich ziehen soll – ob man damit tatsächlich etwas fängt, ist eine ganz andere Frage.",
          TextMapId = "RESOURCE_DESC_5210100"
        },
        RESOURCE_DESC_5210200 = {
          ContentDE = "Ein spezieller Köder, mit dem die Fische schneller anbeißen. Das liegt vielleicht daran, wie lebensecht er sich windet, denn die meisten Wasserbewohner können ihm einfach nicht widerstehen.",
          TextMapId = "RESOURCE_DESC_5210200"
        },
        RESOURCE_DESC_5210300 = {
          ContentDE = "Ein speziell entwickelter Köder, der deine Chancen erhöht, Fische anzulocken – oder ihre Varianten. Für ein Wesen mit exzentrischem Geschmack könnte ein glänzendes Stück Schrott durchaus als Delikatesse gelten.",
          TextMapId = "RESOURCE_DESC_5210300"
        },
        RESOURCE_DESC_5210400 = {
          ContentDE = "Ein Köder, auf den ersten Blick ganz unscheinbar, aber aus hochwertigen Materialien hergestellt. Selbst die wählerischsten Fische fressen so lange weiter, bis selbst der letzte Krümel vertilgt wurde.",
          TextMapId = "RESOURCE_DESC_5210400"
        },
        RESOURCE_DESC_6000001 = {
          ContentDE = "Ein von der Handelsgilde EverSpring unter Zhilius Leitung ausgegebener Waren­gutschein.",
          TextMapId = "RESOURCE_DESC_6000001"
        },
        RESOURCE_DESC_99 = {
          ContentDE = "Ein Kristall, vom Himmelbaum geerntet, eines der vielseitigsten Minerale auf dem Kontinent Atlasia.\n Seinen Namen trägt er, weil er in einem sanften Glanz schimmert, wie das Licht des Vollmonds.",
          TextMapId = "RESOURCE_DESC_99"
        },
        RESOURCE_DESC_CANCELPHANTOM = {
          ContentDE = "Ein Siegel zum Widerrufen einer Beschwörung.\n Das Beisammensein mag kurz gewesen sein, doch die Sehnsucht reißt nicht ab. Vielleicht liegt das nächste Wiedersehen nur einen Wimpernschlag entfernt.",
          TextMapId = "RESOURCE_DESC_CANCELPHANTOM"
        },
        RESOURCE_DESC_GENERALSKIN_1 = {
          ContentDE = "Nach der Verwendung kann ein Outfit aus folgenden Figuren ausgewählt werden: Berenica, Phantasio, Lisbell, Frau Nifle, Fina, Rebecca, Tabethe, Lynn, Yale und Oliver, Hellfire, Margie, Rhythm, Randy, Sibylle, Truffle und Filbert, Outsider, Psyche oder Daphne.",
          TextMapId = "RESOURCE_DESC_GENERALSKIN_1"
        },
        RESOURCE_DESC_GENERALSKIN_2 = {
          ContentDE = "Nach der Verwendung kann ein Outfit aus folgenden Figuren ausgewählt werden: Berenica, Phantasio, Lisbell, Frau Nifle, Kezhou, Fina, Rebecca, Tabethe, Fushu, Lynn, Yale und Oliver, Hellfire, Margie, Rhythm, Randy, Sibylle, Truffle und Filbert, Outsider, Psyche oder Daphne.",
          TextMapId = "RESOURCE_DESC_GENERALSKIN_2"
        },
        RESOURCE_DESC_MUSIC = {
          ContentDE = "Ein Notenblatt – die Noten zeichnen eine Geschichte nach, wie Fußspuren im Sand.",
          TextMapId = "RESOURCE_DESC_MUSIC"
        },
        RESOURCE_DESC_OPTWEAPON_1 = {
