        RLBlessing_Desc_613 = {
          ContentDE = "Erhöht die Moral um <Highlight>$1</>, wenn [Glühkäfer] nicht in der Nähe ist,\n und um <Highlight>$2</>, wenn [Glühkäfer] in der Nähe ist.",
          TextMapId = "RLBlessing_Desc_613"
        },
        RLBlessing_Desc_614 = {
          ContentDE = "[Glühkäfer] verringern ihr Angriffsintervall deutlich für <Highlight>$2</> s, solange sich Gegner in der Nähe befinden. (kann einmal alle <Highlight>$1</> s ausgelöst werden).",
          TextMapId = "RLBlessing_Desc_614"
        },
        RLBlessing_Desc_615 = {
          ContentDE = "Erhöht verursachten SCH von [Glühkäfer] um <Highlight>$1</>.",
          TextMapId = "RLBlessing_Desc_615"
        },
        RLBlessing_Desc_701 = {
          ContentDE = "Erhöht die Fähigkeitsdauer um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_701"
        },
        RLBlessing_Desc_702 = {
          ContentDE = "Erhöht die automatische Wiederherstellung von Geist um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_702"
        },
        RLBlessing_Desc_703 = {
          ContentDE = "Erhöht die Auslöserate der Nahkampfwaffen um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_703"
        },
        RLBlessing_Desc_704 = {
          ContentDE = "Erhöht die max. LP um <Highlight>#1</>.",
          TextMapId = "RLBlessing_Desc_704"
        },
        RLBlessing_Desc_705 = {
          ContentDE = "Erhöht die VTD um <Highlight>#1</>. Beim Erleiden des SCH wird der verursachte SCH für <Highlight>$2</> s um <Highlight>$1</> erhöht. Kann einmal alle <Highlight>$3</> Sekunden ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_705"
        },
        RLBlessing_Desc_706 = {
          ContentDE = "Beim Verursachen des SCH verursachst du zusätzlichen Flächenschaden in Höhe von <Highlight>$1</> der max. LP am Standort des Ziels (kann einmal alle <Highlight>$2</> s ausgelöst werden).",
          TextMapId = "RLBlessing_Desc_706"
        },
        RLBlessing_Desc_707 = {
          ContentDE = "Erhöht den Fähigkeits-SCH um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen, und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_707"
        },
        RLBlessing_Desc_708 = {
          ContentDE = "Erhöht den verursachten SCH um <Highlight>$1</>. Der Effekt erhöht sich um <Highlight>1 %</> für jeweils <Highlight>1 %</> verlorene LP, bis zu <Highlight>$2)</>.",
          TextMapId = "RLBlessing_Desc_708"
        },
        RLBlessing_Desc_709 = {
          ContentDE = "Erhöht die KRIT-Rate der Nahkampfwaffen um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_709"
        },
        RLBlessing_Desc_710 = {
          ContentDE = "Erhöht den KRIT-SCH der Nahkampfwaffen um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_710"
        },
        RLBlessing_Desc_711 = {
          ContentDE = "Beim Erleiden des SCH erhältst du <Highlight>$1</> Punkte Ultra-Schild (kann einmal alle <Highlight>$2</> s ausgelöst werden).",
          TextMapId = "RLBlessing_Desc_711"
        },
        RLBlessing_Desc_712 = {
          ContentDE = "Der erlittene SCH pro Treffer übersteigt nicht <Highlight>#1</> der max. LP. Wenn du mehr SCH erlitten hast als <Highlight>$2</> der max LP, stellt <Highlight>$1</> der max LP pro Sekunde für <Highlight>$3</> s wieder her.",
          TextMapId = "RLBlessing_Desc_712"
        },
        RLBlessing_Desc_713 = {
          ContentDE = "Der Ultimate verbraucht alle VTD und wandelt <Highlight>$1</> davon für <Highlight>$2</> s in ANG der Figur um. Dieser Effekt kann nur einmal alle <Highlight>$3</> s bei demselben Ziel ausgelöst werden.",
          TextMapId = "RLBlessing_Desc_713"
        },
        RLBlessing_Desc_714 = {
          ContentDE = "Ignoriert beim Verursachen des Fähigkeits-SCH die VTD des Ziels um <Highlight>$2</>, wenn die LP unter <Highlight>100 %</> liegen, und um <Highlight>$1</>, wenn die LP <Highlight>100 %</> betragen.",
          TextMapId = "RLBlessing_Desc_714"
        },
        RLBlessing_Desc_715 = {
          ContentDE = "Erhöht die Entschlossenheit um <Highlight>$2</>, wenn die LP unter <Highlight>40 %</> liegen, und um <Highlight>$1</>, wenn die LP gleich oder höher als <Highlight>40 %</> sind.",
          TextMapId = "RLBlessing_Desc_715"
        },
