        },
        RLBlessing_SimpleDesc_104 = {
          ContentDE = "Stellt LP wieder her, wenn du Gegner im <Highlight>Nahkampfreichweite</> besiegst.",
          TextMapId = "RLBlessing_SimpleDesc_104"
        },
        RLBlessing_SimpleDesc_105 = {
          ContentDE = "Erlittener SCH durch Gegner <Highlight>in der Nähe</> oder durch Gegner mit [Schmelz-Feuerglut] wird reduziert.",
          TextMapId = "RLBlessing_SimpleDesc_105"
        },
        RLBlessing_SimpleDesc_106 = {
          ContentDE = "Wenn du Schaden erleiderst, wird [Schmelz-Feuerglut] auf Gegner <Highlight>in der Nähe</> angewendet.",
          TextMapId = "RLBlessing_SimpleDesc_106"
        },
        RLBlessing_SimpleDesc_107 = {
          ContentDE = "Erhöht die <Highlight>KRIT-Rate</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_107"
        },
        RLBlessing_SimpleDesc_108 = {
          ContentDE = "Erhöht den <Highlight>KRIT-SCH</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_108"
        },
        RLBlessing_SimpleDesc_109 = {
          ContentDE = "Erhöht den SCH der Nahkampfwaffen beim <Highlight>Sturzangriff, geladenen Angriff und Gleitangriff</>.",
          TextMapId = "RLBlessing_SimpleDesc_109"
        },
        RLBlessing_SimpleDesc_110 = {
          ContentDE = "Wendet regelmäßig [Schmelz-Feuerglut] auf <Highlight>Gegner in der Nähe</> an.",
          TextMapId = "RLBlessing_SimpleDesc_110"
        },
        RLBlessing_SimpleDesc_111 = {
          ContentDE = "Stellt LP wieder her, wenn du Gegnern mit [Schmelz-Feuerglut] SCH zufügst.",
          TextMapId = "RLBlessing_SimpleDesc_111"
        },
        RLBlessing_SimpleDesc_112 = {
          ContentDE = "Erhöht die <Highlight>Angriffs-GES </> und die <Highlight>Angriffsreichweite</> der Nahkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_112"
        },
        RLBlessing_SimpleDesc_113 = {
          ContentDE = "Verursacht <Highlight>zusätzlichen</> Schaden, wenn ein Schaden die LP des Ziels auf ein <Highlight>niedrigeres Niveau</> reduziert.",
          TextMapId = "RLBlessing_SimpleDesc_113"
        },
        RLBlessing_SimpleDesc_114 = {
          ContentDE = "Nahkampfwaffen fügen Gegnern mit [Schmelz-Feuerglut] <Highlight>Bonus-SCH</> zu.",
          TextMapId = "RLBlessing_SimpleDesc_114"
        },
        RLBlessing_SimpleDesc_115 = {
          ContentDE = "Je weniger Gegner sich <Highlight>in der Nähe</> befinden, desto höher ist der verursachte SCH.",
          TextMapId = "RLBlessing_SimpleDesc_115"
        },
        RLBlessing_SimpleDesc_201 = {
          ContentDE = "Erhöht den <Highlight>ANG</> der Fernkampfwaffe.",
          TextMapId = "RLBlessing_SimpleDesc_201"
        },
        RLBlessing_SimpleDesc_202 = {
          ContentDE = "Erhöht <Highlight>Auslöserate</> der Fernkampfwaffen.",
          TextMapId = "RLBlessing_SimpleDesc_202"
        },
        RLBlessing_SimpleDesc_203 = {
          ContentDE = "Wenn du mit einer Fernkampfwaffe SCH verursachst, spawnen [Munitionskisten].",
          TextMapId = "RLBlessing_SimpleDesc_203"
