        },
        RLTreasure_Desc_15101 = {
          ContentDE = "Wenn [Kampfhaltung] des Gegners über <Highlight>$1</> ist, stellt deine Figur beim Verursachen des SCH <Highlight>$2</> Punkte Geist wieder her. Abklingzeit: <Highlight>$3</>s.",
