        Raid_Buff_11 = {
          ContentDE = "Wenn der Fähigkeits-SCH einer Anemo-Figur über 100 % liegt, erhöht sich den Durchschlag gegen alle Elemente für je #1 über dem Schwellenwert um #2, bis zu maximal #3.",
          TextMapId = "Raid_Buff_11"
