        SCEREAD_TEXT_1000001 = {
          ContentDE = "Schwarzer Drache wütet, trübe Fluten breiten sich aus; Tag und Nacht geraten aus der Ordnung, die Temperaturen stürzen jäh.\n Gras und Bäume welken, jegliches Leben bricht ab; Felsgestein zerberstet, Himmel und Erde verfärben sich.\n Die einfachen Menschen von Schilf und Ufer bangen um ihre Heimat; die Sternenweber-Getreuen stellen sich gemeinsam der Not.\n Sie schmolzen Erz, schmiedeten Eisen, errichteten diesen Turm und entzündeten sein Rauchwerk; wohlriechender Wind erfüllte die Luft, trübes Miasma ward gelöst.\n Wacht stets über diesen Turm, lasst den Duft nicht erlöschen; pflegt ihn regelmäßig, so bleibt diese Gegend sicher.\n Sollte Zhuyin sich regen, kehrt das Unheil zurück; so lange auch das Glück währt, dem Turm wird am Ende die Kraft versiegen.\n Darum ist dies hier niedergeschrieben, als Mahnung für die Späteren: Wenn ihr abermals diese Heimsuchung trefft, so sucht nach neuen Wegen.\n Mit vereinten Herzen schirmt Flüsse und Auen; bewahrt Huaxu auf ewig, Frieden für alle Generationen.",
          TextMapId = "SCEREAD_TEXT_1000001"
        },
        SCEREAD_TEXT_1000002 = {
          ContentDE = "Mögen die Seelen der Verstorbenen rasch den Zweifel abstreifen und gemäß den Geboten ihres Pfades ins Reich der Freude eingehen.\n Diese Inschrift hält fest:\n Gui (Dorffrau; auf der Flucht von Zobel-Bi’an erschlagen.)\n Chuntao (Weberin; ihr Heim wurde überrannt, sie wurde darin erschlagen.)\n Li Erlang (Bauer; bei der Feldarbeit von Zobel-Bi’an erschlagen.)\n Xiao Xiaosan (Schreibjunge; auf der Flucht vom Lehrer getrennt, starb nach einem Irrgang in die Gritblight-Ebene)\n ...",
          TextMapId = "SCEREAD_TEXT_1000002"
        },
        SKILL_100001_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Verbündete.",
          TextMapId = "SKILL_100001_DESC"
        },
        SKILL_100001_NAME = {
          ContentDE = "Schlag",
          TextMapId = "SKILL_100001_NAME"
        },
        SKILL_100003_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Fähigkeits-SCH für sich selbst und Verbündete.",
          TextMapId = "SKILL_100003_DESC"
        },
        SKILL_100003_NAME = {
          ContentDE = "Neuheit",
          TextMapId = "SKILL_100003_NAME"
        },
        SKILL_100005_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Waffen-SCH für sich selbst und Verbündete.",
          TextMapId = "SKILL_100005_DESC"
        },
        SKILL_100005_NAME = {
          ContentDE = "Schneide",
          TextMapId = "SKILL_100005_NAME"
        },
        SKILL_100007_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die VTD für sich selbst und Verbündete.",
          TextMapId = "SKILL_100007_DESC"
        },
        SKILL_100007_NAME = {
          ContentDE = "Befestigung",
          TextMapId = "SKILL_100007_NAME"
        },
        SKILL_100009_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht die KRIT-Rate für sich selbst und Verbündete.",
          TextMapId = "SKILL_100009_DESC"
        },
        SKILL_100009_NAME = {
          ContentDE = "Leidenschaftlicher Impuls",
          TextMapId = "SKILL_100009_NAME"
        },
        SKILL_10101_DESC = {
          ContentDE = "Figur-ANG +<H>#1</>.",
          TextMapId = "SKILL_10101_DESC"
        },
        SKILL_10102_DESC = {
          ContentDE = "Auslöserate +<H>#1</>. Wenn ein Hydro-Figur mit dieser Waffe einen Bonuseffekt auslöst, erhalten alle anderen Verbündeten +<H>#2</> ANG für <H>#3</> Sek.",
          TextMapId = "SKILL_10102_DESC"
        },
        SKILL_10103_DESC = {
          ContentDE = "Angriffsreichweite +<H>#1</>. Wird mit dieser Waffe ein KRIT gelandet, besteht eine Chance von <H>#2</>, <H>#3</> Punkte Geist wiederherzustellen. Kann einmal alle <H>#4</> Sek. ausgelöst werden.",
          TextMapId = "SKILL_10103_DESC"
        },
        SKILL_10104_DESC = {
          ContentDE = "VTD +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst, mit einer Chance von <H>#3</>, den Schild des Ziels um <H>#2</> der VTD des Anwenders zu reduzieren.",
          TextMapId = "SKILL_10104_DESC"
        },
        SKILL_10105_DESC = {
          ContentDE = "Angriffs-GES +<H>#1</>. Wird mit dieser Waffe ein geladener Angriff ausgeführt, besteht eine Chance von <H>#2</>, die Abk. der Resonanz-Unterstützung um <H>#3</> Sek. zu verkürzen.",
          TextMapId = "SKILL_10105_DESC"
        },
        SKILL_10201_DESC = {
          ContentDE = "Fähigkeitsreichweite +<H>#1</>. Beim Treffen eines Gegners mit dieser Waffe im Standardangriff wird die Angriffs-GES um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>#4</>-mal stapelbar). Der Effekt wird beim Waffenwechsel deaktiviert.",
          TextMapId = "SKILL_10201_DESC"
        },
        SKILL_10202_DESC = {
          ContentDE = "Angriffs-GES +<H>#1</>. Verursacht +<H>#2</> SCH bei Zielen, die mit Bonuseffekten belegt sind.",
          TextMapId = "SKILL_10202_DESC"
        },
        SKILL_10203_DESC = {
          ContentDE = "Fähigkeits-SCH +<H>#1</>. Wenn ein Elektro-Figur mit dieser Waffe einen Sturzangriff ausführt, wird Fähigkeits-SCH um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>3</>-mal stapelbar).",
          TextMapId = "SKILL_10203_DESC"
        },
        SKILL_10204_DESC = {
          ContentDE = "Entschlossenheit +<H>#1</>. Nachdem eine Anemo-Figur ihren Ultimate eingesetzt hat, erhält sie den [Segen der Tausend Winde]: Erhöht die Entschlossenheit um <H>#2</> und die Angriffs-GES um <H>#3</> für <H>#4</> Sek. Jede Instanz von Fähigkeits-SCH oder Schaden durch Fernkampfwaffen verlängert die Dauer um <H>#5</> Sek.",
          TextMapId = "SKILL_10204_DESC"
        },
        SKILL_10206_DESC = {
          ContentDE = "Fähigkeits-SCH +<H>#1</>.",
          TextMapId = "SKILL_10206_DESC"
        },
        SKILL_10208_DESC = {
          ContentDE = "KRIT-Rate +<H>#1</>. Bei Schaden durch normale Angriffe mit dieser Waffe besteht eine Chance von <H>#2</>, das Magazin der Fernkampfwaffe nachzuladen.",
          TextMapId = "SKILL_10208_DESC"
        },
        SKILL_10301_DESC = {
          ContentDE = "Max. LP +<H>#1</>. Wenn ein Pyro-Figur SCH erleidet, wird die Fähigkeitsdauer um <H>#2</> für <H>#3</> Sek. verlönert (bis zu <H>#4</>-mal stapelbar).",
          TextMapId = "SKILL_10301_DESC"
        },
        SKILL_10302_DESC = {
          ContentDE = "KRIT-Rate +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst, mit eine Chance von <H>#2</>, die Kombostufe auf das Maximum zu erhöhen.",
          TextMapId = "SKILL_10302_DESC"
        },
        SKILL_10303_DESC = {
          ContentDE = "Fähigkeitsdauer +<H>#1</>.",
          TextMapId = "SKILL_10303_DESC"
        },
        SKILL_10304_DESC = {
          ContentDE = "Moral +<H>#1</>. Wenn ein Elektro-Figur den Ultimate einsetzt, wird der Fähigkeits-SCH um <H>#2</> für <H>#3</> Sek. erhöht (bis zu <H>#4</>-mal stapelbar).",
          TextMapId = "SKILL_10304_DESC"
        },
        SKILL_10401_DESC = {
          ContentDE = "Angriffs-GES +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst – wenn die LP des Trägers unter 25 % liegen, besteht eine Chance von <H>#2</>, <H>#3</> der max. LP wiederherzustellen.",
          TextMapId = "SKILL_10401_DESC"
        },
        SKILL_10402_DESC = {
