        SKILL_230102_DESC = {
          ContentDE = "Beschwört 9 [Tentakel] um Tabethe.",
          TextMapId = "SKILL_230102_DESC"
        },
        SKILL_230102_NAME = {
          ContentDE = "Gerechtigkeitskeilerei!",
          TextMapId = "SKILL_230102_NAME"
        },
        SKILL_230103_DESC = {
          ContentDE = "Beim Verursachen von KRIT-SCH mit einer Fernkampfwaffe besteht eine Chance, 1 [Tentakel] in der Nähe des Ziels zu beschwören, was nur einmal pro Sekunde ausgelöst werden kann. Es können maximal 18 [Tentakel] gleichzeitig existieren.",
          TextMapId = "SKILL_230103_DESC"
        },
        SKILL_230103_NAME = {
          ContentDE = "Die Farce beginnt!",
          TextMapId = "SKILL_230103_NAME"
        },
        SKILL_230104_DESC = {
          ContentDE = "Beim Beschwören von [Tentakeln] wird die KRIT-Rate von Tabethe erhöht, bis zu 10-mal stapelbar.",
          TextMapId = "SKILL_230104_DESC"
        },
        SKILL_230104_NAME = {
          ContentDE = "Tentakel überall!",
          TextMapId = "SKILL_230104_NAME"
        },
        SKILL_240101_DESC = {
          ContentDE = "Beschwört 1 [Yunchi]. Es können maximal 2 [Yunchi] gleichzeitig existieren.",
          TextMapId = "SKILL_240101_DESC"
        },
        SKILL_240101_NAME = {
          ContentDE = "Unterhimmelstrost",
          TextMapId = "SKILL_240101_NAME"
        },
        SKILL_240102_DESC = {
          ContentDE = "Verursacht Hydro-SCH an Gegnern in der Nähe. Gewährt einen Ultra-Schild und eine Erhöhung der Angriffs-GES. Verbündete in der Nähe erhalten einen Ultra-Schild und die [Neun-Nadel-Therapie].",
          TextMapId = "SKILL_240102_DESC"
        },
        SKILL_240102_NAME = {
          ContentDE = "Ganzheitliche Harmonie",
          TextMapId = "SKILL_240102_NAME"
        },
        SKILL_240103_DESC = {
          ContentDE = "Der Einsatz einer Fertigkeit oder eines Ultimates durch sich selbst oder Verbündete wird die Fähigkeits-GES erhöht, bis zu 2-mal stapelbar. Die Dauer wird beim Stapeln aktualisiert.",
          TextMapId = "SKILL_240103_DESC"
        },
        SKILL_240103_NAME = {
          ContentDE = "Archäus-Wiederbelebung",
          TextMapId = "SKILL_240103_NAME"
        },
        SKILL_240104_DESC = {
          ContentDE = "Erhöht den Fähigkeits-SCH basierend auf der Anzahl der [Yunchi] auf dem Kampffeld.",
          TextMapId = "SKILL_240104_DESC"
        },
        SKILL_240104_NAME = {
          ContentDE = "Blühende Vitalität",
          TextMapId = "SKILL_240104_NAME"
        },
        SKILL_240191_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den Fähigkeits-SCH für sich selbst und Verbündete, wenn 2 oder mehr Figuren im Team das gleiche Element teilen.",
          TextMapId = "SKILL_240191_DESC"
        },
        SKILL_240191_NAME = {
          ContentDE = "Meridian-Synergie",
          TextMapId = "SKILL_240191_NAME"
        },
        SKILL_310001_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Pyro-Verbündete.",
          TextMapId = "SKILL_310001_DESC"
        },
        SKILL_310001_NAME = {
          ContentDE = "Ätherflamme",
          TextMapId = "SKILL_310001_NAME"
        },
        SKILL_310003_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Pyro-Verbündete.",
          TextMapId = "SKILL_310003_DESC"
        },
        SKILL_310003_NAME = {
          ContentDE = "Höllenschmiede ",
          TextMapId = "SKILL_310003_NAME"
        },
        SKILL_310101_DESC = {
          ContentDE = "Verursacht Pyro-SCH an Gegnern vor sich und fügt [Risswunde] zu.",
          TextMapId = "SKILL_310101_DESC"
        },
        SKILL_310101_NAME = {
          ContentDE = "Tödliche Blüte",
          TextMapId = "SKILL_310101_NAME"
        },
        SKILL_310102_DESC = {
          ContentDE = "Wechselt die Fernkampfwaffe zu [Hansel und Gretel]. In diesem Zustand kann Lynn nur schießen und Fähigkeiten einsetzen, sich jedoch nur mithilfe von [Tödliche Blüte] bewegen.\n Schießen verursacht SCH an allen Gegnern voraus, und dabei wird Lynns Angriffs-GES alle 0,2 Sek. erhöht, bis zu 35-mal stapelbar.\n Beim Einsatz von [Hänsel und Gretel] wird kontinuierlich Geist verbraucht. Währenddessen ist Lynn beim Erleiden von SCH immun gegen Trefferstarre. Fällt der Geist unter 0 oder wird die Fähigkeit erneut eingesetzt, wird [Hänsel und Gretel] wieder in die Scheide zurückgeführt.",
          TextMapId = "SKILL_310102_DESC"
        },
        SKILL_310102_NAME = {
          ContentDE = "Pulverrausch",
          TextMapId = "SKILL_310102_NAME"
        },
        SKILL_310103_DESC = {
          ContentDE = "Wenn Lynn nicht schießt, erhält sie 1 Stapelung [Vorladen] pro Sekunde, bis zu 6 Stapelungen. Wenn sie schießt, verbraucht sie alle Stapelungen [Vorladen], um für eine bestimmte Zeit [Unterdrückungsfeuer] zu erhalten. [Unterdrückungsfeuer]: Erhöht den Schaden basierend auf der Anzahl der verbrauchten [Vorladen]-Stapelungen.\n [Vorladen]-Stapelung kann während [Unterdrückungsfeuer] nicht erhalten werden.",
          TextMapId = "SKILL_310103_DESC"
        },
        SKILL_310103_NAME = {
          ContentDE = "Taktisches Schnellfeuer",
          TextMapId = "SKILL_310103_NAME"
        },
        SKILL_310104_DESC = {
          ContentDE = "Entfernt sofort [Risswunde] und verursacht Schaden, sobald die [Aufgerissene Wunde]-Anzahl das Maximum erreicht.",
          TextMapId = "SKILL_310104_DESC"
        },
        SKILL_310104_NAME = {
          ContentDE = "Unverzeihlichkeit",
          TextMapId = "SKILL_310104_NAME"
        },
        SKILL_310201_DESC = {
          ContentDE = "Befiehlt allen [Schmutzvertilgern], sich kontinuierlich um Hilda zu drehen und [Hyperthermische Reinigungsstrahlen] abzufeuern. Währenddessen wird die Dauer aller [Leichten Schmutzvertilger] angehalten. [Hyperthermische Reinigungsstrahlen] fügen getroffenen Gegnern Pyro-SCH zu. Während der Dauer von [Hyperthermischer Reinigungsstrahl] besteht beim Besiegen eines Gegners die Chance, Hilda Geist wiederherzustellen.",
          TextMapId = "SKILL_310201_DESC"
        },
        SKILL_310201_NAME = {
          ContentDE = "Pyrolytische Reinigung",
          TextMapId = "SKILL_310201_NAME"
        },
        SKILL_310202_DESC = {
          ContentDE = "Verursacht Pyro-SCH an Gegnern in der Umgebung und belegt sie mit [Entwaffnung]. Für jedes getroffene Ziel wird 1 [Leichter Schmutzvertilger] in der Nähe von Hilda beschworen und die Dauer aller [Leichten Schmutzvertilger] wird aktualisiert.\n Trägt 2 [Schwere Schmutzvertilger] herum. [Schwere Schmutzvertilger] und [Leichte Schmutzvertilger] zielen automatisch auf Gegner in der Nähe und schießen alle 3 Sek. auf sie, wobei sie Pyro-SCH verursachen.\n Es können maximal 6 [Leichte Schmutzvertilger] gleichzeitig existieren.",
          TextMapId = "SKILL_310202_DESC"
        },
        SKILL_310202_NAME = {
          ContentDE = "Hingebungsvoller Service",
          TextMapId = "SKILL_310202_NAME"
        },
        SKILL_310203_DESC = {
          ContentDE = "Beim Ausweichen wird Hildas Fernkampfwaffen-Magazin vollständig nachgeladen, und sie erhält für kurze Zeit [Elegante Wut].",
          TextMapId = "SKILL_310203_DESC"
        },
        SKILL_310203_NAME = {
          ContentDE = "Automatische Reinigung",
          TextMapId = "SKILL_310203_NAME"
        },
        SKILL_310204_DESC = {
          ContentDE = "[Schmutzvertilger] hat eine Chance, beim Angriff 1 zusätzliches Geschoss abzufeuern, mit einer Wahrscheinlichkeit in Höhe von [30 % + 20 % × Hildas Mehrfachschussrate der Fernkampfwaffen]. Erhöht den SCH von [Hyperthermischer Reinigungsstrahl] um [30 % + 20 % × Hildas Mehrfachschussrate der Fernkampfwaffen].",
          TextMapId = "SKILL_310204_DESC"
        },
        SKILL_310204_NAME = {
          ContentDE = "Multitasking",
          TextMapId = "SKILL_310204_NAME"
        },
        SKILL_310301_DESC = {
          ContentDE = "Wirft eine Bombe namens [Kleiner Knaller], die entweder die Form von [Kleiner Knaller: Yales Werk] oder [Kleiner Knaller: Olivers Werk] annimmt. Nach der Landung detoniert die Bombe nach 2 Sek. und verursacht Pyro-SCH in einem kreuzförmigen Bereich, wodurch alle weiteren [Kleinen Knaller] im Umkreis ausgelöst werden. Es können maximal 10 [Kleine Knaller] gleichzeitig existieren.",
          TextMapId = "SKILL_310301_DESC"
        },
        SKILL_310301_NAME = {
          ContentDE = "Kleiner Knaller",
          TextMapId = "SKILL_310301_NAME"
        },
        SKILL_310302_DESC = {
          ContentDE = "Generiert [Alptraumlabor] um Yale und Oliver herum. Der erneute Einsatz dieser Fähigkeit kann das [Alptraumlabor] vorzeitig schließen.",
          TextMapId = "SKILL_310302_DESC"
        },
        SKILL_310302_NAME = {
          ContentDE = "Alptraumerinnerung",
          TextMapId = "SKILL_310302_NAME"
        },
        SKILL_310303_DESC = {
          ContentDE = "Wenn ein [Kleiner Knaller] eingesetzt wird und sich beim Abwurf mindestens 2 m über dem Boden befindet, verursacht er bei der Landung Pyro-SCH an nahe stehenden Gegnern.",
          TextMapId = "SKILL_310303_DESC"
        },
        SKILL_310303_NAME = {
          ContentDE = "Bomben-Spielregeln",
          TextMapId = "SKILL_310303_NAME"
        },
        SKILL_310304_DESC = {
          ContentDE = "Bei jedem Einsatz eines [Kleinen Knallers] erhalten Yale und Oliver 1 Stapelung [Bombenfieber], bis zu 3 Stapelungen.",
          TextMapId = "SKILL_310304_DESC"
        },
        SKILL_310304_NAME = {
          ContentDE = "Bomben-Erinnerungen",
          TextMapId = "SKILL_310304_NAME"
        },
        SKILL_320101_DESC = {
          ContentDE = "Tritt in den Zustand [Vergeltung] ein.",
          TextMapId = "SKILL_320101_DESC"
        },
        SKILL_320101_NAME = {
          ContentDE = "Glühendes Inferno",
          TextMapId = "SKILL_320101_NAME"
        },
        SKILL_320102_DESC = {
          ContentDE = "Verursacht Pyro-SCH an Gegnern in der Umgebung und verspottet sie.",
          TextMapId = "SKILL_320102_DESC"
        },
        SKILL_320102_NAME = {
          ContentDE = "Käfig der Verzweiflung",
          TextMapId = "SKILL_320102_NAME"
        },
        SKILL_320103_DESC = {
          ContentDE = "Erhöht die max. LP und stellt dauerhaft LP wieder her.",
