        },
        TARGET_DUNGEON_EXCAVATION_104 = {
          ContentDE = "Aktiviere die Exkavatoren. <Highlight>Drei</> Exkavatoren können in jeder Runde aktiviert werden. Exkavatoren mit verschiedenen Stufen haben eine unterschiedliche Erkundungseffizienz.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_104"
        },
        TARGET_DUNGEON_EXCAVATION_105 = {
          ContentDE = "Exkavatoren erfordern <Highlight>Exkavator-Module</> zum Funktionieren, die du durch das <Highlight>Besiegen</> bestimmter Monster erhalten kannst.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_105"
        },
        TARGET_DUNGEON_EXCAVATION_106 = {
          ContentDE = "Nachdem du ein Exkavator-Modul gesammelt hast, nähere dich einem Exkavator zur automatischen Installation.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_106"
        },
        TARGET_DUNGEON_EXCAVATION_107 = {
          ContentDE = "Achte auf den <Highlight>Erkundungsfortschritt</> und die verbleibende Anzahl der Exkavator-Module. Schütze die Exkavatoren, um ihren ununterbrochenen Betrieb sicherzustellen.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_107"
        },
        TARGET_DUNGEON_EXCAVATION_108 = {
          ContentDE = "Exkavatoren geben <Highlight>Münzen</> während der Erkundung ab. Die Mission ist abgeschlossen, nachdem drei Exkavatoren aktiviert wurden und mindestens einer von ihnen den vollen Erkundungsfortschritt erreicht.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_108"
        },
        TARGET_DUNGEON_EXCAVATION_109 = {
          ContentDE = "Wenn du eine Erkundungsmission abschließt, kannst du wählen, ob du dich zurückziehen oder neue Exkavatoren aktivieren willst, um mehr Münzen zu erhalten.",
          TextMapId = "TARGET_DUNGEON_EXCAVATION_109"
