        TERMEXP_1103_Combo = {
          ContentDE = "Gewährt eine gewisse Menge [Immersion]. Dieser Effekt kann nur einmal alle 0,1 Sek. ausgelöst werden.",
          TextMapId = "TERMEXP_1103_Combo"
        },
        TERMEXP_1103_Finish = {
          ContentDE = "Erhöht Phantasios SCH basierend auf den Stapelungen von [Adagio] des Ziels und entfernt anschließend alle [Adagio]-Stapelungen. Wenn das Ziel mit 10 Stapelungen [Adagio] belegt ist, werden Phantasios Geist wiederhergestellt und eine gewisse Menge [Immersion] gewährt. Dieser Effekt kann nur einmal pro Angriff ausgelöst werden.",
          TextMapId = "TERMEXP_1103_Finish"
        },
        TERMEXP_1103_HyperForm = {
          ContentDE = "Im Zustand [Bestialische Wut: Hingabe] wird ständig [Immersion] statt Geist verbraucht, um den Zustand aufrechtzuerhalten. Erhöht die Fähigkeits-GES und den ANG basierend auf dem max. Geist.\n Im Zustand [Bestialische Wut: Hingabe] wird während der Aufrechterhaltung von [Bestiengestalt] keine Immersion pro Sekunde erzeugt.",
          TextMapId = "TERMEXP_1103_HyperForm"
        },
        TERMEXP_1103_Skill01 = {
          ContentDE = "Stürmt vorwärts, verursacht Umbro-SCH an Gegnern auf dem Weg und erhält [Presto]. [Presto]: Vergrößert die Fähigkeitsreichweite und gewährt Immunität gegen Trefferstarre.",
          TextMapId = "TERMEXP_1103_Skill01"
        },
        TERMEXP_1501_Buff01 = {
          ContentDE = "Immun gegen Trefferstarre und reduziert den erlittenen SCH.",
          TextMapId = "TERMEXP_1501_Buff01"
        },
        TERMEXP_1502_Skill01 = {
          ContentDE = "Erschafft 1 [Sonnenfinsternis] und ersetzt diese Fähigkeit durch [Mondjagd].\n [Sonnenfinsternis]: Verursacht beim Erstellen Lumino-SCH bei allen Gegnern innerhalb der Reichweite und reduziert ihren ANG.",
          TextMapId = "TERMEXP_1502_Skill01"
        },
        TERMEXP_1503_Skill02 = {
          ContentDE = "Beendet den Zustand [Aspektmanifestation] und verursacht Lumino-SCH an Gegnern vor sich.",
          TextMapId = "TERMEXP_1503_Skill02"
        },
        TERMEXP_1503_Skill02_01 = {
          ContentDE = "Erbt alle Attributen von Kezhous Nahkampfwaffe und erhält eine größere Angriffsreichweite. [Phanoschwert] verfügt über Standardangriff-Modi für Schwert, Großschwert, Stangenwaffe und Doppelklingen. Nach dem Ausführen des finalen Angriffs von [Phanoschwert] wird zu einem zufälligen Angriffsmodus gewechselt und alle [Phanofedern] werden entfesselt.",
          TextMapId = "TERMEXP_1503_Skill02_01"
        },
        TERMEXP_1503_Skill02_02 = {
          ContentDE = "Kezhou kann maximal 7 [Phanofedern] gleichzeitig haben. Beim Entfesseln wählt jede [Phanofeder] einen zufälligen Gegner, umkreist ihn und fliegt auf ihn zu, um ihm anzugreifen – dabei verursacht sie Lumino-SCH an Gegnern auf ihrer Flugbahn. Nachdem die [Phanofeder] den Gegner 3-mal angegriffen hat, löst sie sich auf. Von der [Phanofeder] getroffene Ziele erleiden zusätzlichen SCH in Höhe eines bestimmten Prozentsatzes des anhaltenden Lumino-Bonuseffekts-SCH, basierend auf der Auslöserchance der eigenen Nahkampfwaffe.",
          TextMapId = "TERMEXP_1503_Skill02_02"
        },
        TERMEXP_1504_ExtraPassive_01 = {
          ContentDE = "Wird bei Nah- oder Fernkampfangriffen automatisch aktiviert. Wenn Su Yi SCH erleidet, absorbiert der Schild diese Schadensinstanz. Der Schild zerbricht, nachdem er SCH in Höhe eines bestimmten Prozentsatzes von Su Yis max. LP absorbiert hat.",
          TextMapId = "TERMEXP_1504_ExtraPassive_01"
        },
        TERMEXP_1504_Passive_01 = {
          ContentDE = "Jeder verbrauchte Überhitzung-Stapelung stellt Geist wieder her und erhöht den SCH der anschließenden Arsenal-Explosion.",
          TextMapId = "TERMEXP_1504_Passive_01"
        },
        TERMEXP_1504_Skill02_01 = {
          ContentDE = "Stellt dem [Kunstwerker-Arsenal] zusätzliche Munition bereit und erhöht die Angriffs-GES. Wird beim Zurückziehen des Arsenals entfernt.",
          TextMapId = "TERMEXP_1504_Skill02_01"
        },
        TERMEXP_1504_Skill02_02 = {
          ContentDE = "Standardangriffe mit dem [Kunstwerker-Großschwert] verbrauchen 5 Patronen des [Kunstwerker-Arsenals] und verursachen entlang des Wegs Lumino-SCH.",
          TextMapId = "TERMEXP_1504_Skill02_02"
        },
        TERMEXP_1504_Skill02_03 = {
          ContentDE = "Feuert mit dem [Kunstwerker-Geschütz] eine Kunstwerker-Granate nach vorn, die beim Aufprall explodiert und Lumino-Flächenschaden verursacht.\n Ist der Dämonenkeil [Kunstwerker-Umkonfiguration] ausgerüstet, wird stattdessen eine Zündgranate abgefeuert, die sich auf zufällige Gegner zubewegt und entlang ihres Wegs alle 0,5 Sek. Lumino-Flächenschaden verursacht.",
          TextMapId = "TERMEXP_1504_Skill02_03"
        },
        TERMEXP_1601_Skill02 = {
          ContentDE = "Erhöht den Waffen-SCH.",
          TextMapId = "TERMEXP_1601_Skill02"
        },
        TERMEXP_1801_Passive = {
          ContentDE = "Verursacht zusätzlichen Lumino-SCH.",
          TextMapId = "TERMEXP_1801_Passive"
        },
        TERMEXP_1801_Skill02 = {
          ContentDE = "Erzeugt ein Elementarfeld basierend auf dem Typ der [Teeparty-Gäste] — [Nachtigall] für Hydro, [Hund] für Pyro, [Einhorn] für Elektro und [Schmetterling] für Anemo.\n Wenn das Feld auftaucht oder sich sein Element verschiebt, erhalten Fina und Verbündete einen zusätzlichen Elementarschaden, der dem Typ des Felds entspricht. Während [Ausgelassene Teeparty] aktiv ist, verursacht das Feld außerdem alle 2 Sek. Elementarschaden an Gegnern innerhalb der Reichweite.",
          TextMapId = "TERMEXP_1801_Skill02"
        },
        TERMEXP_2101_Dot = {
          ContentDE = "Verursacht Hydro-SCH einmal alle 2 Sek. Wenn ein Gegner, der mit [Gift der Liebe] belegt ist, besiegt wird, überträgt er sein eigenes [Gift der Liebe] entsprechend der aktuellen Stapelzahl und der verbleibenden Dauer auf nahe Gegner.",
          TextMapId = "TERMEXP_2101_Dot"
        },
        TERMEXP_2101_Summon = {
          ContentDE = "Erbt 100 % von Rebeccas Attributen und fügt nahe Gegnern fortlaufend Hydro-SCH zu.",
          TextMapId = "TERMEXP_2101_Summon"
        },
        TERMEXP_2301_Summon = {
          ContentDE = "Erbt 100 % von Tabethes Attributen, verursacht kontinuierlich Hydro-SCH an Gegnern in der Nähe und erfasst bis zu 2 Gegner, um sie bewegungsunfähig zu machen.",
          TextMapId = "TERMEXP_2301_Summon"
        },
        TERMEXP_2401_Skill02Buff = {
          ContentDE = "Erhöht den Fähigkeits-SCH um einen Prozentsatz von [Fushu]s Fähigkeits-SCH.",
          TextMapId = "TERMEXP_2401_Skill02Buff"
        },
        TERMEXP_2401_Summon = {
          ContentDE = "Erbt 100 % von Fushus Attributen und verursacht pro Sekunde Hydro-SCH an den fünf nächststehenden Gegnern.\n [Yunchi] stellt einmal alle 3 Sek. LP und Geist für Teammitglieder in der Nähe wieder her.",
          TextMapId = "TERMEXP_2401_Summon"
        },
        TERMEXP_3101_Debuff = {
          ContentDE = "Wenn der Gegner unter dem Einfluss von [Risswunde] einen Fernkampf-SCH durch [Lynn] erleidet, wird die [Aufgerissene Wunde]-Anzahl um 1 erhöht. Wenn die Dauer von [Risswunde] endet, wird beim Gegner einmal Pyro-SCH in Höhe der [Aufgerissene Wunde]-Anzahl × [Risswunde]-SCH verursacht.",
          TextMapId = "TERMEXP_3101_Debuff"
        },
        TERMEXP_3102_Buff = {
          ContentDE = "Erhöht die Angriffs-GES von [Schmutzvertilger], die Rotations-GES von [Pyrolytische Reinigung] und die Angriffs-GES von Fernkampfwaffen.",
          TextMapId = "TERMEXP_3102_Buff"
        },
        TERMEXP_3102_Debuff = {
          ContentDE = "Deaktiviert dauerhaft Fernkampfwaffen.",
          TextMapId = "TERMEXP_3102_Debuff"
        },
        TERMEXP_3103_Skill02 = {
          ContentDE = "Im Bereich des [Alptraumlabors]:\n Die Bewegungs-GES von Gegnern im Bereich wird reduziert. Die Detonationstimer von [Kleinen Knallern] auf dem Boden werden pausiert und sie detonieren nicht durch andere [Kleine Knaller].\n Wenn das [Alptraumlabor] schließt:\n Detonieren alle [Kleinen Knaller] im Bereich, und das Labor löst eine Explosion aus, die Pyro-SCH an den Gegnern verursacht. Für jeden detonierten [Kleinen Knaller] steigt der Explosions-SCH des [Alptraumlabors] und es wird Geist für Yale und Oliver wiederhergestellt.",
          TextMapId = "TERMEXP_3103_Skill02"
        },
        TERMEXP_3103_Summon01 = {
          ContentDE = "Wird Schaden verursacht, erleidet das Ziel eine stärkere Reduzierung der Kampfhaltung. Je größer der Unterschied zwischen der Fähigkeitsreichweite und dem Fähigkeits-SCH von Yale und Oliver ist, desto höher ist die Chance, [Kleiner Knaller: Yales Werk] einzusetzen. Wenn der Unterschied nicht geringer als 50 % ist, ist es garantiert ein [Kleiner Knaller: Yales Werk].",
          TextMapId = "TERMEXP_3103_Summon01"
        },
        TERMEXP_3103_Summon02 = {
          ContentDE = "Verursacht höheren SCH. Je größer der Unterschied zwischen dem Fähigkeits-SCH und der Fähigkeitsreichweite von Yale und Oliver ist, die durch ausgerüstete Dämonenkeile bereitgestellt werden, desto höher ist die Chance, [Kleiner Knaller: Olivers Werk] einzusetzen. Wenn der Unterschied nicht geringer als 50 % ist, ist es garantiert ein [Kleiner Knaller: Olivers Werk].",
          TextMapId = "TERMEXP_3103_Summon02"
        },
        TERMEXP_3201_Skill01 = {
          ContentDE = "Verursacht alle 2 Sek. Pyro-SCH an Gegnern in der Nähe. Wenn Hellfire während [Vergeltung] SCH erleidet, verlängert sich die Dauer des Zustands, und [Durchdringende Vergeltung] verursacht alle 2 Sekunden Pyro-SCH an Gegnern in der Nähe.",
          TextMapId = "TERMEXP_3201_Skill01"
        },
        TERMEXP_3202_Passive01 = {
          ContentDE = "Jeder Waffen- und Fähigkeits-SCH, außer [Drehklingen] und [Risswunde], detoniert 2 Stapelungen [Risswunde], was zusätzlichen Elementar-SCH verursacht. Max. 20 Detonationen pro Sekunde.",
          TextMapId = "TERMEXP_3202_Passive01"
        },
        TERMEXP_3202_Skill01 = {
          ContentDE = "Erhöt Fähigkeits-GES. [Drehklingen] erhöhen ihre Geschwindigkeit und ihre Dauer wird pausiert. Erhält Immunität gegen Trefferstarre. Alle [Rausch]-Stapelungen werden entfernt, wenn [Burgunder-Gestöber] endet.",
          TextMapId = "TERMEXP_3202_Skill01"
        },
        TERMEXP_3202_Skill02 = {
          ContentDE = "Jede [Drehklinge] rotiert alle 2 Sekunden einmal um die Figur. Nach dem Abheben fliegt sie 30 m weit, bevor sie zurückkehrt. Wird sie auf dem Rückweg von Angriffen von [Burgunder-Gestöber] getroffen, wird sie auf einen zufälligen Gegner innerhalb von 20 m erneut abgefeuert. Bei jedem Abfeuern wird ihre Geschwindigkeit basierend auf den [Rausch]-Stapelungen aktualisiert. Es können maximal 8 [Drehklingen] gleichzeitig existieren.",
          TextMapId = "TERMEXP_3202_Skill02"
        },
        TERMEXP_4101_Skill02_01 = {
          ContentDE = "Erhöht die Bewegungs-GES für sich selbst und Verbündete. Verursacht jede Sekunde Elektro-SCH an 1 zufälligem Gegner in Reichweite und wechselt dabei zwischen [Positive Ladung] und [Negative Ladung]. Gegner ohne [Elektrische Ladung] werden priorisiert.",
          TextMapId = "TERMEXP_4101_Skill02_01"
        },
        TERMEXP_4101_Skill02_02 = {
          ContentDE = "Das Ziel mit [Positive Ladung] wählt alle 3 Sek. 1 zufälliges Ziel mit [Negative Ladung] in Reichweite aus, dann werden beide zum Mittelpunkt zwischen ihren Positionen gezogen und erleiden Elektro-SCH. Wenn keine Ziele mit [Negative Ladung] in der Umgebung sind, wird 1 zufälliges Ziel ausgewählt, um zusammen Elektro-SCH zu erleiden.\n Wenn ein mit [Elektrische Ladung] belegtes Ziel erneut mit derselben Ladung belegt wird, wird die Dauer der bestehenden [Elektrischen Ladung] aktualisiert. Es kann nicht mit der entgegengesetzten [Elektrischen Ladung] belegt werden.",
          TextMapId = "TERMEXP_4101_Skill02_02"
        },
        TERMEXP_4102_Skill02_01 = {
          ContentDE = [[
Wenn Zhiliu 2 [Talismane: Zhen] hat, wird [Himmel-Erde-Divination] mit [Donnerndes Orakel] ersetzt.
 [Donnerndes Orakel]: Verbraucht alle [Talismane], verursacht Elektro-SCH an Gegnern in einer geraden Linie vor sich.]],
          TextMapId = "TERMEXP_4102_Skill02_01"
        },
        TERMEXP_4102_Skill02_02 = {
          ContentDE = "Wird [Himmel-und-Erde-Evolution] durch diese Fähigkeit ersetzt, wenn Zhiliu 1 [Talisman: Zhen] und 1 [Talisman: Xun] besitzt.\n [Donnerndes Orakel]: Verbraucht alle [Talismane], Verursacht DoT an Gegnern in einem Bereich nach vorne und erschafft anschließend ein Feld [Vier-Reiche-Harmonisierung] an ihrem Standort. Zielt alle 3 Sek. auf bis zu 5 Gegner innerhalb des Feldes und erschafft eine [Zhen-Xun-Konvergenz] an ihrem Standort, wodurch Elektro-Flächenschaden verursacht wird.",
          TextMapId = "TERMEXP_4102_Skill02_02"
        },
        TERMEXP_4102_Skill02_03 = {
          ContentDE = "Wenn Zhiliu 2 [Talismane: Xun] hat, wird [Himmel-Erde-Divination] durch [Klarheit des Schicksals] ersetzt.\n [Klarheit des Schicksals]: Verbraucht alle [Talismane], um Elektro-SCH an Gegnern im Umkreis zu verursachen und Zhilius Fähigkeits-SCH zu erhöhen.",
          TextMapId = "TERMEXP_4102_Skill02_03"
        },
        TERMEXP_4201_BonusAttack = {
          ContentDE = "Erzeugt [Tobende Donner] bei Zielen, die durch [Sternenlichtabstieg] oder [Milchstraßensturz] Schaden erlitten haben, und verursacht Elektro-Flächenschaden. Es werden maximal 5 Ziele ausgewählt.",
          TextMapId = "TERMEXP_4201_BonusAttack"
        },
        TERMEXP_4201_FallAttack = {
          ContentDE = "Stürzt mit hoher Geschwindigkeit herab und verursacht Elektro-Flächenschaden beim Aufprall. Dieser Angriff wird als Sturzangriff mit Nahkampfwaffen angesehen. Der Einsatz dieser Fähigkeit im Zustand [Xuanjiao-Besessenheit] löst [Drachenrufwolken] aus.",
          TextMapId = "TERMEXP_4201_FallAttack"
        },
        TERMEXP_4201_Marks = {
          ContentDE = "Die Widerschuppe bleibt bestehen, wobei maximal 6 Schuppen gleichzeitig existieren. Die Schuppen werden entfernt, wenn der Zustand [Xuanjiao-Besessenheit] endet.",
          TextMapId = "TERMEXP_4201_Marks"
        },
        TERMEXP_4201_Skill2Buff = {
          ContentDE = "Wenn Fähigkeits-SCH bei einem Ziel verursacht wird, das mit [Donnernder Ansturm] belegt ist, wird zusätzlicher Elektro-SCH verursacht. Kann alle 3 Sek. beim gleichen Ziel ausgelöst werden.",
          TextMapId = "TERMEXP_4201_Skill2Buff"
        },
        TERMEXP_4201_Summon = {
          ContentDE = [[
Immun gegen Trefferstarre. Xuanjiao schwebt um [Yuming] herum und verursacht beim Kontakt mit Gegnern alle 2 Sekunden einmal Elektro-SCH pro Gegner.
 Xuanjiao kann den SCH, den [Yuming] erleidet, absorbieren. Wenn die absorbierte Menge einen festgelegten Prozentsatz von [Yuming]s max. LP erreicht, endet [Xuanjiao-Besessenheit].]],
          TextMapId = "TERMEXP_4201_Summon"
        },
        TERMEXP_4201_SuperFallAttack = {
          ContentDE = "Verbraucht alle [Widerschuppen], um den verursachten SCH für sich selbst und Verbündete zu erhöhen.\n Stürzt anschließend mit hoher Geschwindigkeit herab und verursacht Elektro-Flächenschaden beim Aufprall. Dieser Angriff wird als Sturzangriff mit Nahkampfwaffen angesehen. Der Einsatz dieser Fähigkeit im Zustand [Xuanjiao-Besessenheit] löst [Drachenrufwolken] aus.",
          TextMapId = "TERMEXP_4201_SuperFallAttack"
        },
        TERMEXP_4202_Skill01 = {
          ContentDE = "[Barriere] blockt Frontalangriffe ab und absorbiert deren Schaden. Sie verschwindet, sobald sie Schaden in Höhe von 100 % der Randys max. LP absorbiert hat.",
          TextMapId = "TERMEXP_4202_Skill01"
