        },
        TextMap_AnswerDetail_100003 = {
          ContentDE = "Der Bühnenvorhang-Fetzen weist auf das Galea-Theater, und das unheilvolle, opernhafte Summen des Täters verstärkt diesen Verdacht. Das Theater verdient eine gründliche Untersuchung.",
          TextMapId = "TextMap_AnswerDetail_100003"
        },
        TextMap_AnswerDetail_100004 = {
          ContentDE = "Der Täter floh nach Südwesten – und die einzige Einrichtung in dieser Richtung mit nennenswerten Phoxichor-Vorräten ist die lokale Fabrik. Sie verdient eine gründliche Untersuchung.",
          TextMapId = "TextMap_AnswerDetail_100004"
        },
        TextMap_AnswerDetail_100005 = {
          ContentDE = "Das Versteck des Täters war mit Bühnenrequisiten dekoriert, und während des Angriffs summte er eine Opernmelodie. Diese Hinweise deuten darauf hin, dass er ein Opernliebhaber sein könnte. Vielleicht liegt der Schlüssel zu seiner Identität in der Melodie selbst.",
          TextMapId = "TextMap_AnswerDetail_100005"
        },
        TextMap_AnswerDetail_100101 = {
          ContentDE = "Basierend auf der Position des Mondes zur Tatzeit wird der Angriff auf zwischen 4 und 5 Uhr morgens geschätzt.",
          TextMapId = "TextMap_AnswerDetail_100101"
        },
        TextMap_AnswerDetail_100201 = {
          ContentDE = "Die frisch gebrochene Wetterfahne ist vermutlich gesplittert, als der Täter auf dem Dach landete. Zusammen mit weiteren Hinweisen könnte sie zusätzliche Informationen liefern.",
          TextMapId = "TextMap_AnswerDetail_100201"
        },
        TextMap_AnswerDetail_100202 = {
          ContentDE = "Das Fundament der Wetterfahne ist nach Südwesten verbogen. Zusammen mit weiteren Hinweisen könnte sie zusätzliche Informationen liefern.",
          TextMapId = "TextMap_AnswerDetail_100202"
        },
        TextMap_AnswerDetail_100203 = {
          ContentDE = "Bruchmuster der Fahne und ihres Fundaments passen perfekt zusammen – sie wurde während der Flucht über die Dächer abgerissen.\n Die zusammengesetzte Fahne zeigt nach Südwesten und bestätigt die Fluchtrichtung.",
          TextMapId = "TextMap_AnswerDetail_100203"
        },
        TextMap_AnswerDetail_100301 = {
          ContentDE = "In dieser Nacht summte der Täter mit rauer Stimme eine Opernmelodie. Könnte es sich um einen Sänger oder einfach nur um einen Musikliebhaber handeln?",
          TextMapId = "TextMap_AnswerDetail_100301"
        },
        TextMap_AnswerDetail_100302 = {
          ContentDE = "Am Tatort wurde ein Stück Samtvorhang gefunden – identisch mit dem Vorhang, der im Galea-Theater verwendet wird. Könnte dies auf eine Verbindung zum Theater hindeuten? Um diesen Zusammenhang zu bestätigen, sind weitere Beweise erforderlich.",
          TextMapId = "TextMap_AnswerDetail_100302"
        },
        TextMap_AnswerDetail_100303 = {
          ContentDE = "Der Bühnenvorhang-Fetzen weist auf das Galea-Theater, und das opernhafte Summen des Täters verstärkt diesen Verdacht. Das Theater verdient eine gründliche Untersuchung.",
          TextMapId = "TextMap_AnswerDetail_100303"
        },
        TextMap_AnswerDetail_100401 = {
          ContentDE = "Der Täter floh in Richtung Südwesten – ein Gebiet mit vielen Wohnhäusern, Schulen und einer Fabrik. Die Untersuchung von Rhythm ist ins Stocken geraten, da das Gebiet ohne weitere Hinweise zu groß ist. Es sind weitere Hinweise erforderlich, um die Suche einzugrenzen.",
          TextMapId = "TextMap_AnswerDetail_100401"
        },
        TextMap_AnswerDetail_100402 = {
          ContentDE = "In der Nähe des Tatorts wurden Spuren von Phoxichor im Schnee entdeckt. Es wurden jedoch keine Lecks aus nahegelegenen Anlagen gemeldet. Es wäre besser, Rhythm wegen der Falldetails zu konsultieren, um weitere Hinweise zu sammeln.",
          TextMapId = "TextMap_AnswerDetail_100402"
        },
        TextMap_AnswerDetail_100403 = {
          ContentDE = "Du erinnerst dich an einen stechenden Geruch, der dem Täter anhaftete – ein eindeutiges Zeichen starker Phoxichor-Kontamination. Nur sehr wenige Standorte in Icelake könnten solche Werte aufweisen. Abgleich mit anderen Hinweisen könnte die Spur eingrenzen.",
          TextMapId = "TextMap_AnswerDetail_100403"
        },
        TextMap_AnswerDetail_100404 = {
          ContentDE = "Der Täter floh nach Südwesten – und die einzige Einrichtung in dieser Richtung mit nennenswerten Phoxichor-Vorräten ist die lokale Fabrik. Könnte die sein Versteck sein? Sie verdient eine gründliche Untersuchung.",
          TextMapId = "TextMap_AnswerDetail_100404"
        },
        TextMap_AnswerDetail_100501 = {
          ContentDE = "In der Kanalisation fandest du Samtvorhänge und Schaufensterpuppen, die wie Schauspieler mitten in einer Aufführung posierten. Wer immer diese Szene arrangierte, sieht sich selbst womöglich als Teil der Vorstellung. Abgleich mit anderen Hinweisen – vielleicht offenbart es die wahre Identität dieser Person.",
          TextMapId = "TextMap_AnswerDetail_100501"
        },
        TextMap_AnswerDetail_100502 = {
          ContentDE = "In dieser Nacht summte der Täter mit rauer Stimme eine Opernmelodie. Könnte es sich um einen Sänger oder einfach nur um einen Musikliebhaber handeln?",
          TextMapId = "TextMap_AnswerDetail_100502"
        },
        TextMap_AnswerDetail_100503 = {
          ContentDE = "Das Versteck des Täters war mit Bühnenrequisiten dekoriert, und während des Angriffs summte er eine Opernmelodie. Diese Hinweise deuten darauf hin, dass er ein Opernliebhaber sein könnte. Vielleicht liegt der Schlüssel zu seiner Identität in der Melodie selbst.",
          TextMapId = "TextMap_AnswerDetail_100503"
        },
        TextMap_AnswerDetail_200101 = {
          ContentDE = "Herr Buck trinkt in der Asphodel nur Saft und Milch. Er verträgt keinen Alkohol – schon ein einziger Schluck reicht aus, um ihn bewusstlos zu machen.",
          TextMapId = "TextMap_AnswerDetail_200101"
        }
      }
    end
  },
  {
    MinKey = "TextMap_AnswerDetail_200102",
    MaxKey = "Title_10057",
    Loader = function()
      return {
        TextMap_AnswerDetail_200102 = {
          ContentDE = "Jemand hat heimlich Alkohol in Herr Bucks Milch gemischt – eindeutig mit der Absicht, ihn bewusstlos zu machen. Auf dem Krug ist noch ein klebriger Handabdruck in Kindergröße zu sehen.",
          TextMapId = "TextMap_AnswerDetail_200102"
        },
        TextMap_AnswerDetail_200103 = {
          ContentDE = "Kleine Fußspuren führen von der Straße zu Herr Bucks Fensterbank – ein deutliches Zeichen dafür, dass ein Kind eingebrochen ist und etwas im Haus angerichtet hat.",
          TextMapId = "TextMap_AnswerDetail_200103"
        },
        TextMap_AnswerDetail_200104 = {
          ContentDE = "Einige Popcornstücke liegen in der Nähe der Fußspuren – vermutlich blieben sie am Eindringling hängen und fielen ab, als er durchs Fenster kletterte.",
          TextMapId = "TextMap_AnswerDetail_200104"
        },
        TextMap_AnswerDetail_200105 = {
          ContentDE = "Ein zitternder Charon-Junge verkauft Bier, Popcorn, Opernkarten und Poster in der Nähe des Ticketschalters des Galea-Theaters.",
          TextMapId = "TextMap_AnswerDetail_200105"
        },
        TextMap_AnswerDetail_200106 = {
          ContentDE = "Ein bestimmtes Kind, das wusste, dass Buck keinen Alkohol verträgt, schlich sich in sein Haus und mischte ihm etwas in die Milch – gerade genug, um ihn bewusstlos zu machen. Deshalb ist Buck in letzter Zeit ungewöhnlich früh eingeschlafen.",
          TextMapId = "TextMap_AnswerDetail_200106"
        },
        TextMap_AnswerDetail_200107 = {
          ContentDE = "Ein betrunkener Mann liegt zusammengesackt neben dem Mülleimer, stinkend nach Alkohol. Er passt nicht zum Profil eines Kindes und scheint auch nicht der Typ zu sein, der sein Getränk verschenkt.",
          TextMapId = "TextMap_AnswerDetail_200107"
        },
        TextMap_AnswerDetail_200108 = {
          ContentDE = "Ein kleines Mädchen, das seinen strengen Vater ständig um Popcorn bittet. Sie passt zwar zum Profil eines Kindes, aber es ist klar, dass das Popcorn unter Bucks Fenster nicht von ihr stammt.",
          TextMapId = "TextMap_AnswerDetail_200108"
        },
        TextMap_AnswerDetail_200201 = {
          ContentDE = "Vor sechzehn Jahren inszenierte Sigs Freund Donat eine Entführung. Das Opfer, Enola, kam während des Vorfalls unerwartet ums Leben. Sig wurde zum Tode verurteilt.",
          TextMapId = "TextMap_AnswerDetail_200201"
        },
        TextMap_AnswerDetail_200202 = {
          ContentDE = "Giselle, die Phoxjägerin, diente einst in der Eskorte. Doch vor sechzehn Jahren trat sie zurück, nachdem ein Urteil sie in Konflikt mit ihrem Vorgesetzten brachte.",
          TextMapId = "TextMap_AnswerDetail_200202"
        },
        TextMap_AnswerDetail_200203 = {
          ContentDE = "Violet, Sigs Schwester, verließ Icelake vor sechzehn Jahren. Nun scheint sie zurückgekehrt zu sein. Jemand hat ein violettes Band auf seinem Grab hinterlassen, höchstwahrscheinlich sie.",
          TextMapId = "TextMap_AnswerDetail_200203"
        },
        TextMap_AnswerDetail_200204 = {
          ContentDE = "Violetta trägt bei jedem Auftritt ein violettes Band. Sie sagt, es sei ein Andenken an eine liebe Freundin. Es ist zu ihrem Erkennungszeichen geworden.",
          TextMapId = "TextMap_AnswerDetail_200204"
        },
        TextMap_AnswerDetail_200205 = {
          ContentDE = "Rosalind, die Tochter von Earl Magnus, wird vermisst – vermutlich entführt. Ihre Eltern hatten ihr kürzlich einen Gesangslehrerin engagiert.",
          TextMapId = "TextMap_AnswerDetail_200205"
        },
        TextMap_AnswerDetail_200206 = {
          ContentDE = "Eine von Violettas Schülerinnen wurde entführt. Der Erpresserbrief nimmt in rätselhafter Weise Bezug auf Ereignisse vor sechzehn Jahren.",
          TextMapId = "TextMap_AnswerDetail_200206"
        },
        TextMap_AnswerDetail_200207 = {
          ContentDE = "Vor sechzehn Jahren gehörte Giselle zu dem Team, das den Entführungsfall untersuchte. Das Urteil erschütterte sie so sehr, dass sie sich entschloss, aus der Eskorte auszutreten.",
          TextMapId = "TextMap_AnswerDetail_200207"
        },
        TextMap_AnswerDetail_200208 = {
          ContentDE = "Die violetten Bänder sind in Farbe und Stil vollkommen identisch. In Verbindung mit ihren fast gleichlautenden Namen wird deutlich, dass Violetta und Violet in enger Beziehung stehen.",
          TextMapId = "TextMap_AnswerDetail_200208"
        },
        TextMap_AnswerDetail_200209 = {
          ContentDE = "Es ist höchst wahrscheinlich, dass Violettas vermisste Schülerin Rosalind ist, die Tochter von Graf Magnus. Der Hinweis des Erpresserbriefs auf die Ereignisse vor sechzehn Jahren deutet auf eine tiefere Verbindung zu Violetta selbst hin.",
          TextMapId = "TextMap_AnswerDetail_200209"
        },
        TextMap_AnswerDetail_200210 = {
          ContentDE = "Rosalinds Entführung steht eindeutig in Zusammenhang mit dem Fall von damals, und Violetta weiß genau, was wirklich geschehen ist.",
          TextMapId = "TextMap_AnswerDetail_200210"
        },
        TextMap_AnswerDetail_200211 = {
          ContentDE = "Der alte Fall verbarg Wahrheiten, die Violetta schon lange kannte. Giselle inszenierte die jüngste „Entführung” ihrer Schülerin, um diese Wahrheiten ans Licht zu bringen.",
          TextMapId = "TextMap_AnswerDetail_200211"
        },
        TextMap_AnswerDetail_200301 = {
          ContentDE = "Auf der Fensterbank steht ein Strauß Skylilien, deren Blütenblätter noch vom Morgentau feucht sind – jemand muss sie erst kürzlich dort hingestellt haben.",
          TextMapId = "TextMap_AnswerDetail_200301"
        },
        TextMap_AnswerDetail_200302 = {
          ContentDE = "Diese ruhige Ecke von EverSpring ist unberührt geblieben. Keine Fußspuren außer Linglings ... nichts ist fehl am Platz.",
          TextMapId = "TextMap_AnswerDetail_200302"
        },
        TextMap_AnswerDetail_200303 = {
          ContentDE = "Nahe der Eingangstür gefunden, ist das Album voller Familienfotos. Auf einem davon hält eine jüngere Lingling einen Strauß Skylilien in der Hand und lächelt neben ihrer Großmuter – direkt vor diesem Haus.",
          TextMapId = "TextMap_AnswerDetail_200303"
        },
        TextMap_AnswerDetail_200304 = {
          ContentDE = "Ein Brief, der erklärt, dass Linglings Eltern sie wegen der Arbeit aus Haojing zurück nach Nebelkai brachten – vorübergehend wohnen sie wieder im alten Arbeiterwohnheim, das einst ihr Zuhause war.",
          TextMapId = "TextMap_AnswerDetail_200304"
        },
        TextMap_AnswerDetail_200305 = {
          ContentDE = "Jemand hat den Blumenstrauß zurückgelassen, ohne eine einzige Spur zu hinterlassen.",
          TextMapId = "TextMap_AnswerDetail_200305"
        },
        TextMap_AnswerDetail_200306 = {
          ContentDE = "Der „Geist“ kannte dieses bescheidene kleine Haus gut und schätzte das Album sehr. Vielleicht gehörte er einst zu dieser Familie.",
          TextMapId = "TextMap_AnswerDetail_200306"
        },
        TextMap_AnswerDetail_200307 = {
