        UIGuide_TongLv_1 = {
          ContentDE = "Einige figure besitzen einzigartige Resonanzwaffen. Diese Waffen steigen mit dem figur auf und können nicht separat ersetzt oder verbessert werden, können aber mit Dämonenkeilen ausgerüstet werden.",
          TextMapId = "UIGuide_TongLv_1"
        },
        UIGuide_TrainingGround_1 = {
          ContentDE = "Die Sandreich-Meditation ermöglicht es dir, frühere Gegner in einer kontrollierten Umgebung erneut zu bekämpfen und deine Kampffähigkeiten zu trainieren.",
          TextMapId = "UIGuide_TrainingGround_1"
        },
        UIGuide_TrainingGround_2 = {
          ContentDE = "Im <H>Grobkorn-Wirbel</> der Sandreich-Meditation findest du Kampfnachschub wie <H>Munitionskisten</>, <H>Sal Volatil</> und <H>kognitives Sal Volatil</>, um dir den Kampf zu erleichtern.",
          TextMapId = "UIGuide_TrainingGround_2"
        },
        UIGuide_TrainingGround_3_PC = {
          ContentDE = "Öffne <H>oben rechts</> das <H>Bewaffnungsmenü</>, um schnell zwischen den zu testenden <H>Figuren</> zu wechseln.",
          TextMapId = "UIGuide_TrainingGround_3_PC"
        },
        UIGuide_TrainingGround_3_Phone = {
          ContentDE = "Öffne <H>oben links</> das <H>Bewaffnungsmenü</>, um schnell zwischen den zu testenden <H>Figuren</> zu wechseln.",
          TextMapId = "UIGuide_TrainingGround_3_Phone"
        },
        UIGuide_TrainingGround_4_PC = {
          ContentDE = "Drücke &OpenMenu& und wähle <H>Verlassen</> aus, um zu gehen.",
          TextMapId = "UIGuide_TrainingGround_4_PC"
        },
        UIGuide_TrainingGround_4_Phone = {
          ContentDE = "Wähle <H>Sandreich-Meditation verlassen</> im <H>Menü</> <H>oben links</>, um zu gehen.",
          TextMapId = "UIGuide_TrainingGround_4_Phone"
        },
        UIGuide_TrialRank_1 = {
          ContentDE = "Erhalte EP durch die Verbesserung von Figuren, Waffen, Geniemon und Dämonenkeilen oder durch das Abschließen von Aufträgen, um deine Prüfungsstufe zu erhöhen.",
          TextMapId = "UIGuide_TrialRank_1"
        },
        UIGuide_TrialRank_2 = {
          ContentDE = "Die Erhöhung der Prüfungsstufe gewährt wertvolle Belohnungen und mächtige Buffs.",
          TextMapId = "UIGuide_TrialRank_2"
        },
        UIGuide_TriggerEffect_1 = {
          ContentDE = "<H>Figuren</> besitzen Elementtypen. Es gibt sechs Elemente: <H>Hydro, Pyro, Anemo, Elektro, Lumino und Umbro</>. Jedes Element hat einen eigenen <H>Bonuseffekt</>, der als Debuff angewendet wird und <H>DoT</> verursacht:\n Hydro: Fügt Hydro-DoT zu.\n Pyro: Fügt Pyro-DoT zu.\n Elektro: Fügt Elektro-DoT zu.\n Anemo: Fügt Anemo-DoT zu.\n Lumino: Fügt Lumino-DoT zu und verlängert die verbleibende Dauer aller aktiven Bonuseffekt.\n Umbro: Fügt Umbro-DoT zu und verlangsamt die Kampfhaltung-Regeneration des Ziels.",
          TextMapId = "UIGuide_TriggerEffect_1"
        },
        UIGuide_TriggerEffect_2 = {
          ContentDE = "<H>Waffen</> haben physisches Element: <H>Hieb, Durchdringung und Erschütterung</>. Ihre <H>Bonuseffekte</> verstärken den Schaden oder verlangsamen die Erholung der Kampfhaltung:\n Hieb: Verursacht mehr Schaden am <H>Schild</> des Ziels.\n Durchdringung: Verursacht mehr Schaden an den <H>LP</> des Ziels.\n Erschütterung: Schwächt effektiv die <H>Kampfhaltung</> des Ziels.",
          TextMapId = "UIGuide_TriggerEffect_2"
        },
        UIGuide_TriggerEffect_3 = {
          ContentDE = "Wenn du Schaden mit einer Waffe oder bestimmten Fähigkeiten verursachst, besteht eine Chance, einen elementaren <H>Bonuseffekt</> auszulösen. Die Chance basiert auf der <H>Auslöserate</> der Waffe.",
          TextMapId = "UIGuide_TriggerEffect_3"
        },
        UIGuide_TurnTable = {
          ContentDE = "Ein gewöhnlicher Türschlossmechanismus. Lass alle weißen Bereiche innerhalb der vorgegebenen Zeit aufleuchten, um diese Art von magischem Schloss zu öffnen.",
          TextMapId = "UIGuide_TurnTable"
        },
        UIGuide_ValveMechanism = {
          ContentDE = "Ein gewöhnlicher Türschlossmechanismus. Bewege den Zeiger innerhalb des Zeitlimits zum Endpunkt, um das magische Schloss zu entriegeln.",
          TextMapId = "UIGuide_ValveMechanism"
        },
        UIGuide_WIKI_01 = {
          ContentDE = "Während der Dialoge erscheint unten rechts der <H>Eintrag ansehen</>-Button. Du kannst darauf tippen, um die im Dialog vorkommenden Stichwörter und deren ausführliche Beschreibungen anzusehen.",
          TextMapId = "UIGuide_WIKI_01"
        },
        UIGuide_WIKI_02 = {
          ContentDE = "Im <H>Atlasipedia</> kannst du alle bisher freigeschalteten Einträge ansehen.",
          TextMapId = "UIGuide_WIKI_02"
        },
        UIGuide_WallJump_PC = {
          ContentDE = "Drücke in der Nähe einer Wand <H>wiederholt</> &Jump&, um an der Wand nach oben zu springen.",
          TextMapId = "UIGuide_WallJump_PC"
        },
        UIGuide_WallJump_Phone = {
          ContentDE = "Tippe in der Nähe einer Wand <H>wiederholt</> auf die Taste, um an der Wand nach oben zu springen.",
          TextMapId = "UIGuide_WallJump_Phone"
        },
        UIGuide_WangXi_1 = {
          ContentDE = "Der Vergessensspalt zersetzt kontinuierlich jedes Lebewesen, das in ihn fällt. Solange du dich in seinem Einflussbereich befindest, sinkt deine LP stetig.",
          TextMapId = "UIGuide_WangXi_1"
        },
        UIGuide_WangXi_2 = {
          ContentDE = "Überall im Vergessensspalt liegen die Wasser des Vergessens. Mit ihnen in Kontakt zu kommen, beschleunigt den LP-Verlust erheblich.",
          TextMapId = "UIGuide_WangXi_2"
        },
        UIGuide_WangXi_3 = {
          ContentDE = "Die richtige Nutzung der von Laternenblüten geschaffenen sicheren Zonen ist entscheidend, um dem Vergessensspalt zu entkommen.",
          TextMapId = "UIGuide_WangXi_3"
        },
        UIGuide_XiQiu_1 = {
          ContentDE = "Nutze den Ziehmodus der Mechanischen Nexus, um die Jishu-Kugeln in ihre passenden Sockel zu ziehen und das Rätsel zu lösen.",
          TextMapId = "UIGuide_XiQiu_1"
        },
        UIGuide_XiaoChuan_1 = {
          ContentDE = "Ein <H>Kanu</> treibt auf den Wassern des Vergessens. Wird es angezündet, erzeugt es eine sichere, sich ständig bewegende Zone um sich herum, die dir hilft, der Zersetzung des Spaltes zu widerstehen. Innerhalb dieser Zone kannst du dich bewegen und LP stetig wiederherstellen.",
          TextMapId = "UIGuide_XiaoChuan_1"
        },
        UIGuide_XingShi_1 = {
          ContentDE = "Klopfe auf eine <H>Erleuchtungsstele</>, um die Mechanismen der Vielfach-Fangjagd-Formation zu aktivieren und die Struktur des Gebiets zu verändern.",
          TextMapId = "UIGuide_XingShi_1"
        },
        UIGuide_YanShi_1 = {
          ContentDE = "Einige Höhleneingänge werden von Felsen blockiert.",
          TextMapId = "UIGuide_YanShi_1"
        },
        UIGuide_YanShi_2 = {
          ContentDE = "Diese Felsen können mit Nah- oder Fernkampfwaffen zerstört werden – Nahkampfangriffe sind effizienter.",
          TextMapId = "UIGuide_YanShi_2"
        },
        UIGuide_ZhanFeng_1 = {
          ContentDE = "Läute das <H>Äolische Klangspiel</>, und es wird auf deinen Wunsch reagieren, verborgene Mechanismen oder Erinnerungen vergangener Tage erwachen lassen.",
          TextMapId = "UIGuide_ZhanFeng_1"
        },
        UIGuide_ZhouYe_1 = {
          ContentDE = "In Huaxu kannst du die Tageszeit über das Menü <H>Zeitzyklus</> ändern.",
          TextMapId = "UIGuide_ZhouYe_1"
        },
        UIGuide_content_203001 = {
          ContentDE = "Während du die Welt erkundest, kannst du auf <H>Geniemon</> treffen. Benutze <H>Leckereien</>, um dich mit ihnen anzufreunden. Geniemon können dein Team im Kampf durch Geniemon-Unterstützung verstärken.",
          TextMapId = "UIGuide_content_203001"
        },
        UIGuide_content_203501 = {
          ContentDE = "In Städten und anderen <H>sicheren Gebieten</>, <H>halte &Skill3& gedrückt</>, um zum Protagonisten zu wechseln, die Umgebung zu erkunden und mit ihr zu interagieren.",
          TextMapId = "UIGuide_content_203501"
        },
        UIGuide_content_203601 = {
          ContentDE = "Du kannst sich den Prüfungen des Vogelgeistes stellen, indem du bei den aufgezeichneten Vogeltürmen meditierst.",
          TextMapId = "UIGuide_content_203601"
        },
        UIGuide_content_203602 = {
          ContentDE = "Nach deinem ersten erfolgreichen Abschluss der Prüfungen erhältst du mit Sternen bewertete Belohnungen. Du kannst diese Prüfungen wiederholen, um höhere Bewertungen zu erreichen und bessere Belohnungen zu erhalten.",
          TextMapId = "UIGuide_content_203602"
        },
