        },
        UI_COMMONPOP_TEXT_100019 = {
          ContentDE = "Nach dem Freischalten kann dieser Gegenstand verkauft oder verbraucht werden. Möchtest du fortfahren?",
          TextMapId = "UI_COMMONPOP_TEXT_100019"
        },
        UI_COMMONPOP_TEXT_100027 = {
          ContentDE = "Du hast keine Belohnungsversuche mehr. Bist du sicher, dass du starten möchtest, obwohl keine Belohnungen verfügbar sind?",
          TextMapId = "UI_COMMONPOP_TEXT_100027"
        },
        UI_COMMONPOP_TEXT_100029 = {
          ContentDE = "Lass die Figur auf Phase %s aufsteigen, um fortzufahren.",
