        },
        UI_COMMONPOP_TEXT_100030 = {
          ContentDE = "Erfordert Prüfungsstufe %s",
          TextMapId = "UI_COMMONPOP_TEXT_100030"
        },
        UI_COMMONPOP_TEXT_100033_1 = {
          ContentDE = "Tastenbelegung nicht zugewiesen",
          TextMapId = "UI_COMMONPOP_TEXT_100033_1"
        },
        UI_COMMONPOP_TEXT_100033_2 = {
          ContentDE = "Bitte gib die gewünschte Tastenbelegung ein.",
          TextMapId = "UI_COMMONPOP_TEXT_100033_2"
        },
        UI_COMMONPOP_TEXT_100034 = {
          ContentDE = "Bitte bestätige die Änderung der Tastenbelegung.",
          TextMapId = "UI_COMMONPOP_TEXT_100034"
        },
        UI_COMMONPOP_TEXT_100035 = {
          ContentDE = "Wird bereits von [%s] verwendet, dessen Funktion nicht geändert werden kann",
          TextMapId = "UI_COMMONPOP_TEXT_100035"
        },
        UI_COMMONPOP_TEXT_100036 = {
          ContentDE = "Diese Taste wird von [%s] verwendet. Vertauschen von Tasten bestätigen.",
          TextMapId = "UI_COMMONPOP_TEXT_100036"
        },
        UI_COMMONPOP_TEXT_100037 = {
          ContentDE = "Bist du sicher, dass du zum Raststätte teleportieren möchtest?",
          TextMapId = "UI_COMMONPOP_TEXT_100037"
        },
        UI_COMMONPOP_TEXT_100038 = {
          ContentDE = "Gegenstand in der Ausrüstung werden nach dem Verkauf automatisch entfernt.",
          TextMapId = "UI_COMMONPOP_TEXT_100038"
        },
        UI_COMMONPOP_TEXT_100044 = {
          ContentDE = "%s wird derzeit von %s verwendet. Tauschen bestätigen?",
          TextMapId = "UI_COMMONPOP_TEXT_100044"
        },
        UI_COMMONPOP_TEXT_100045 = {
          ContentDE = "Toleranzlimit überschritten. Nach dem Hochstufen automatisch entfernt.",
          TextMapId = "UI_COMMONPOP_TEXT_100045"
        },
        UI_COMMONPOP_TEXT_100048 = {
          ContentDE = "Bist du sicher, dass du das Steckenbleiben der Figur beheben möchtest?",
          TextMapId = "UI_COMMONPOP_TEXT_100048"
        },
        UI_COMMONPOP_TEXT_100050 = {
          ContentDE = "%s Dämonenkeil wird entfernt. Fortfahren?",
          TextMapId = "UI_COMMONPOP_TEXT_100050"
        },
        UI_COMMONPOP_TEXT_100051 = {
          ContentDE = "Dein Konto (UID: %d) wurde aufgrund von Verstößen bis %s gesperrt. Du wirst nun abgemeldet.",
          TextMapId = "UI_COMMONPOP_TEXT_100051"
        },
        UI_COMMONPOP_TEXT_100052 = {
          ContentDE = "Dein Konto (UID: %d) wurde für %s bis %s gesperrt. Du wirst jetzt abgemeldet.",
          TextMapId = "UI_COMMONPOP_TEXT_100052"
        },
        UI_COMMONPOP_TEXT_100052_0 = {
          ContentDE = "Verstoß gegen die Nutzungsvereinbarung",
          TextMapId = "UI_COMMONPOP_TEXT_100052_0"
        },
        UI_COMMONPOP_TEXT_100052_1 = {
          ContentDE = "Abnormale Daten festgestellt",
          TextMapId = "UI_COMMONPOP_TEXT_100052_1"
        },
        UI_COMMONPOP_TEXT_100052_2 = {
          ContentDE = "Verwendung von Drittanbieter-Plug-ins",
          TextMapId = "UI_COMMONPOP_TEXT_100052_2"
        },
        UI_COMMONPOP_TEXT_100052_3 = {
          ContentDE = "Unangemessene Sprache",
          TextMapId = "UI_COMMONPOP_TEXT_100052_3"
        },
        UI_COMMONPOP_TEXT_100052_4 = {
          ContentDE = "Rückerstattung für ein minderjähriges Konto",
          TextMapId = "UI_COMMONPOP_TEXT_100052_4"
        },
        UI_COMMONPOP_TEXT_100054_1 = {
          ContentDE = "Bitte gib einen neuen Namen ein.",
          TextMapId = "UI_COMMONPOP_TEXT_100054_1"
        },
        UI_COMMONPOP_TEXT_100054_2 = {
          ContentDE = "Du kannst deinen Namen innerhalb von %d Tagen nicht erneut ändern.",
          TextMapId = "UI_COMMONPOP_TEXT_100054_2"
        },
        UI_COMMONPOP_TEXT_100055 = {
          ContentDE = "Signatur eingeben",
          TextMapId = "UI_COMMONPOP_TEXT_100055"
        },
        UI_COMMONPOP_TEXT_100056 = {
          ContentDE = "Nach der Bestätigung sind keine weiteren Änderungen möglich.",
          TextMapId = "UI_COMMONPOP_TEXT_100056"
        },
        UI_COMMONPOP_TEXT_100057 = {
          ContentDE = "<H>Du kannst dein Geburtsdatum nur einmal ändern.</> Bist du sicher, dass du dein Geburtsdatum auf <H>%s</> ändern möchtest?",
          TextMapId = "UI_COMMONPOP_TEXT_100057"
        },
        UI_COMMONPOP_TEXT_100058 = {
          ContentDE = "Bist du sicher, dass du die Erkundung jetzt beenden möchtest?",
          TextMapId = "UI_COMMONPOP_TEXT_100058"
        },
        UI_COMMONPOP_TEXT_100058_2 = {
          ContentDE = "Belohnungen und Punkte werden basierend auf deinem aktuellen Erkundungsfortschritt berechnet.",
          TextMapId = "UI_COMMONPOP_TEXT_100058_2"
        },
        UI_COMMONPOP_TEXT_100066 = {
          ContentDE = "Ein Kampfbegleiter-Siegel nutzt diese Waffe. Trotzdem verkaufen?",
          TextMapId = "UI_COMMONPOP_TEXT_100066"
        },
        UI_COMMONPOP_TEXT_100066_2 = {
          ContentDE = "Dämonenkeile automatisch ausrüsten? Auf dieser Seite derzeit verwendeten Dämonenkeile werden entfernt.",
          TextMapId = "UI_COMMONPOP_TEXT_100066_2"
        },
        UI_COMMONPOP_TEXT_100067 = {
          ContentDE = "Auto. Ausrüsten nicht möglich: Keine passenden Dämonenkeile gefunden.",
          TextMapId = "UI_COMMONPOP_TEXT_100067"
        },
        UI_COMMONPOP_TEXT_100071 = {
          ContentDE = "Bist du sicher, dass du alle ausstehenden Freundschaftsanfragen ablehnen möchtest?",
          TextMapId = "UI_COMMONPOP_TEXT_100071"
        },
        UI_COMMONPOP_TEXT_100072 = {
          ContentDE = "Du unterliegst derzeit Maßnahmen zum Schutz vor Spielsucht. Gemäß den Vorschriften zur Prävention von Online-Spielsucht bei Minderjährigen dürfen Konten von Minderjährigen nur an Freitagen, Samstagen, Sonntagen sowie an gesetzlichen Feiertagen jeweils von 20:00 bis 21:00 Uhr für eine Stunde online sein. Bitte geh verantwortungsbewusst mit deiner Spielzeit um und spiele maßvoll.",
          TextMapId = "UI_COMMONPOP_TEXT_100072"
        },
        UI_COMMONPOP_TEXT_100073 = {
          ContentDE = "Dein Konto (UID: %d) wurde auf einem anderen Gerät angemeldet und du wirst hier in Kürze abgemeldet.",
          TextMapId = "UI_COMMONPOP_TEXT_100073"
        },
        UI_COMMONPOP_TEXT_100074 = {
          ContentDE = "Verbindung fehlgeschlagen. Verbindung zum Server nicht möglich. Bitte überprüfe dein Netzwerk.",
          TextMapId = "UI_COMMONPOP_TEXT_100074"
        },
        UI_COMMONPOP_TEXT_100075 = {
          ContentDE = "Das Spiel muss neu gestartet werden, damit die Sprachänderung wirksam wird. Möchtest du jetzt neu starten?",
          TextMapId = "UI_COMMONPOP_TEXT_100075"
        },
