        UI_SPECIALPOP_COMMON_TITLE = {
          ContentDE = "Bitte wähle einen Aufgabemodus:",
          TextMapId = "UI_SPECIALPOP_COMMON_TITLE"
        },
        UI_SPECIALPOP_TEXT_CONTENT_1_1 = {
          ContentDE = "1. Erhalte alle Belohnungen der Haupthandlung sowie ausgewählte Nebenaufträge-Belohnungen für Kapitel Nachtfahrer – 1 und erhalte frühen Zugang zu Kapitel Dämmerung – 1.\n 2. Schalte Aufträge, Schmieden, Geniemon-Fütterung, Angeln, Nocturne-Echos, Mystisches Labyrinth, Gesprächswellen und weitere Funktionen vorzeitig frei. Empfohlen für Spieler, die bereits mit den Spielsystemen vertraut sind.\n \n <H>Hinweise</>\n 1. Tutorials für diese Funktionen werden ebenfalls übersprungen, können aber teilweise später im Tutorial-Bildschirm angesehen werden.\n 2. Das Vorspulen zu Kapitel Dämmerung kann den Ablauf bestimmter Story-Ereignisse beeinflussen.\n 3. Du kannst die Hauptghandlung von Kapitel Nachtfahrer – 1 weiterhin abschließen, aber die Auftrag-Belohnungen werden nicht erneut vergeben. Einige Nebenaufträge und interessante Punkte werden erst nach Abschluss des Kapitels freigeschaltet.",
          TextMapId = "UI_SPECIALPOP_TEXT_CONTENT_1_1"
        },
        UI_SPECIALPOP_TEXT_CONTENT_1_2 = {
          ContentDE = "1. Setze die Haupthandlung dieses Kapitels fort, um die vollständige narrative Erfahrung zu erhalten.\n 2. Die Systeme werden nach und nach freigeschaltet, jeweils mit einem Tutorial, das neuen Spielern den Einstieg erleichtert.",
          TextMapId = "UI_SPECIALPOP_TEXT_CONTENT_1_2"
        },
